\section*{\label{sec:appendix_entropyScaling} Appendix A: Entropy Scaling for Viscosity and Diffusion Coefficients} 


Based on the (dimensionless) residual entropy profile, the viscosity and self-diffusion coefficient profiles can be determined using ansatz functions according to 
%
\begin{subequations}
\begin{equation} \label{eq:poly3}
  \ln \left(\frac{\eta^\mathrm{entr. scal.}}{\eta_\mathrm{ref}}\right)= \sum_{i}^{N} x_i A_i + \sum_{i}^{N} \frac{x_i m_i}{\tilde{m}} B_i s_\mathrm{res}^\#   + \sum_{i}^{N} \frac{x_i m_i}{\tilde{m}} C_i  \left(s_\mathrm{res}^\#\right)^2  + \sum_{i}^{N} \frac{x_i m_i}{\tilde{m}} D_i \left(s_\mathrm{res}^\#\right)^3
\end{equation}
\begin{equation}
  \ln \left(\frac{\rho D_i^{\text {self}, 0}}{\rho D_{i, \mathrm{ref}}^{\text {self},0}}\right)=  A_i+B_i s_\mathrm{res}^\#-C_i\left(1-\exp \left(s_\mathrm{res}^\#\right)\right)\left(s_\mathrm{res}^\#\right)^2 -D_i\left(s_\mathrm{res}^\#\right)^4  -E_i\left(s_\mathrm{res}^\#\right)^8
  \end{equation}
\end{subequations}
where the dependence on the position of the quantities $\eta^\mathrm{entr. scal.}(\rb)$, $D_i^{\text {self}, 0}(\rb)$, $x_i(\rb)$ and $s_\mathrm{res}^\#(\rb)$ is not shown explicitly for clarity. The ansatz functions are analogous to those in homogeneous systems \citep{loetgeringlin2018pure,hopp2018self,hopp2019erratum,stierle2021hydrodynamic}. Importantly, the parameters $A_i, B_i, C_i, D_i$, and $E_i$ were fitted to transport coefficients in homogeneous systems \citep{loetgeringlin2018pure,hopp2018self} and can be used directly in inhomogeneous systems. Thus, transport coefficients of inhomogeneous systems are not required as input to the generalized entropy scaling approach. 
%
The references for viscosity and the self-diffusion coefficient are the Chapman-Enskog properties $\eta_\mathrm{ref}=\eta_\mathrm{CE}$ and $D_{i,\mathrm{ref}}^{\text {self},0}=D_{i,\mathrm{CE}}^{\text {self},0}$, given by \citep{chapman1990mathematical,hirschfelder1967molecular}
%
  \begin{subequations}
        \begin{align}
    \eta_{\mathrm{CE}}=&\sum_{i=1}^{N_{\mathrm{c}}} \frac{x_i \eta_{\mathrm{CE}, i}}{\sum_j^{N_{\mathrm{c}}} x_j \phi_{i j}} \\
    \eta_{\mathrm{CE}, i}=&\frac{5}{16} \frac{\sqrt{\frac{\mw_i k_{\mathrm{B}} T}{N_{\mathrm{A}} \pi}}}{\sigma_i^2 \Omega_i^{(2,2)\#}} \\
    \phi_{i j}=&\frac{\left(1+\sqrt{\frac{\eta_{\mathrm{CE}, i}}{\eta_{\mathrm{CE}, j}} \sqrt[4]{\frac{\mw_j}{\mw_i}}}\right)^2}{\sqrt{8\left(1+\frac{\mw_i}{\mw_j}\right)}} \\
    \rho D_{i, \mathrm{CE}}^{\mathrm{self}, 0}=&\frac{3}{8} \frac{\sqrt{\frac{\mathrm{R} T}{\pi \mw_i}}}{\sigma_i^2 \Omega_i^{(1,1)\#}}
  \end{align}
\end{subequations}
%
where the dimensionless collision integrals, $\Omega^{(1,1)\#}$ and $\Omega^{(2,2)\#}$, are determined from an empirical correlation \citep{neufeld1972empirical}, $N_\mathrm{A}$ is the Avogadro number, and $R$ is the universal gas constant. 

The Maxwell-Stefan diffusion coefficients in the  mixture, $D_{ij}$, are estimated from the self-diffusion coefficients, $D_i^{\text {self}, 0}$.  
The relation between the pure-component self-diffusion coefficient and the self-diffusion coefficient at infinite dilution can be estimated as reported in unpublished work reported by \citet{stierle2021hydrodynamic} according to 
\begin{equation}
  D_i^{\mathrm{self},\infty} = D_j^{\mathrm{self},0} \left( \frac{d_j^\mathrm{eff}}{d_i^\mathrm{eff}} \right)^{2.23}
\end{equation}
%
where effective molecular diameters, $d_i^\mathrm{eff}$, are determined from liquid densities at the normal boiling point for each pure component $i$ as 
%
\begin{equation}
  d_i^\mathrm{eff} = \left( \rho_i^\mathrm{pure}(T_i^\mathrm{sat}, p\stst) \right)^{-\tfrac{0.71}{3}}
\end{equation}
%
with the saturation temperature $T_i^\mathrm{sat}(p\stst)$ and the pressure $p\stst=\SI{1.01325}{\bar}$ at the normal boiling point.
The self-diffusion coefficient in the mixture (or \emph{tracer} diffusion coefficient) is calculated according to \citet{liu2011predictive}
%
\begin{equation}
  \frac{1}{D_i^\mathrm{self}(\mathbf{x})} = \frac{x_i}{D_i^{\mathrm{self},0}} + \frac{(1 - x_i)}{D_i^{\mathrm{self},\infty}}
\end{equation}
%
The Maxwell-Stefan binary diffusion coefficient is determined based on the Darken equation \citep{darken1948diffusion,sridhar2010commentary} according to
%
\begin{equation}
  D_{ij}(\mathbf{x}) = \left( x_i D_j^\mathrm{self}(\mathbf{x}) + x_j D_i^\mathrm{self}(\mathbf{x}) \right) 
\end{equation}
%

