\section{Link to cubic number fields}

\subsection{Splitting and cubic discriminants}

The link between cubic fields and Eisenstein discriminants is the following \cite[Thm 3.3]{Stevenhagen1996}. 

\begin{Prop}\label{Prop: Stevenhagen}
    Suppose $d\in\CD$. If there exists a real cubic field of discriminant $4d$, then $d\in\CE$. 
    Conversely, suppose $d\in\CE$. Then the following are equivalent
    \begin{enumerate}
        \item $4d$ is the discriminant of a real cubic field;
        \item The exact sequence (\ref{exact sequence}) splits.
    \end{enumerate}
    If the above equivalent conditions hold, then there are in fact $h^*(d)$ non-isomorphic cubic fields of discriminant $4d$, where 
    $h^*(d) = \#\Cl(\CO_K)[3]$ is the order of the $3$-torsion subgroup of the class group $\Cl(\CO_K)$.
\end{Prop}





\subsection{Counting cubic discriminants}

Denote by
\begin{align*}
\pi_c(x) &= \#\{\text{non-isomorphic cubic fields of discriminant $4d$, where $d\in\CD$ and $d\leq x$} \} \\
& = \sum_{d\in\CD,\; d\leq x} m(4d)
\end{align*}
the counting function for the relevant cubic fields,
where $m(4d)$ denotes the multiplicity of the cubic discriminant $4d$, i.e. the number of non-isomorphic cubic fields of discriminant $4d$.
By Proposition \ref{Prop: Stevenhagen}, $\pi_c$ should have a similar, but not identical, behaviour to $\pi_\CE$. 

Happily, $\pi_c$ is quite well understood. We have \cite{BST2013, BTTT2024}

\begin{Thm}[Bhargava, Shankar, Taniguchi, Thorner, Tsimmerman]
\label{BSTTT1}
    \[
    \pi_c(x) = \sum_{d\in\CD,\; d\leq x} m(4d) = 
    \frac{1}{3\pi^2}x + C_{5/6} x^{5/6} + O(x^{2/3 + \varepsilon}),
    \]
    where
    $C_{5/6} \approx -0.03761.$
    % \begin{align*}
    %     C_{5/6} &= \frac{4^{11/6}\zeta(1/3)}{35\Gamma(2/3)^3\zeta(5/3)}\prod_{p\geq 3}
    %     \left(1 - \frac{1}{p^2+p+1}\right) \\
    %     &\approx -0.03761.
    % \end{align*}
\end{Thm}

\begin{proof}
    We use \cite[Theorem 1.3]{BTTT2024}. In their notation, we have 
    \begin{align*}
        \pi_c(x) &= N_3^+(4x, \Sigma) \\
        &= C^+(\Sigma)\frac{1}{12\zeta(3)}4x + K^+(\Sigma)\frac{4\zeta(1/3)}{5\Gamma(2/3)^3\zeta(5/3)}(4x)^{5/6} + O_{\epsilon}(x^{2/3+\epsilon}),
    \end{align*}
    where $C^+(\Sigma) = \prod_p C_p$ and $K^+(\Sigma) = \prod_p K_p$ are computed next.

    The local conditions $\Sigma = (\Sigma_p)_p$ are the following. Since $d$ is square-free and $d\equiv 5 \bmod 8$, real cubic fields with discriminant $4d$ are precisely those at which $2$ is the only prime which is totally ramified, by \cite[Lemma 2.1]{Stevenhagen1996}. Thus, by the helpful Table 2 in \cite{BTTT2024}, we get
    \[
    C_2 = \frac{1}{2^2+2+1} = \frac{1}{7}
    \]
    and
    \[
    K_2 = \frac{1+2^{-1/3}}{2^2}\cdot \frac{1-2^{-1/3}}{(1-2^{-5/3})(1+2^{-1})} = \frac{1-2^{-2/3}}{6(1-2^{-5/3})}.
    \]
    At primes $p\geq 3$ we require that $p$ not be totally ramified, giving
    \[
    C_p = 1 - \frac{1}{p^2+p+1}
    \]
    and
    \[
    K_p = 1 - \frac{1+p^{-1/3}}{p^2}\cdot \frac{1-p^{-1/3}}{(1-p^{-5/3})(1+p^{-1})}.
    \]
    Now we compute
    \begin{align*}
        C_1 &= C^+(\Sigma)\frac{1}{3\zeta(3)} = \frac{1}{21} 
        \frac{\prod_p\left(1-\frac{1}{p^2+p+1}\right)}{\left(1 - \frac{1}{2^2+2+1}\right)}
        \prod_p\left(1 - \frac{1}{p^3}\right)\\
        &= \frac{1}{18}\prod_p\left(1-\frac{1}{p^2}\right) = \frac{1}{18\zeta(2)}\\
        &= \frac{1}{3\pi^2}
    \end{align*}
    and, numerically,
    \begin{align*}
        C_{5/6} &= K^*(\Sigma)\frac{4\zeta(1/3)}{5\Gamma(2/3)^3\zeta(5/3)}\cdot 4^{5/6} 
        = \frac{4^{11/6}\zeta(1/3)}{5\Gamma(2/3)^3\zeta(5/3)}\prod_p K_p\\
        &\approx -0.03761.
    \end{align*}
\end{proof}

This is an improvement over the original Davenport-Heilbronn Theorem \cite{DH2}, which only produced the linear term.


A closely related result is

\begin{Thm}[Bhargava, Shankar, Taniguchi, Thorner, Tsimmerman]
\label{BSTTT2}
    \[
    \sum_{d\in\CD,\; d\leq x}\frac{h^*(d)-1}{2} = 
    \sum_{d\in\mathcal{D},\; d\leq x} m(d) = 
    \frac{1}{6\pi^2}x + C^*_{5/6} x^{5/6} + O(x^{2/3+\varepsilon}),
    \]
    where $C^*_{5/6} \approx -0.0386.$
    % \begin{align*}
    %     C^*_{5/6} &= \frac{4\zeta(1/3)}{15\Gamma(2/3)^3\zeta(5/3)}
    %     \frac{1-2^{-4/3}}{1-2^{-5/3}}
    %     \prod_{p\geq 3}
    %     \left(1 - \frac{1}{p^2+p+1}\right) \\
    %     &\approx -0.0386.
    % \end{align*}
\end{Thm}

\begin{proof}
    The first identity follows as the number of cubic fields of fundamental discriminant $d$ equals $(h^*(d)-1)/2$, see \cite[Section 8.1]{BST2013}. The counting function for such fields is again given in  \cite[Theorem 1.3]{BTTT2024}. This time, the relevant local condition is that $2$ is partially split and the remaining primes are not totally ramified, by Lemma \ref{partial split} below. The coefficients are computed using Table 2 in \cite{BTTT2024} as in the proof of Theorem \ref{BSTTT1}.
\end{proof}

\begin{Lem}\label{partial split}
    Let $F/\BQ$ be a totally real cubic field with square-free discriminant $d$. Then $2$ is partially split in $F/\BQ$ if and only if $d\equiv 5 \bmod 8$.
\end{Lem}

\begin{proof}
    First, $2$ is unramified if and only if $d$ is odd.
    It is known (see e.g. \cite{Hasse1930}) that if an odd cubic discriminant $d$ is square-free then $d \equiv 1 \bmod 4$ and the Galois closure of $F$ is $L=F(\sqrt{d})$ and has Galois group $\Gal(L/\BQ)\cong S_3$. 
    Since this is not cyclic, $2$ cannot remain inert in $L$, therefore 2 splits into either 2, 3 or 6 primes $\fp$ in $L/\BQ$ of residue degrees $f(\fp, L/\BQ) = 3, 2$ or $1$, respectively.

    If the residue degrees are $1$ or $3$, then $2$ splits in the quadratic extension $\BQ(\sqrt{d})/\BQ$, hence $d \equiv 1 \bmod 8$.

    Therefore, $d\equiv 5 \bmod 8$ if and only if 2 splits into three primes of residue degree 2 in $L/\BQ$. It remains to show that in this case $2$ is partially split in $F/\BQ$.

    The decomposition groups $D(\fp, L/\BQ)$ have order 2, and only one of them can equal $\Gal(L/F)$. Let $\fp$ be one of the two primes above 2 for which $D(\fp, L/\BQ)=\{1, \sigma\} \neq \Gal(L/F)$. Then $\sigma(\fp\cap\CO_F) \neq \fp\cap\CO_F$ and so $f(\fp, L/F) = 1$ and hence $f(\fp\cap\CO_F, F/\BQ)=2$. It follows that 2 is partially split in $F/\BQ$.
\end{proof}

