\subsection{Unconditional results}

Before presenting our numerical results, we obtain some upper and lower bounds on $\Delta(x)$, which allow for slight improvements in Stevenhagen's Theorem \ref{Stevenhagen1}.

\begin{Thm}\label{Thm: improved Stevenhagen}
    We have the following asymptotic upper and lower bounds on $\pi_{\CE}(x)$.
    \begin{enumerate}
        \item $\displaystyle \pi_\CE(x) \geq (C_{5/6} - 2C^*_{5/6})x^{5/6} + O(x^{2/3 + \varepsilon})$. 


        \item $\displaystyle \pi_\CE(x) \leq \frac{1}{6\pi^2}x + C^*_{5/6}x^{5/6} + O(x^{2/3 + \varepsilon}).$
    \end{enumerate}
\end{Thm}

Since $C_{5/6} - 2C^*_{5/6} \approx 0.0396 > 0$ and $C^*_{5/6} \approx -0.0386 < 0$, this is an improvement on the lower and upper bounds in Theorem~\ref{Stevenhagen1}.

\begin{proof}

First,
\begin{align*}
    \Delta(x) & \geq \sum_{d\in\CE, \; d \leq x}(1-h^*(d)) 
    \geq \sum_{d\in\CD, \; d \leq x}(1-h^*(d)) \\
    & = -\frac{1}{3\pi^2}x - 2C^*_{5/6}x^{5/6} + O(x^{2/3+\varepsilon}) \\
    \Rightarrow \; \pi_\CE(x) & = \pi_c(x) + \Delta(x) \\
    & \geq (C_{5/6} - 2C^*_{5/6})x^{5/6} + O(x^{2/3 + \varepsilon}).
\end{align*}

For an upper bound on $\Delta(x)$, note that $\delta(d)=1 \Rightarrow h^*(d) \geq 3$, so 
\begin{align*}
\Delta(x) &\leq \sum_{d\in\CE,\; d\leq x} \frac{h^*(d)-1}{2} \\
& \leq \sum_{d\in\CD,\; d\leq x} \frac{h^*(d)-1}{2} \\
% & = \frac{2}{3\pi^2}x + \frac{1}{2}C'_{5/6}x^{5/6} + O(x^{2/3 + \varepsilon})
% - \frac{1}{2\pi^2}x + O(x^{1/2 + \varepsilon}) \\
& = \frac{1}{6\pi^2}x + C^*_{5/6}x^{5/6} + O(x^{2/3 + \varepsilon}),
\end{align*}
which gives us
\[
\pi_{\CE}(x) \leq \pi_c(x) + \Delta(x) = 
\frac{1}{2\pi^2}x + \left(C_{5/6} + C^*_{5/6}\right)x^{5/6} + O(x^{2/3 + \varepsilon}).
\]

\end{proof}


