\section{}
The following material includes summarised parts of \cite{Punch2024} (the second author's Honours thesis).

For each value of $d\in\CD$, we describe how to compute $\varepsilon_d\bmod 2\CO_K$. Our technique has been adapted slightly from \cite[Section 7.4]{JacobsonWilliams}, which computes the (non-reduced) fundamental unit. Our strategy is to reduce intermediate values of $\theta$ (the generators for principal ideals in the cycle of reduced ideals) modulo $2\CO_K$ at each step. The original infrastructure technique is summarised below.

Given a principal $\CO_K$-ideal $I=(\theta_{j+1})$ expressed as the $\BZ$-module $[\frac{Q_j}{2},\frac{P_j+\sqrt{d}}{2}]$, we define $\rho(I)$ to be the ideal $(\theta_{j+2})$, which is the $\BZ$-module $[\frac{Q_{j+1}}{2},\frac{P_{j+1}+\sqrt{d}}{2}]$, where $$q_j=\floor{\frac{P_j+\sqrt{d}}{Q_j}},P_{j+1}=q_j Q_j-P_j, Q_{j+1}=\frac{d-P_{j+1}^2}{Q_j}, \text{ and }\theta_{j+2}=\frac{P_{j+1}+\sqrt{d}}{Q_j}\theta_{j+1}.$$ The action of $\rho$ is usually called a \say{reduction}, because applying it to a primitive ideal sufficiently many times will yield a reduced primitive ideal. A binary operation that yields an ideal equivalent to the product of two input ideals will be denoted by $*$ (note that there are several operations that do this). Infrastructure is a baby-step giant-step technique (due to Shanks, which he describes in \cite{shanks1969}), with $\rho$ and $*$ as baby steps and giant steps, respectively. The reader should refer to Algorithm \ref{alg:Infra} for the full description.

\begin{algorithm}
\caption{Infrastructure}\label{alg:Infra}
\begin{algorithmic}
\State \textbf{Input:} a value $d\in\CD$.
\State \textbf{Output:} the fundamental unit $\varepsilon$ in $\BQ(\sqrt{d})$.
\State Put $j\gets 1,\theta_1\gets 1$. \Comment{$(\theta_1)$ can be thought of as the $\BZ$-module $[\frac{2}{2},\frac{1+\sqrt{d}}{2}]$.}
\State Initialize a dictionary of ideals, and add the key-value pair $(Q_0=2,P_0=1):\theta_1=1$.
\While{$\log\theta_{j}<{\sqrt[^4]{d}}$}
    \State Compute $(\theta_{j+1})=\rho((\theta_{j}))$ and its corresponding $\BZ$-module $[\frac{Q_{j}}{2},\frac{P_{j}+\sqrt{d}}{2}]$.
    \State Add $(Q_j,P_j):\theta_{j+1}$ to the dictionary.
    \If{$Q_j=Q_{j-1}$ or $P_j=P_{j-1}$}
        \State Compute $\varepsilon$ using \cite[Theorem 3.13]{JacobsonWilliams}.
        \State \Return $\varepsilon$.
    \EndIf
    \State $j \gets j+1$.
\EndWhile
\State Put $(\mu_1)\gets(\theta_j),k\gets 2$.
\State Compute two more ideals, $(\theta_{j+1})$ and $(\theta_{j+2})$, and their corresponding $\BZ$-modules.
\State Add $(Q_j,P_j):\theta_{j+1}$ and $(Q_{j+1},P_{j+1}):\theta_{j+2}$ to the dictionary.
\While{true}
    \State Put $(\mu_k)\gets(\mu_1)*(\mu_{k-1}')$.
    \State Apply $\rho$ to $(\mu_k)$ until it is a reduced ideal, say $(\mu_k')$, and let $q_k$ and $p_k$ be the values of $Q$ and $P$ when we write $(\mu_k')$ as a $\BZ$-module.
    \If{$(q_k,p_k)$ is in the dictionary}
        \State Set $\theta$ to be the value corresponding to the key $(q_k,p_k)$.
        \State Put $\varepsilon=\frac{\mu_k'}{\theta}$.
        \State \Return $\varepsilon$.
    \EndIf
    \State $k\gets k+1$.
\EndWhile

\end{algorithmic}
\end{algorithm}
\begin{comment}
\begin{itemize}
\item   \textbf{Step 1} Let $\theta_1=1$. Then the ideal $(\theta_1)$ can be thought of as the $\BZ$-module $[\frac{2}{2},\frac{1+\sqrt{d}}{2}]$.
\item   \textbf{Step 2} By repeated application of $\rho$, compute ideals $(\theta_2)=\rho((\theta_1))$, $(\theta_3)=\rho((\theta_2)), \dots$ until we reach $(\theta_{m+2})$, where $m$ is the least integer such that $\log\theta_{m}>{\sqrt[^4]{d}}$. For each ideal, store its generator $\theta_j=\frac{G_{j-2}+B_{j-2}\sqrt{d}}{2}$, and the values of $Q_{j-1}$ and $P_{j-1}$ such that $[\frac{Q_{j-1}}{2},\frac{P_{j-1}+\sqrt{d}}{2}]$ is the corresponding $\BZ$-module. 
\item \textbf{Step 3} If, during Step 2, we find that two consecutive values of $Q$ or $P$ are the same, immediately compute the fundamental unit using \cite[Theorem 3.13]{JacobsonWilliams} and terminate.
\item \textbf{Step 4} Otherwise, put $(\mu_1)=(\theta_m)$ and, for successive integers $k\geq2$, compute $(\mu_k)=(\mu_1)*(\mu_{k-1})$. Again, for each ideal, we need to know its generator and the values of $Q$ and $P$ in the associated $\BZ$-module. This time, we do not need to store previous values.
\item \textbf{Step 5} If, during Step 4, we find that $(\mu_x)=(\theta_y)$ for some integers $x,y$ (by examining the corresponding $\BZ$-modules), then calculate the fundamental unit $\frac{\mu_x}{\theta_y}$ and terminate.
\end{itemize}
\end{comment}

Now, we describe how to modify this procedure. During the baby-step stage of the algorithm, we just reduce each generator modulo $2\CO_K$. The giant step involves composition and reduction on two principal ideals, say $\mathfrak{b}_1=(\theta')$ and $\mathfrak{b}_2=(\theta'')$. The output is a reduced principal ideal $\mathfrak{b}=(\theta)$ and a factor $\frac{1}{\gamma}$ such that $\mathfrak{b}=\frac{1}{\gamma}\mathfrak{b}_1\mathfrak{b}_2=(\frac{1}{\gamma}\theta'\theta'')$. We find $\theta\pmod{2\CO_K}$ by finding $\frac{1}{\gamma}\times\theta'\times\theta''\pmod{2\CO_K}$, so we need some value for $\frac{1}{\gamma}\pmod{2\CO_K}$. While we are guaranteed that $\theta',\theta'',\theta\in\CO_K$, we know only that $\frac{1}{\gamma}\in K$.

However, we can fix this in the following way. In the cycle of reduced principal ideals $\{ \mathfrak{a}_1=(1),\mathfrak{a}_2,\mathfrak{a}_3,\dots\}$, we have that $\theta_j=\frac{G_{j-2}+B_{j-2}\sqrt{d}}{2}$ is a generator for $\mathfrak{a}_j$ (see \cite[Section 3.1]{JacobsonWilliams} for the definitions of $G_j$, $A_j$ and $B_j$).
\begin{Thm} \label{theoremthetanotin2OK}
    For every $j\geq 1$, $\theta_j$ is not in $2\CO_K$.
\end{Thm}
\emph{Proof.}
\begin{itemize}
    \item When $j=1$, $\theta_j=1$.
    \item When $j=2$, $\theta_j=\frac{G_0+B_0\sqrt{d}}{2}$, which is not in $2\CO_K$ because $B_0=1$.
    \item When $j\geq 3$, first observe that, due to \cite[Equation 3.4]{JacobsonWilliams}, $\gcd(G_{j-2},B_{j-2})$ is either 1 or 2. If it is 1, then $\theta_j=\frac{G_{j-2}+B_{j-2}\sqrt{d}}{2}$ must be outside $2\CO_K$. If it is 2, we need to show that $G_{j-2}-B_{j-2}$ (which equals $2A_{j-2}-2B_{j-2}$ by definition of $G_{j-2}$) is $2\pmod{4}$.
    $B_{j-2}$ is even by assumption, and $A_{j-2}$ is coprime to it by \cite[Equation 3.9]{JacobsonWilliams} (and therefore odd), so we are done. \qed
\end{itemize}

It follows that $\theta',\theta'',\theta\in \CO_K \backslash 2\CO_K$. Now, let $\CO_{K,2}$ be the localisation of $\CO_K$ at the prime ideal $2\CO_K$. We know that $\frac{1}{\gamma}$ is $\frac{\theta}{\theta'\theta''}$, and that neither the numerator nor denominator is in $2\CO_K$ (by Theorem \ref{theoremthetanotin2OK} and primality of $2\CO_K$). It follows that $\frac{1}{\gamma}\in \CO_{K,2}$. Putting $B=\CO_K/2\CO_K$ with the canonical reduction map $\CO_K\rightarrow B$, the universal property provides a unique way of extending this map to all of $\CO_{K,2}$. Then, if $\frac{1}{\gamma}=\frac{\alpha}{\beta}$ for some $\alpha\in \CO_K,\beta\in\CO_K\backslash 2\CO_K$, it reduces to $(\alpha+2\CO_K)(\beta+2\CO_K)^{-1}$.

Finally, since we only ever multiply or divide generators, it is sufficient to work in  $(\CO_K/2\CO_K)^*\cong(\BF_4)^*\cong \BZ_3$. Instead of multiplication in $\CO_K/2\CO_K$, it is equivalent to do addition in $\BZ_3$ (more easily achieved on a computer).

Ultimately, this means that the algorithm from \cite[Section 7.4]{JacobsonWilliams} can be performed as usual, except that we substitute elements of $\BZ_3$ for ideal generators from $\CO_K$. Then the result is $0\in \BZ_3$ iff $\varepsilon_d\in 1+2\CO_K$.

This procedure was implemented using the PyOpenCL library for Python. The modified infrastructure technique was implemented in C; for a given value of $d$, it calculated the reduced fundamental unit and returned an element of $\BZ_3$. This C routine was executed on a GPU, with each kernel fed a different value of $d\in \CD$. The outputs were returned to Python, which collated the results. The specific hardware used was a 12th-Gen Intel Core i5-1235U (CPU), and an Intel Iris $\text{X}^\text{e}$ Graphics card (GPU).

Additionally, our implementation uses a nonstandard technique for storing the baby step list. When there is enough memory available, it is best to implement a dictionary as a hash table because lookup is faster in this setting. But on a GPU, each kernel has limited memory, so this is not feasible. Instead, for each ideal, we add the tuple $(Q,P,\theta)$ to an unsorted list. Then, we add $(Q,P)$ to a Bloom filter (see \cite[Method 2]{Bloom} for a description of Bloom filters). Usually, it can quickly answer in the negative when asked if the dictionary contains a given ideal. Rarely, it will give false positives, in which case we must search the whole list. Importantly, it can never give false negatives.

The code that was used for the calculations can be seen at \url{https://github.com/JP1681/Fundamental-units-modulo-2O_K}. The authors acknowledge the help of GPT-4 in implementing the Bloom filter and related search functions.

Earlier, we mentioned that there are several ways of carrying out $*$. One such algorithm is known as NUCOMP, created by Shanks and described by him in \cite{Shanks1988}. Many versions of the algorithm exist (see \cite[Appendix A.1]{JacobsonWilliams}, \cite[Section 3]{JacobsonScheidlerWilliams},\cite[Section 10]{vdP2003},\cite[Section 2]{JacobsonvdP2002}). However, the authors could not get them to perform correctly. For example, they would either give invalid ideals, require more reduction steps than claimed, or produce an incorrect value of $\gamma$.

Ultimately, the authors were able to produce a working version of NUCOMP. Ours is a \say{hybrid}, based on \cite[Section 10]{vdP2003} and \cite[Section 2]{JacobsonvdP2002}, and is described here in full. Our algorithm is the same as in \cite{JacobsonvdP2002}, except that the value of $\gamma$ is calculated using \cite{vdP2003}.

As in those papers, we use binary quadratic forms instead of ideals, and we have two algorithms: NUCOMP, for composing different forms; and its special case NUDUPL, for composing a form with itself. We also describe a third algorithm, which mainly serves to convert between forms and ideals.

For NUCOMP (Algorithm \ref{alg:NUCOMP}), it is sensible to precompute $L=\lvert d \rvert^\frac{1}{4}$. Except where noted, all divisions are done \textbf{without} remainder.

\begin{algorithm}
\caption{NUCOMP}\label{alg:NUCOMP}
\begin{algorithmic}
\State \textbf{Input:} two binary quadratic forms, $\varphi_1=(u_1,v_1,w_1)$ and $\varphi_2=(u_2,v_2,w_2)$, both with discriminant $d$, and the value $L=\lvert d \rvert^\frac{1}{4}$.
\State \textbf{Output:} a near-reduced binary quadratic form $\varphi_3=(u_3,v_3,w_3)$, whose discriminant is $d$, and the value $\gamma\in K$ such that $\varphi_3=\frac{1}{\gamma}\varphi_1 \varphi_2$.
\\
\If {$w_1<w_2$}
    \State Swap $\varphi_1$ and $\varphi_2$.
\EndIf
\State Put $s\gets\frac{v_1+v_2}{2}$, $m\gets v_2-s$.
\State Use the extended Euclidean algorithm to find $(b,c,F)$ such that $bu_2+cu_1=F=\gcd(u_1,u_2)$.
\If {$F\vert s$}
    \State Put $G\gets F, A_x\gets G, B_x\gets mb, B_y\gets \frac{u_1}{G},C_y\gets \frac{u_2}{G}, D_y\gets\frac{s}{G}$.
\Else
    \State Use the extended Euclidean algorithm to find $(x,y,G)$ such that $xF+ys=G=\gcd(F,s)$.
    \State Put $H\gets \frac{F}{G}, B_y\gets \frac{u_1}{G}, C_y\gets \frac{u_2}{G},  D_y\gets\frac{s}{G}$.
    \State Put $l\gets y(bw_1+cw_2)\mod H,B_x\gets\frac{bm+lB_y}{H}$.
\EndIf
\State Put $b_x\gets B_x\mod B_y, b_y\gets B_y, x\gets 1, y\gets 0, z\gets 0$.
\While{$\lvert b_y \rvert > L$ and $b_x\neq 0$}
    \State Divide $b_y$ by $b_x$, then let $q$ and $t$ be the quotient and remainder respectively.
    \State Put $b_y\gets b_x, b_x\gets t, t\gets y-qx, y\gets x, x\gets t, z\gets z+1$.
\EndWhile
\If {$z$ is odd}
    \State Put $b_y\gets -b_y$ and $y\gets -y$.
\EndIf
\State Put $a_x\gets Gx$, $a_y\gets Gy$.
\If {$z\neq0$}
    \State Put $c_x\gets \frac{C_y b_x-mx}{B_y}, Q_1\gets b_y c_x, Q_2\gets Q_1+m, d_x\gets \frac{D_y b_x - w_2 x}{B_y}, Q_3\gets y d_x$.
    \State Put $Q_4 \gets Q_3 + D_y, d_y\gets \frac{Q_4}{x}$.
    \If {$b_x\neq 0$}
        \State Put $c_y\gets \frac{Q_2}{b_x}.$
    \Else 
        \State Put $c_y\gets \frac{c_x d_y - w_1}{d_x}.$
    \EndIf
    \State Put $u_3\gets b_y c_y - a_y d_y, w_3\gets b_x c_x - a_x d_x, v_3\gets G(Q_3+Q_4)-Q_1-Q_2$.
\Else 
    \State Put $Q_1\gets C_y b_x, c_x\gets \frac{Q_1-m}{B_y}, d_x\gets \frac{b_x D_y-w_2}{B_y}, u_3\gets b_y C_y, w_3\gets b_x c_x - G d_x, v_3\gets v_2-2Q_1$.
\EndIf
\State Put $t\gets2u_3,A\gets G(xt+yv_3), B\gets Gy, C\gets t$.
\State Put $\gamma\gets \frac{A+B\sqrt{d}}{C}$, and $\varphi_3\gets (u_3,v_3,w_3)$.
\State \Return $\varphi_3,\gamma$.
\end{algorithmic}
\end{algorithm}
\begin{comment}
\begin{itemize}
\item   \textbf{Step 1} If $w_1<w_2$, swap $\varphi_1$ and $\varphi_2$. Put $s=\frac{v_1+v_2}{2}$. Put $m=v_2-s$.
\item \textbf{Step 2} Use the extended Euclidean algorithm to find $(b,c,F)$ such that $bu_2+cu_1=F=\gcd(u_1,u_2)$. If $F\vert s$, put $G=F$, $A_x=G$, $B_x=mb$, $B_y=\frac{u_1}{G}$, $C_y=\frac{u_2}{G}$, $D_y=\frac{s}{G}$ and go to Step 5. If not, go to Step 3.
\item \textbf{Step 3} Use the extended Euclidean algorithm to find $(x,y,G)$ such that $xF+ys=G=\gcd(F,s)$. Put $H=\frac{F}{G}$, $B_y=\frac{u1}{G}$, $C_y=\frac{u2}{G}$, $D_y=\frac{s}{G}$. 
\item \textbf{Step 4} Put $l=y(bw_1+cw_2)\mod H$, $B_x=\frac{bm+lB_y}{H}$.
\item \textbf{Step 5} Put $b_x=B_x\mod B_y$, $b_y=B_y$, $x=1$, $y=0$, $z=0$. While $\lvert b_y \rvert > L$ and $b_x\neq 0$, repeat Step 5a. Then, go to Step 5b.
\begin{itemize}
    \item \textbf{Step 5a} Divide $b_y$ by $b_x$, then let $q$ and $t$ be the quotient and remainder respectively. Put $b_y=b_x$, $b_x=t$, $t=y-qx$, $y=x$, $x=t$, $z=z+1$.
    \item \textbf{Step 5b} If $z$ is odd, put $b_y=-b_y$ and $y=-y$. Go to Step 6.
\end{itemize}
\item \textbf{Step 6}
Put $a_x=Gx$, $a_y=Gy$. If $z\neq0$, go to Step 7. Otherwise, put $Q_1=C_y b_x$, $c_x=\frac{Q_1-m}{B_y}$, $d_x=\frac{b_x D_y-w_2}{B_y}$, $u_3=b_y C_y$, $w_3=b_x c_x - G d_x$, $v_3=v_2-2Q_1$. Go to Step 8.
