For NUDUPL (Algorithm \ref{alg:NUDUPL}), again we precompute $L=\lvert d \rvert^\frac{1}{4}$. As above, except where noted, all divisions are done \textbf{without} remainder.
\begin{algorithm}
\caption{NUDUPL}\label{alg:NUDUPL}
\begin{algorithmic}
\State \textbf{Input:} a binary quadratic form, $\varphi=(u,v,w)$, with discriminant $d$, and the value $L=\lvert d \rvert^\frac{1}{4}$.
\State \textbf{Output:} a near-reduced binary quadratic form $\varphi_3=(u_3,v_3,w_3)$, whose discriminant is $d$, and the value $\gamma\in K$ such that $\varphi_3=\frac{1}{\gamma}\varphi^2$.
\\
\State Use the extended Euclidean algorithm to find $(x,y,G)$ such that $xu+yv=G=\gcd(u,v)$.
\State Put $A_x\gets G,B_y\gets \frac{u}{G}, D_y\gets\frac{v}{G}$.
\State Put $B_x\gets yw \mod B_y$.
\State Put $b_x\gets B_x, b_y\gets B_y, x\gets 1, y\gets 0, z\gets 0$.
\While{$\lvert b_y \rvert > L$ and $b_x\neq 0$}
    \State Divide $b_y$ by $b_x$, then let $q$ and $t$ be the quotient and remainder respectively.
    \State Put $b_y\gets b_x$, $b_x\gets t$, $t\gets y-qx$, $y\gets x$, $x\gets t$, $z\gets z+1$.
\EndWhile
\If{$z$ is odd}
    \State Put $b_y\gets -b_y$ and $y\gets -y$.
\EndIf
\State Put $a_x\gets Gx$, $a_y\gets Gy$.
\If {$z=0$}
    \State $d_x\gets \frac{b_x D_y - w}{B_y}, u_3\gets b_y^2, w_3\gets b_x^2, v_3\gets v-(b_x+b_y)^2+u_3+w_3, w_3\gets w_3-G d_x$.
\Else
    \State Put $d_x\gets \frac{b_x D_y - w x}{B_y}, Q_1\gets d_x y, d_y\gets Q_1+D_y, v_3\gets G(d_y+Q_1), d_y\gets \frac{d_y}{x}, u_3\gets b_y^2$.
    \State Put $w_3\gets b_x^2, v_3\gets v_3-(b_x+b_y)^2+u_3+w_3, u_3\gets u_3-a_y d_y, w_3\gets w_3 - a_x d_x$.
\EndIf
\State Put $t\gets 2u_3, A\gets G(xt+y v_3), B\gets Gy, C\gets t$.
\State Put $\gamma=\frac{A+B\sqrt{d}}{C},\varphi_3=(u_3,v_3,w_3)$.
\State \Return $\varphi_3,\gamma$.
\end{algorithmic}
\end{algorithm}

\begin{comment}
\begin{itemize}
    \item \textbf{Step 1}
    Use the extended Euclidean algorithm to find $(x,y,G)$ such that $xu+yv=G=\gcd(u,v)$. Put $A_x=G$, $B_y=\frac{u}{G}$, $D_y=\frac{v}{G}$.
    \item \textbf{Step 2}
    Put $B_x=yw \mod B_y$.
    \item \textbf{Step 3} Put $b_x=B_x$, $b_y=B_y$, $x=1$, $y=0$, $z=0$. While $\lvert b_y \rvert > L$ and $b_x\neq 0$, repeat Step 3a. Then, go to Step 3b.
\begin{itemize}
    \item \textbf{Step 3a} Divide $b_y$ by $b_x$, then let $q$ and $t$ be the quotient and remainder respectively. Put $b_y=b_x$, $b_x=t$, $t=y-qx$, $y=x$, $x=t$, $z=z+1$.
    \item \textbf{Step 3b} If $z$ is odd, put $b_y=-b_y$ and $y=-y$. Go to Step 4.
\end{itemize}
\item \textbf{Step 4}
Put $a_x=Gx$, $a_y=Gy$. If $z\neq 0$, go to Step 5. Otherwise, put $d_x=\frac{b_x D_y - w}{B_y}$, $u_3=b_y^2$, $w_3=b_x^2$, $v_3=v-(b_x+b_y)^2+u_3+w_3$, $w_3=w_3-G d_x$. Go to Step 6.
\item \textbf{Step 5} Put $d_x=\frac{b_x D_y - w x}{B_y}$, $Q_1=d_x y$, $d_y=Q_1+D_y$, $v_3=G(d_y+Q_1)$, $d_y=\frac{d_y}{x}$, $u_3=b_y^2$, $w_3=b_x^2$, $v_3=v_3-(b_x+b_y)^2+u_3+w_3$, $u_3=u_3-a_y d_y$, $w_3=w_3 - a_x d_x$. Go to Step 6.
\item \textbf{Step 6}
Put $t=2u_3$. Then $\gamma=\frac{A+B\sqrt{d}}{C}$ where $A=G(xt+y v_3)$, $B=Gy$, $C=t$. The output is $\varphi_3=(u_3,v_3,w_3)=\frac{1}{\gamma}\varphi^2$. 
\end{itemize}
\end{comment}

Our third algorithm is called NUCOMPchoose (Algorithm \ref{alg:NUCOMPchoose}). This algorithm takes two ideals (written as $\BZ$-modules), converts them to binary quadratic forms, and decides which technique (out of NUCOMP, NUDUPL and standard composition without reduction) should be used to compose them. The third technique mentioned, composition without reduction, simply produces the ideal product of its inputs, written as a $\BZ$-module. The reader can see how this is achieved in \cite[Section 5.4]{JacobsonWilliams}. If either ideal has small norm, NUCOMP and NUDUPL tend to produce large values during the computation, which can overflow. It is therefore preferable to use the ideal product in these cases (the authors have found that a norm less than or equal to 50 is appropriate, at least for $d\leq 10^{11}$).

\begin{algorithm}
\caption{NUCOMPchoose}\label{alg:NUCOMPchoose}
\begin{algorithmic}
\State \textbf{Input:} the primitive reduced ideals $I_1=[\frac{u_1}{2},\frac{v_1+\sqrt{d}}{2}]$ and $I_2=[\frac{u_2}{2},\frac{v_2+\sqrt{d}}{2}]$.
\State \textbf{Output:} the primitive (not necessarily reduced) ideal $I=[\frac{u}{2},\frac{v+\sqrt{d}}{2}]$, and the value $\gamma$ such that $I=\frac{1}{\gamma}{I_1 I_2}$.
\\
\State Put $u_1\gets \lvert u_1 \rvert, u_2\gets\lvert u_2 \rvert, v_1\gets v_1\pmod{u_1}, v_2\gets v_2\pmod{u_2}$.
\If{$u_1\leq 50$ or $u_2 \leq 50$}
    \State Find the ideal product of $I_1$ and $I_2$, and write it as $S[\frac{u}{2},\frac{v+\sqrt{d}}{2}]$ for some integer $S$.
    \State \Return $I=[\frac{u}{2},\frac{v+\sqrt{d}}{2}],\gamma=S$.
\EndIf
\State Put $w_1\gets\frac{v_1^2-D}{2u_1}$.
\If{$u_1=u_2$ and $v_1=v_2$}
    \State Use NUDUPL to compose $(\frac{u_1}{2},-v_1,w_1)$ with itself, and let the output be $(u_3,v_3,w_3)$ and $\gamma$.
\Else
    \State Put $w_2\gets\frac{v_2^2-D}{2u_2}$.
    \State Use NUCOMP to compose $(\frac{u_1}{2},-v_1,w_1)$ with $(\frac{u_2}{2},-v_2,w_2)$, and let the output be $(u_3,v_3,w_3)$ and $\gamma$.
\EndIf
\State Put $u=\lvert 2u_3\rvert$ and $v=-v_3\pmod{u}$.
\State \Return $I=[\frac{u}{2},\frac{v+\sqrt{d}}{2}]$ and $\gamma$.
\end{algorithmic}
\end{algorithm}



