\section{Linear Programming Formulations}
\label{sec:lp-formulations}

In this section we first formulate an LP for the efficient allocation problem, whose dual characterizes CE prices. We then show how to convert this dual to an LP that characterizes UCE prices.

\subsection{Competitive Equilibrium}

The primal LP computes an efficient allocation. For each $i \in N$ and $\vk \in \mK_i$, we introduce a variable $z_i(\vk) \in [0, 1]$ to capture whether the agent obtains bundle $\vk$ in the allocation. As mentioned, although the variable is fractional, it can be shown that the LP has an integer optimal solution based on the gross substitutes property. The LP shows the associated dual variables in brackets to the left of each constraint.
%
\begin{alignat}{3}
    \max_{z \geq 0} & \qquad \ds \sum_{i \in N} \sum_{\vk \in \mK_i} v_i(\vk) z_i(\vk) && \qquad && \label{opt:primal-ce} \\
    \mbox{$[p]$} & \qquad \ds \sum_{i \in N} \sum_{\vk \in \mK_i} |\vk|\, z_i(\vk) \leq K && && \tag{\ref{opt:primal-ce}a} \label{opt:primal-ce-const-a} \\
    \mbox{$[\pi_i]$} & \qquad \ds \sum_{\vk \in \mK_i} z_i(\vk) \leq 1 && \qquad \mbox{$\forall i \in N$} && \tag{\ref{opt:primal-ce}b} \label{opt:primal-ce-const-b}
\end{alignat}
%
Its dual takes the following form. There is a variable $\pi_i \geq 0$ for each agent $i \in N$, and a variable $p \geq 0$ which should be interpreted as the (constant) price per unit.
%
\begin{alignat}{3}
\min_{\pi \geq 0, p \geq 0} & \qquad \ds \sum_{i \in N} \pi_i + K \, p && \qquad && \label{opt:dual-ce} \\
\mbox{$[z_i(\vk)]$} & \qquad \ds \pi_i \geq v_i(\vk) - |\vk|\, p && \qquad \mbox{$\forall i \in N$, $\forall \vk \in \mK_i$} && \tag{\ref{opt:dual-ce}a} \label{opt:dual-ce-cons-a}
\end{alignat}
%
An optimal solution $p^*$ to this LP corresponds to CE prices, by standard duality arguments~\citep{bikhchandani2002package, bikhchandani2002linear}. We explain the proof here as we will use similar arguments for our UCE results.
%
Suppose $z_i^*(\vk)$ are an optimal primal solution and $\pi_i^*$, $p^*$ an optimal dual solution. If $z_i^*(\vk^*) = 1$, then the primal LP has computed an efficient allocation where agent $i$ obtains bundle $\vk^*$. By complementary slackness, constraint~\eqref{opt:dual-ce-cons-a} binds and so we have $v_i(\vk^*) - |\vk^*| p^* = \pi_i^*  \geq v_i(\vk) - |\vk| p^*$ for all $\vk \in \mK_i$. In other words, $\vk^* \in D_i(p^*)$ for each $i \in N$. If $p^* = 0$, then every allocation trivially maximizes the seller's revenue, whereas if $p^* > 0$, then by complementary slackness constraint~\eqref{opt:primal-ce-const-b} binds and all items are allocated. At a constant price of $p^*$ per unit, this maximizes the seller's revenue. Thus, $p^*$ supports the allocation $(\vk^*_1, \dots, \vk^*_n)$.

In the sequel we will use $\Primal(N)$ to refer to the primal LP and $\Dual(N)$ for the dual LP, both parametrized by the economy. We write $V(N)$ for their optimal value, which is common to both by strong duality.

\subsection{Universal Competitive Equilibrium}

We now present our dual LP characterizing UCE prices, referred to as $\UCEDual(N)$.
%
\begin{alignat}{3}
\min_{\pi \geq 0,\, p \geq 0,\, \alpha \geq 0,\, \rho\: \mathrm{free}} & \qquad \ds \sum_{j \in N_0} \left[ \sum_{i \in \Nj} \pi_i^{-j} + 
K \, p^{-j} + \sum_{i \in \Nj} \alpha^{-j}_i \right] && \qquad && \label{opt:dual-uce} \\
\mbox{$[z_i^{-j}(\vk)]$} & \qquad \ds \pi_i^{-j} \geq v_i(\vk) - \rho_i(\vk) && \quad \mbox{$\forall j \in N_0$, $\forall i \in \Nj$, $\forall \vk \in \mK_i$} && \tag{\ref{opt:dual-uce}a} \label{opt:dual-uce-cons-a} \\
\mbox{$[\beta_i^{-j}(\vk)]$} & \qquad \ds \rho_i(\vk) \leq |\vk| \, p^{-j} + \alpha_i^{-j} && \quad \mbox{$\forall j \in N_0$, $\forall i \in \Nj$, $\forall \vk \in \mK_i$} &&  \tag{\ref{opt:dual-uce}b} \label{opt:dual-uce-cons-b}
\end{alignat}
%
\medskip
To obtain this LP, we applied the following transformation recipe:
%
\begin{enumerate}
    \item We create copies $\pi_i^{-j}$ and $p^{-j}$ of the original variables $\pi_i$ and $p$ for each economy $j \in N_0$.
    \item We also create new variables $\alpha_i^{-j}$ for all $j \in N_0$, $i \in N^{-j}$.
    \item The objective function is the sum of the dual objectives for the main and marginal economies, but we also add in all the  $\alpha_i^{-j}$ variables.
    \item We create copies of the constraints~\eqref{opt:dual-ce-cons-a} for each economy $j \in N_0$, leading to constraint~\eqref{opt:dual-uce-cons-a}. However, each price term $|\vk| p^{-j}$ in a constraint associated to agent $i$ is replaced with a new price variable $\rho_i(\vk)$.
    \item We introduce the new constraints~\eqref{opt:dual-uce-cons-b}. To understand these constraints, the goal is to enforce the relationship:
    %
    $\rho_i(\vk) = \min_{j \in N_0^{-i}} |\vk| \, p^{-j} + \alpha_i^{-j}.$
    %
    In other words, $\rho_i(\vk)$ should be the \emph{lower envelope} of the prices for $\vk$ in the main and marginal economies, with additive offsets $\alpha_i^{-j}$ in these economies.
    As the optimization will push $\rho_i(\vk)$ to be as large as possible, this will hold at an optimal solution by introducing constraints~\eqref{opt:dual-uce-cons-b}.

\end{enumerate}

The corresponding primal LP is as follows, referred to as $\UCEPrimal(N)$. The common optimal value of the UCE primal and dual is denoted $\tilde{V}(N)$.
%
\vspace{-10pt}
\begin{alignat}{3}
    \max_{z \geq 0, \beta \geq 0} & \qquad \ds \sum_{j \in N_0} \left[ \sum_{i \in \Nj} \sum_{\vk \in \mK_i} v_i(\vk) z_i^{-j}(\vk) \right] && \qquad &&  \label{opt:primal-uce} \\
    \mbox{$[\pi_i^{-j}]$} & \qquad \ds \sum_{\vk \in \mK_i} z_i^{-j}(\vk) \leq 1 && \qquad \mbox{$\forall j \in N_0$, $\forall i \in \Nj$} &&  \tag{\ref{opt:primal-uce}a} \label{opt:primal-uce-cons-a} \\
    \mbox{$[\rho_i(\vk)]$} & \qquad \ds \sum_{j \in N_0^{-i}} z_i^{-j}(\vk) = \sum_{j \in N_0^{-i}} \beta_i^{-j}(\vk) && \qquad \mbox{$\forall i \in N$, $\forall \vk \in \mK_i$} && \tag{\ref{opt:primal-uce}b} \label{opt:primal-uce-cons-b} \\
    \mbox{$[\alpha_i^{-j}]$} & \qquad \ds \sum_{\vk \in \mK_i} \beta_i^{-j}(\vk) \leq 1 && \qquad \mbox{$\forall j \in N_0$, $\forall i \in \Nj$} && \tag{\ref{opt:primal-uce}c} \label{opt:primal-uce-cons-c} \\
    \mbox{$[p^{-j}]$} & \qquad \ds \sum_{i \in \Nj} \sum_{\vk \in \mK_i} |\vk| \, \beta_i^{-j}(\vk) \leq K && \qquad \mbox{$\forall j \in N_0$} && \tag{\ref{opt:primal-uce}d} \label{opt:primal-uce-cons-d} 
\end{alignat}
%
This LP formulation follows a similar pattern as the dual. Comparing to the original CE primal, we now have a copy $z_i^{-j}(\vk)$ of the original allocation variable $z_i(\vk)$ for each economy $j \in N_0$, but also new allocation variables $\beta_i^{-j}(\vk)$. The supply constraints~\eqref{opt:primal-uce-cons-d} are imposed on the $\beta_i^{-j}(\vk)$ variables, while the $z_i^{-j}(\vk)$ variables appear in the objective. Constraints~\eqref{opt:primal-uce-cons-b} state that, for each agent $i \in N$, the aggregate allocations across economies that contain agent $i$ should equalize.

We do not prescribe a direct recipe to transform the CE primal into the UCE primal. Our approach has been to transform the CE dual into the UCE dual following the recipe above, and then take the dual of the latter to recover the UCE primal. Although our exposition focuses on the case of two items with multiple units, the transformation applies generically. In Appendix~\ref{app:general-uce-lp}, we show how the LPs for general combinatorial auctions from~\citep{bikhchandani2002package} can be converted to LPs for UCE prices.

\subsection{UCE Characterization}

%In this section we prove our main result, that the dual $\UCEDual(N)$ characterizes UCE prices.
%
\begin{lemma}
\label{lem:primal-uce-solution}
Assume that the primal $\Primal(\Nj)$ has an integer optimal solution for all $j \in N_0$. Then the primal $\UCEPrimal(N)$ has an integer optimal solution, such that the $z^{-j}_i(\vk)$ variables define an efficient allocation for economy $\Nj$ for each $j \in N_0$, and its optimal value is $\tilde{V}(N) = \sum_{j \in N_0} V(\Nj)$.
\end{lemma}
%
%\vspace{-10pt}
\begin{proof}
%
We argue that we can assume that at an optimal solution, we have $z^{-j}_i(\vk) = \beta^{-j}_i(\vk)$ for all $j \in N_0$, $i \in \Nj$, $\vk \in \mK_i$. To see this, note that reassigning $z^{-j}_i(\vk) \leftarrow \beta^{-j}_i(\vk)$ obviously maintains equality in constraints~\eqref{opt:primal-uce-cons-b}. As the $z^{-j}_i(\vk)$ values on the left-hand side of~\eqref{opt:primal-uce-cons-b} all have the same coefficient $v_i(\vk)$ in the objective for a fixed $i \in N$ and $\vk \in \mK_i$, this does not change the objective value of the solution. Furthermore, constraints~\eqref{opt:primal-uce-cons-c} imply that the new $z^{-j}_i(\vk)$ values satisfy~\eqref{opt:primal-uce-cons-a}.

Thus, we can introduce the constraints $z^{-j}_i(\vk) = \beta^{-j}_i(\vk)$ for all $j \in N_0$, $i \in \Nj$, $\vk \in \mK_i$ without affecting the optimal value of $\UCEPrimal(N)$. We these extra constraints, the LP simplifies to the following.
%
\begin{alignat}{3}
    \max_{z \geq 0, \beta \geq 0} & \qquad \ds \sum_{j \in N_0} \left[ \sum_{i \in \Nj} \sum_{\vk \in \mK_i} v_i(\vk) z_i^{-j}(\vk) \right] && \qquad &&  \nonumber \\
    \mbox{$[\pi_i^{-j}]$} & \qquad \ds \sum_{\vk \in \mK_i} z_i^{-j}(\vk) \leq 1 && \qquad \mbox{$\forall j \in N_0$, $\forall i \in \Nj$} &&  \nonumber \\
    \mbox{$[p^{-j}]$} & \qquad \ds \sum_{i \in \Nj} \sum_{\vk \in \mK_i} |\vk| \, z_i^{-j}(\vk) \leq K && \qquad \mbox{$\forall j \in N_0$} && \nonumber
\end{alignat}
%
By inspection we see that this LP decomposes into the constraints and variables from $\Primal(\Nj)$ for each $j \in N_0$, and the objective is simply their summed objectives. Thus, as each $\Primal(\Nj)$ has an integer optimal solution, $\UCEPrimal(N)$ also has an integer optimal solution by our previous arguments, such that the variables $z_i^{-j}(\vk)$ define an efficient allocation for economy $\Nj$, for each $j \in N_0$. The optimal value of the summed objective is the sum of the optimal values for $\Primal(\Nj)$ for all $j \in N_0$, or more concisely $\tilde{V}(N) = \sum_{j \in N_0} V(\Nj)$.
\end{proof}

\begin{theorem}
Assume that the primal $\UCEPrimal(N)$ has an integer optimal solution, such that the $z^{-j}_i(\vk)$ variables define an efficient allocation for economy $\Nj$, for each $j \in N_0$. Then at an optimal solution to $\UCEDual(N)$, the $\rho_i(\vk)$ variables represent UCE prices for economy $N$.
\end{theorem}
%
\begin{proof}
Note that an integer solution to the primal $\UCEPrimal(N)$ must be binary (0 or 1). Fix an economy $j \in N_0$ and let $(\vk^*_1, \dots, \vk^*_n)$ be the efficient allocation defined by the optimal $z_i^{-j}(\vk)$ variables. For each agent $i \in \Nj$ we have
$$
v_i(\vk^*_i) - \rho_i(\vk^*_i) = \pi_i^{-j} \geq v_i(\vk) - \rho_i(\vk)
$$
for all $\vk \in \mK_i$. The first equality holds by complementary slackness, because $z^{-j}_i(\vk^*_i) > 0$, and the remaining inequalities hold by dual feasibility. Thus $\vk^*_i \in D_i(\rho_i)$. Next, for feasible allocations $\vk$ we have:
%
\begin{eqnarray*}
\sum_{i \in \Nj} \rho_i(\vk^*_i) & = & \sum_{i \in \Nj} |\vk^*_i|\, p^{-j} + \alpha_i^{-j} \\
& \geq & \sum_{i \in \Nj} |\vk_i|\, p^{-j} + \alpha_i^{-j} \\
& \geq & \sum_{i \in \Nj} \rho_i(\vk_i)
\end{eqnarray*}
%
The first equality follows from complementary slackness for~\eqref{opt:dual-uce-cons-b}, because we can assume $\beta_i^{-j}(\vk_i^*) = z_i^{-j}(\vk_i^*) > 0$ as in the proof of Lemma~\ref{lem:primal-uce-solution}.
Because $(\vk^*_1, \dots, \vk^*_n)$ is efficient, we have $\sum_{i \in N^{-j}} |\vk_i^*| = K \geq \sum_{i \in N^{-j}} |\vk_i|$ for any feasible $(\vk_1, \dots, \vk_n)$. This implies the first inequality as it is linear in $p^{-j}$.
The second inequality follows from the feasibility constraint~\eqref{opt:dual-uce-cons-b}.
Therefore $(\vk^*_1, \dots, \vk^*_n) \in S(\boldsymbol{\rho})$.
As economy $j$ was arbitrary, we have shown that prices $\boldsymbol{\rho}$ are competitive equilibrium prices for all economies $j \in N_0$, which completes the proof.
\end{proof}
%


