\begin{proof}[Proof of Theorem~\ref{thm:uce-vcg-construction}]
%{[Theorem~\ref{thm:uce-vcg-construction}]}
Let $(\vk_1, \dots, \vk_n)$ be an efficient allocation in the main economy and let $(\vk_1^{-\ell}, \dots, \vk_n^{-\ell})$ be efficient allocations in the marginal economies, for $\ell \in N_0$.
By definition, the VCG payment $g_i$ of agent $i$ is:
%
\begin{align}
  \quad & \ds \sum_{\ell \in N^{-i}} v_{\ell}(\vk_{\ell}^{-i}) -  \sum_{\ell \in N^{-i}} v_{\ell}(\vk_{\ell}) \nonumber \\
= \quad  & \ds \left[ \sum_{\ell \in N^{-i}} v_{\ell}(\vk_{\ell}^{-i}) - \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}^{-i}) \right] 
   - \left[ \sum_{\ell \in N^{-i}} v_{\ell}(\vk_{\ell}) - \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}) \right]
   +  \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}^{-i}) -  \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}) \nonumber \\
= \quad  & \ds \sum_{\ell \in N^{-i}} \left( [ v_{\ell}(\vk_{\ell}^{-i}) - p_{\ell}(\vk_{\ell}^{-i}) ]
   - [ v_{\ell}(\vk_{\ell}) -  p_{\ell}(\vk_{\ell}) ] \right)
   +  \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}^{-i}) -  \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}) \nonumber \\
= \quad  & \ds \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}^{-i}) -  \sum_{\ell \in N^{-i}} p_{\ell}(\vk_{\ell}) \nonumber
\end{align}
%
The first two equalities are re-arrangements. The final equality follows because $\vk_i^{-\ell}, \vk_i \in D_i(p_i)$ as they are both supported by the UCE prices, and they therefore have the same utility.
In the final line, the allocations maximize the revenue terms as the UCE prices support them. Therefore, to evaluate these terms, we can use any revenue-maximizing allocations rather than efficient allocations.
\end{proof}

