\begin{proof}[Proof of Lemma \ref{supergollemma}]
 For $t \in B(1-k, 1+k)$, we have
\begin{equation}
	\rho_{M,N}^{-2}(k)\big(F(t;k) - F(1-k;k)\big) = -\frac{1}{2} \big(t - (1-k)^2\big) + O(N^{-1}),
\end{equation}
and $\frac{d}{dx} \Re F\big(-k \pm i/4;k\big) > 0$. Consequently, the function $\rho_{M,N}^{-2}(k) \Re \big(F(t;k) - F(1-k;k)\big)$ decreases as $t$ moves away from $1-k$ along the segment $B(1-k,1+k) \cap \left[ \Sigma_{-}\big(\frac{1}{2}-k\big) \cup \Sigma_{+}\big(\frac{3}{2}-k\big) \right]$. On the horizontal components of $\Sigma_{-}\big(\frac{1}{2}-k\big)$, 
\begin{align}
	\frac{d^2}{dx^2} \Re F\big(x \pm \tfrac{i}{4};k\big) 
	= \Re \left. \frac{d^2F(t;k)}{dt^2} \right|_{t=x\pm\frac{i}{4}} 
	= - \sum_{j=0}^M \Re \psi'\big(x+N+v_j \pm \tfrac{i}{4}\big)< 0.
\end{align}
it follows that $\Re \left[ \rho_{M,N}^{-2}(k) F(t;k) \right]$ decreases as $t$ moves away from $1-k$, since $\frac{d}{dx} \Re F\big(x \pm \frac{i}{4};k\big) > 0$ at the endpoints of these horizontal contours.
Finally, for $t = -N + \frac{1}{2} + iy$ with $y \in [-\frac{1}{4}, \frac{1}{4}]$, a direct calculation yields
\begin{equation}
	\Re \big(F(t;k) - F(1-k;k)\big) = -\rho_{M,N}^{2}(k) (N+1-k)^2 \big(1 + o(1)\big).
\end{equation}
Combining these estimates gives the desired result.
\end{proof}





\subsection{Proof  of Theorem \ref{subthm}}
\begin{proof}[Proof of Theorem \ref{subthm}]
After changing the variables $s,t \to \rho_{M,N}^{3/2}s,\rho_{M,N}^{3/2}t$, we obtain
\begin{equation}
K_{M,N}(x,y)=\rho_{M,N}^{3/2}\int_{\mathcal{C}}\frac{ds}{2 \pi i} \oint_{\Sigma}\frac{dt}{2\pi i}\frac{e^{\rho_{M,N}^{3/2}(xt- ys)}}{s-t}
	\prod_{j=0}^{M}\frac{\Gamma(\rho_{M,N}^{3/2}s+N+v_j)}{\Gamma(\rho_{M,n}^{3/2}t+N+v_j)}.
\end{equation}
Making the substitution $ g(\xi)=\xi\rho^{-1}_{M,N}+\log \lambda_M$, we find that
\begin{equation}
K_{M,N}(g(\xi),g(\eta))=\rho_{M,N}^{3/2}\int_{\mathcal{C}}\frac{ds}{2 \pi i} \oint_{\Sigma}\frac{dt}{2\pi i}\frac{e^{\rho_{M,N}^{1/2}(\xi t-\eta s)}}{s-t}e^{F_{M,N}(\rho_{M,N}^{3/2}s)-F_{M,N}(\rho_{M,N}^{3/2}t)},
\end{equation}
where 
\begin{equation}
	F_{M,N}(s)=\sum_{j=0}^M\log \frac{\Gamma(s+N+v_j)}{\Gamma(N+v_j)}-\log\Gamma(s)-s\log(\lambda_M).
\end{equation}
Applying Stirling's formula for $\log \Gamma(z)$ as given in \eqref{eslogg}, we obtain the asymptotic expansion
\begin{equation}
F_{M,N}(\rho_{M,N}^{3/2}s)=\rho_{M,N}^{3/2}f_{M,N}(s)+O(\Delta_{M,N}),%O(\sum_{j=0}^M\frac{1}{n+v_j}-\sum_{j=1}^M\frac{1}{m_j}),
\end{equation}
where 
\begin{align}
	f_{M,N}(s)=\sum_{j=0}^M\frac{N+v_j}{\rho_{M,N}^{3/2}}\Big(1+\frac{\rho_{M,N}^{3/2}s}{N+v_j}\Big)\log \Big(1+\frac{\rho_{M,N}^{3/2}s}{N+v_j}\Big)-s(\log s
	-v_{M,N}),
\end{align}
with $v_{M,N}=\sum_{j=0}^M\log(N+v_j)-\log\rho_{M,N}^{3/2}-\log \lambda_M$. 

\textbf{Step 1: Contour constructions  and integral decomposition.}

We deform integration contours to isolate the critical point, noting $q_0 := z_0 \rho_{M,N}^{-3/2}$.
Deform the contour for $s$ as $\mathcal{C}=\mathcal{C}_{\text{local}} \cup \mathcal{C}_{\text{global}}$, where  $\mathcal{C}_{\text{local}}=\mathcal{C}_{\text{local},+} \cup \mathcal{C}_{\text{local},-}$,  with
\begin{align}
&\mathcal{C}_{\text{local},+}=\Big\{q_0+\big(1/\rho_{M,N}^{3/2}\big)^{1/3}+re^{\frac{4\pi i}{3}}\mid -\big(1/\rho_{M,N}^{3/2}\big)^{3/10}\leq r \leq 0\Big\},\\
&\mathcal{C}_{\text{local},-}=\Big\{q_0+\big(1/\rho_{M,N}^{3/2}\big)^{1/3}+re^{\frac{5\pi i}{3}}\mid 0\leq r \leq \big(1/\rho_{M,N}^{3/2}\big)^{3/10}\Big\},
\end{align}
and the global contour
\begin{align}
\mathcal{C}_{\text{global}}=&\Big\{q_0+\big(1/\rho_{M,N}^{3/2}\big)^{1/3}-\big(1/\rho_{M,N}^{3/2}\big)^{1/3}e^{\frac{4 \pi i}{3}}+iy \mid y\geq 0\Big\}\notag \\
&\cup \Big\{q_0+\big(1/\rho_{M,N}^{3/2}\big)^{1/3}+\big(1/\rho_{M,N}^{3/2}\big)^{1/3}e^{\frac{5 \pi i}{3}}+iy \mid y\leq 0\Big\}.
\end{align}
Deform the $t$-contour as $\Sigma = \Sigma_{\text{local}} \cup \Sigma_{\text{global}}$, where $\Sigma_{\text{local}} = \Sigma_{\text{local},+} \cup \Sigma_{\text{local},-}$ with
\begin{align}
	&\Sigma_{\text{local},+}=\Big\{q_0-\big(1/\rho_{M,N}^{3/2}\big)^{1/3}+re^{\frac{2\pi i}{3}}\mid 0\leq r \leq \big(1/\rho_{M,N}^{3/2}\big)^{3/10}\Big\},\\
	&\Sigma_{\text{local},-}=\Big\{q_0-\big(1/\rho_{M,N}^{3/2}\big)^{1/3}+re^{\frac{\pi i}{3}}\mid  -\big(1/\rho_{M,N}^{3/2}\big)^{3/10}\leq r \leq 0\Big\}.
\end{align}
The global contour $\Sigma_{\text{global}}$ is constructed to ensure $\Re f_{M,N}(t)$ attains its minimum at the left endpoints of $\Sigma_{\text{local},\pm}$. It is defined as
\begin{equation}
\Sigma_{\text{global}}:=\Sigma_{+}^1 \cup \Sigma_{+}^2 \cup \Sigma_{+}^3 \cup \Sigma^4 \cup  \Sigma_{-}^1 \cup \Sigma_{-}^2 \cup \Sigma_{-}^3,
\end{equation}
where 
\begin{align}
	&\Sigma_{\pm}^1= \Big\{\text{vertical line connecting the left end of $\Sigma_{\text{local},\pm}$ to $(x_1,\pm y_1)$}\Big\}, \notag\\
	&\Sigma_{\pm}^2=\Big\{t=x \pm iy \mid \frac{y-y_1}{y_2-y_1}=\frac{x-x_1}{x_2-x_1} \Big\},\notag\\
	&\Sigma_{\pm}^3=\Big\{t=x \pm iy_2 \mid x\in[-N/\rho_{M,N}^{3/2}+(2\rho_{M,N}^{3/2})^{-1},x_2]\Big\},\notag\\
	&\Sigma^4=\Big\{t=-N/\rho_{M,N}^{3/2}+(2\rho_{M,N}^{3/2})^{-1}+iy \mid y \in [-y_2,y_2]\Big\}.
\end{align}
The contours are oriented such that $\Sigma$ is positively oriented, while $\mathcal{C}$ is from $-i\infty$ to $i\infty$;
see figure \ref{subcontour}.
	\begin{figure}
	\centering
	\includegraphics{figure2}
	\caption{Schematic contours in proof of Theorem \ref{subthm}}
	\label{subcontour}
\end{figure}

In the following, we provide the selection strategy for the contour $\Sigma_{\text{global}}$ and show that $\Re f_{M,N}(t) $ attains its minimum at left end of $\Sigma_{\text{local},\pm}$ on $\Sigma_{\text{global}}$.
For $t \in \Sigma_{\pm}^1$, we set 
$x_1=q_0-\big(\rho_{M,N}^{-3/2}\big)^{1/3}-1/2\big(\rho_{M,N}^{-3/2}\big)^{3/10}$,
 and choose $y_1$ satisfies
$\frac{d\Re f_{M,N}(x_1+iy_1)}{dy}=0$.
Next, we choose  $C$ as a large enough positive constant, independent of $M,N$ and let $x_2=-C$, such that  $\frac{d\Re f_{M,N}(x_2+iy)}{dx}<0$ for $t\in \Sigma^3_{+}$ and choose $y_2$ such that $\frac{d \Re f_{M,N}(x_2+iy_2)}{dy}=0$.
At last, we illustrate that $\Re f_{M,N}(t)$ increases as $t$ along the $(x_1,y_1)\to (x_2,y_2)$.
Note that $z=re^{i\theta}$, $r>0$ and  the angle $\theta \in (\pi/2,\pi)$ is fixed.
By the first derivative 
\begin{equation}
	\begin{split}\frac{d\Re f_{M,N}(x_1+iy_1+z)}{dr}%&=\Re\big(e^{i\theta}f'_{M,N}(x_1+iy_1+z)\big)\\
		=\cos\theta \Re f'_{M,N}(x_1+iy_1+z)-\sin \theta \Im f'_{M,N}(x_1+iy_1+z),
	\end{split}
\end{equation}
and second derivative 
\begin{equation}\label{urr}
	\frac{d^2\Re f_{M,N}(x_1+iy_1+z)}{dr^2}=-\frac{1}{r}\frac{d\Re f_{M,N}(x_1+iy_1+z)}{dr}-\frac{1}{r^2}	\frac{d^2\Re f_{M,N}(x_1+iy_1+z)}{d\theta^2},
\end{equation}
we see that the signs of first-order and second-order derivatives are opposite. Combining \eqref{urr} and  $\frac{d\Re f_{M,N}(x_1+iy_1)}{dr}>0$ and $\frac{d\Re f_{M,N}(x_2+iy_2)}{dr}>0$, we can  conclude that $\frac{d\Re f_{M,N}(t)}{dr}>0$ for $t\in \Sigma^2_{+}$.
 Similarly, we can prove that 
$\Re f_{M,N}(t)$ increases as $t$ moves upward on $\Sigma^1_{+}$, or t moves downward on $\Sigma^1_{-}$ and  $\Re f_{M,N}$ increases as $t$ moves leftward, and attains its minimum at $(x_2,\pm y_2)$ for $t\in \Sigma^3_{\pm}$.  It is easy to see that $\Re f_{M,N}(t)$ attains its maximun at $t=-N/\rho_{M,N}^{3/2}+(2\rho_{M,N}^{3/2})^{-1}$ for $t \in \Sigma^4$.
%Recalling that $q_0=z_0/\rho_{M,n}^{3/2}$, 
Therefore, the integral decomposes into a local part  $\mathcal{C}_{\text{local}}\times \Sigma_{\text{local}} $  and a global part  $\mathcal{C}\times \Sigma \setminus (\mathcal{C}_{\text{local}}\times \Sigma_{\text{local}})$.

\textbf{Step 2: Asymptotics of the local part.}

We compute derivatives to analyze the local behavior,
\begin{align}
	&	f_{M,N}'(s)=\sum_{j=0}^M \log\Big(1+\frac{\rho_{M,N}^{3/2}s}{N+v_j}\Big)-\log s +v_{M,N},\\
	&f_{M,N}''(s)=\rho_{M,N}^{3/2}\sum_{j=0}^M\frac{1}{N+v_j+\rho_{M,N}^{3/2}s},\\
	&f_{M,N}'''(s)=-\rho_{M,N}^3\sum_{j=0}^M\frac{1}{(N+v_j+\rho_{M,N}^{3/2}s)^2}.
\end{align}
Recalling that $z_0$ defined in \eqref{defz_0} and  $q_0= z_0 \rho_{M,N}^{-3/2}$, we have
\begin{equation}
	f_{M,N}'(q_0)=0,\quad 	f_{M,N}''(q_0)=0,
	\quad	f_{M,N}'''(q_0)=2+o(1).
\end{equation}
After makig the change of variables \begin{equation}
t=q_0+\rho_{M,N}^{-1/2}\tau, \quad s=q_0+\rho_{M,N}^{-1/2}\sigma,
 \end{equation}
 and taking Taylor expansion at $q_0$
 in $B(q_0,\rho_{M,N}^{-\frac{3}{2}\times \frac{3}{10}})$, we obtain
\begin{equation}
	f_{M,N}(t)=f_{M,N}(q_0)+\frac{1}{6}f_{M,N}'''(q_0)(t-q_0)^3+O(\rho_{M,N}^{-\frac{3}{2}\times \frac{6}{5}}),
\end{equation}
The local part estimate is given by
\begin{align}\label{localestimate}
	&\big(\rho_{M,N}^{1/2}\big)e^{-\rho_{M,N}^{1/2}(\xi-\eta)q_0}\int_{\mathcal{C}_{\text{local}}}\frac{ds}{2\pi i}\int_{\Sigma_{\text{local}}}\frac{dt}{2 \pi i}e^{(\xi t -\eta s)\rho_{M,N}^{1/2}}\frac{e^{ \rho_{M,N}^{3/2}\frac{f_{M,N}'''(q)}{6}\big((s-q)^3-(t-q)^3\big)+O(\rho_{M,N}^{-\frac{3}{10}})}}{s-t}\notag \\
	&=\int_{\mathcal{C}^{\rho_{M,N}^{1/20}}_{<}}\frac{d\sigma}{2\pi i} \int_{\Sigma_{>}^{\rho_{M,N}^{1/20}}}\frac{d \tau}{2\pi i }\frac{1}{\sigma-\tau}\frac{e^{\frac{\sigma^3}{3}-\eta \sigma}}{e^{\frac{\tau^3}{3}-\xi \tau}}\big(1+O(\rho_{M,N}^{-\frac{3}{10}})\big) \\ \notag
	&=K_{\mathtt{Ai}}(\xi,\eta)+O(\rho_{M,N}^{-\frac{3}{10}}),
\end{align}
where the contours for real $R > 0$ are defined as upward oriented 
\begin{align}
	&\mathcal{C}_{<}^R=\{1+re^{\frac{4\pi i}{3}}\mid -R\leq r\leq 0\} \cup \{1+re^{\frac{5\pi i}{3}}\mid 0\leq r\leq R\},\\
	&\Sigma_{>}^R=\{-1+re^{\frac{2\pi i}{3}}\mid 0\leq r\leq R\} \cup \{-1+re^{\frac{\pi i}{3}}\mid -R\leq r\leq 0\}.
\end{align}

\textbf{Step 3:  Estimates of the global part.}

%On the other hand, we need the ``global" estimates of $\Re f_{M,N}(s)$ for $s\in \mathcal{C}_{\text{global}}$,and  of $\Re f_{M,N}(t)$ for $t \in \Sigma_{\text{global}}$.
For $s$, we consider the infinite contour $\mathcal{C}_{\text{global}}$ split into two parts: $\mathcal{C}^1_{\text{global}} = \{ s \in \mathcal{C}{\text{global}} \mid |\Im s| \leq K \}$ and $\mathcal{C}_{\text{global}}^2 = \mathcal{C}_{\text{global}} \setminus \mathcal{C}_{\text{global}}^1$, where $K$ is a large positive constant.

\begin{lemma}\label{globalref}
	Let $x_0>q_0$, and  $C=\{x_0+iy\mid y\in \mathbb{R}\}\}$, then $\Re f_{M,N}(s)$ attains its global maximum at $x_0$ on $C$. Moreover, 
	\begin{equation}
		\frac{d \Re f_{M,N}(x_0+iy)}{dy}\begin{cases}
			<0, &y>0,\\
			>0,  & y<0.\\
		\end{cases}
	\end{equation}
\end{lemma}
By Lemma \ref{globalref}, $\Re f_{M,N}(s)$ decreases as $s$ moves upward on $\mathcal{C}_{\text{global}}^1$  $ \cap $    $\mathbb{C}_{+}$ or $s$ moves downward on $\mathcal{C}_{\text{global}}^1$ $\cap$ $\mathbb{C}_{-}$.
Direct computation shows that $\Im f'_{M,N}(t)>1$ if $s\in \mathcal{C}_{\text{global}}^2 \cap \mathbb{C}_{+}$ and $\Im f'_{M,N}(t)<-1$ if $s\in \mathcal{C}_{\text{global}}^2 \cap \mathbb{C}_{-}$. Hence $f_{M,N}(s)$ decreases at least linearly fast as $s$ moves to $\pm i \infty$ along $\mathcal{C}_{\text{global}}^2$.
For $t \in \Sigma_{\text{global}}$,  $\Re f_{M,N}(t;\lambda_M)$ attains a minimum at the leftend of $\Sigma_{\text{local},\pm}$.
Combining these global estimates for 
 $s\in \mathcal{C}_{\text{global}}$ and $t \in \Sigma_{\text{global}}$, there exists $\epsilon>0$ such that 
\begin{equation}\label{subglobales}
\Re \Big(f_{M,N}(s)-\frac{\xi(t-q_0)}{\rho_{M,N}}\Big)+\epsilon \rho_{M,N}^{-27/20}\\
	\leq \Re \Big(f_{M,N}(t)-\frac{\eta (t-q_0)}{\rho_{M,N}}\Big)-\epsilon \rho_{M,N}^{-27/20}.
\end{equation}
Thus, combining  \eqref{subglobales} with the estimates of 
$f_{M,N} (t; \lambda_M)$ on
$\Sigma_{\text{local}}$	 and $\mathcal{C}_{\text{local}}$
from \eqref{localestimate} yields
\begin{equation}\label{globalestimate}
	\begin{split}
	&	\rho_{M,N}^{-1}e^{-(\xi-\eta)\frac{z_0}{\rho_{M,N}}}\int\int_{\mathcal{C}\times\Sigma\setminus \mathcal{C}_{\text{local}}\times \Sigma_{\text{local}}}\frac{ds}{2\pi i}\frac{dt}{2\pi i}\frac{1}{s-t}e^{\rho_{M,N}^{1/2}(\xi t-\eta s)}e^{\rho_{M,N}^{3/2}(f_{M,N}(s)-f_{M,N}(t))}\\
	&=\rho_{M,N}^{-1}\int\int_{\mathcal{C}\times\Sigma\setminus \mathcal{C}_{\text{local}}\times \Sigma_{\text{local}}}\frac{ds}{2\pi i}\frac{dt}{2\pi i}\frac{1}{s-t}
	\frac{e^{\rho_{M,N}^{3/2}\Big(f_{M,N}(s)-\frac{\eta(s-q_0)}{\rho_{M,N}}\Big)}}{e^{\rho_{M,N}^{3/2}\Big(f_{M,N}(t)-\frac{\xi(t-q_0)}{\rho_{M,N}}\Big)}}
=O\big(e^{-\epsilon(\rho_{M,N}^{-3/20})}\big).
	\end{split}
\end{equation}

Combining the ``local" estimate \eqref{localestimate} and ``global" estimate \eqref{globalestimate}, we  complete the proof of  Theorem \ref{subthm}.
\end{proof}

	\begin{proof}[Proof of Lemma \ref{globalref}]
		We analyze the derivative of the real part of $f_{M,N}$ along the imaginary axis
		\begin{align}
			\frac{d}{dy}\Re f_{M,N}(x_0 + iy) 
			&= \Im \bigg( \log z 
			- \sum_{j=0}^M \log\Big(1+\frac{\rho_{M,N}^{3/2}z}{N+v_j}\Big) \bigg) \bigg|_{z=x_0+iy} \notag\\
%			&= \arctan(\frac{y}{ x_0}) 	-\sum_{j=0}^M  
%		 \arctan\left(\frac{\rho_{M,n}^{3/2}y}{N+v_j + \rho_{M,n}^{3/2}x_0}\right)   \notag\\
			&= -\rho_{M,N}^{3/2}y \sum_{j=0}^M  \frac{1}{N+v_j + \rho_{M,N}^{3/2}x_0} 
	 + O(\Delta_{M,N}).
		\end{align}
		The key observation comes when $\rho_{M,N}^{3/2}x_0 > z_0$, where $z_0$ is the solution to equation \eqref{defz_0}, implying
$	\sum_{j=0}^M  (N+v_j + \rho_{M,N}^{3/2}x_0)^{-1}  > 0$. This inequality yields $\frac{d}{dy}\Re f_{M,N}(x_0+iy) < 0$ for $y > 0$
and $\frac{d}{dy}\Re f_{M,N}(x_0+iy) > 0$ for $y < 0$.
Consequently, $\Re f_{M,N}(s)$ attains its global maximum at $x_0$ on the contour $C$.
	\end{proof}



