\textbf{Coverage:} For a given reward function $r(x, y)$, we define the tilted policy (softmax policy):
\[
\pi_{\beta,r}(y|x) \propto \pirefer(y|x) \exp(\beta r(x,y)).
\]
Then, we introduce the coverage of tilted policy with respect to the reference policy as,
\begin{equation}\label{eq:cov_const}
    \coverconstr(x) := \sum_{y\in\mathcal{Y}} \frac{\pi_{\beta,r}^2(y|x)}{\pirefer(y|x)} \, .
\end{equation}
We also define,
\[\coverinfr(x):=\lim_{\beta\rightarrow \infty}\coverconstr(x).\]
This measure $\coverconstr(x)$ can also be interpreted as a coverage constant, which is standard in KL-regularized policy learning. Furthermore, we can define the coverage of the tilted policy with respect to the reference policy as $\chi^2$-divergence between $\pi_{\beta,r}(y|x)$ and  $\pirefer(y|x)$, i.e., $\chi^2(\pi_{\beta,r}(y|x)\|\pirefer(y|x))$. It ensures that the reference policy places sufficient probability mass on high-reward responses, thereby guaranteeing that the support of the optimal policy lies within the support of the reference. This prevents cases where optimal outputs are entirely excluded by the reference. Similar notions of coverage have been explored in \citet{huang2025best}. 
\subsection{Optimal regret}
For given policy $\pi\big(Y|x\big)$, we define expected true reward with respect to the policy (a.k.a. value function\footnote{We can also consider $\mbE_{X\sim\rho(\cdot)}[\Jrstar(\pi(\cdot|X))]$. All of our results also holds for expected version of value function.}) 
as
% \todoa{notation to $r*$}
\begin{equation}
\Jrstar(\pi\big(\cdot|x\big)):=\mbE_{Y\sim\pi\big(\cdot|x\big)}[\rstar(Y,x)].
\end{equation}
For two policies, $\pi_1(\cdot|x)$ and $\pi_2(\cdot|x)$, we define the gap between these two policies as follows,
\begin{equation}\label{eq:general_gap}
     \DeltaJ(\pi_1(\cdot|x), \pi_2(\cdot|x)):= \Jrstar(\pi_1(\cdot|x))-\Jrstar( \pi_2(\cdot|x)).
\end{equation}
We consider the following KL-Regularized objective function based on the true reward function for SBoN,
\begin{equation}\label{eq:bon-obj}
\begin{split}
       &\JstarBeta( \pirefer(y|x),\pi(\cdot|x)):=\\&\quad\mathbb{E}_{Y\sim \pi(\cdot|x)}[\rstar(Y,x)]-\frac{1}{\beta}\KLr(\pi(\cdot|x)\|\pi_{\mathrm{ref}}(\cdot|x)).
\end{split}
\end{equation}
We provide an upper bound on the optimal gap of the SBoN solution, which is the gap between $\pi^{\star}_{\rstar}\big(\cdot|x\big)$ as the optimal policy and $\pisbon(\cdot|x)$,
\begin{equation}\label{eq:reg_def}
\begin{split}
     &\DeltaJ(\pi^{\star}_{\rstar}\big(\cdot|x\big), \pisbon(\cdot|x))\\&= \Jrstar(\pi^{\star}_{\rstar}\big(\cdot|x\big))-\Jrstar( \pisbon(\cdot|x)).
\end{split}
\end{equation}
Regarding regret of the BoN, we consider $\pibonEST(\cdot|x)$ instead of $\pisbon(\cdot|x)$ in \eqref{eq:reg_def}.

% on 
Our results can be extended to the sub-optimal gap of the SBoN solution, which is the gap between $\pibetarstar\big(\cdot|x\big)$ as the optimal solution to \eqref{eq:bon-obj} and $\pisbon(\cdot|x)$, 
\begin{equation}\label{eq:KL-gap}
    \begin{split}
         &\DeltaJ(\pibetarstar\big(\cdot|x\big), \pisbon(\cdot|x))\\& :=\Jrstar(\pibetarstar(\cdot|x))-\Jrstar( \pisbon(\cdot|x)).
    \end{split}
\end{equation}

