\section{KL divergence Analysis }\label{sec:scale_law}


% This phenomenon has been studied theoretically by \citet{beirami2024theoretical,mroueh2024information}. 
The KL divergence between the aligned policy and the reference policy, $\KLr(\pibontrue \| \pirefer)$, is studied by \citet{beirami2024theoretical,mroueh2024information} from a theoretical perspective. In particular, \citet{beirami2024theoretical} derives an upper bound on KL divergence for BoN policies under the assumptions of a bijective true reward mapping and a finite output space:
\begin{equation}\label{eq:bon_scale_tight}
    \KLr(\pibontrue(\cdot|x) \| \pirefer(\cdot|x))\leq \log(N)-1+\frac{1}{N},
\end{equation}
\citet{mroueh2024information} relaxes the bijectivity assumption and derives similar bounds using information-theoretic tools. Under some assumptions, the bound in \eqref{eq:bon_scale_tight} is tight. Furthermore, using Pinsker's inequality, in a similar approach to \citep{mroueh2024information}, we have, 
\begin{equation}\label{eq:KL-reward}
    \begin{split}
        &\mathbb{E}_{Y\sim\pisbontrue(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]\\&\leq R_{\max}\sqrt{\frac{1}{2}\KLr(\pisbontrue(\cdot|x)\|\pirefer(\cdot|x))}.
    \end{split}
\end{equation}
Note that \eqref{eq:KL-reward} implies that improvement of expected true reward relative to the reference policy can not exceed the square root of the KL divergence. However, the analysis of KL divergence for the SBoN policy under the true reward model is overlooked. Therefore, we first establish an upper bound on the KL divergence between the SBoN policy under the true reward model and the reference policy, shedding light on its behaviour as a function of the number of samples $N$ and temperature parameter $\beta$. All proof details are deferred to App.~\ref{app:proofs_kl}.
\begin{lemma}\label{lem:scale_law_sbon}
    Under Assumption~\ref{ass:bounded_reward}, the following upper bound holds on KL divergence between SBoN and reference policies for a given prompt $x\in\mathcal{X}$,
       \begin{equation}
       \begin{split}
            &\KLr(\pisbontrue(y|x)\|\pirefer(y|x))\\&\leq \log\Big(\frac{N}{1+(N-1)\exp(-\beta R_{\max})}\Big).
       \end{split}
    \end{equation}
\end{lemma}
Using Lemma~\ref{lem:scale_law_sbon}, we can observe that for BoN, $\beta\rightarrow\infty$, we have,
    \begin{equation}\label{eq:bon_scale_loose}
    \begin{split}
               \KLr(\pibontrue(y|x)\|\pirefer(y|x))\leq \log(N).
    \end{split}
    \end{equation}
    Comparing \eqref{eq:bon_scale_loose} with results in \citep{beirami2024theoretical,mroueh2024information}, our result is derived from the SBoN asymptotic regime. Note that our bound is looser than the bound on KL divergence in \eqref{eq:bon_scale_tight}. In contrast, our bound is general and can be applied to different $\beta$ in SBoN. For $\beta=0$, where our policy is the reference policy, our bound is tight. It is also important to note that the upper bound in Lemma~\ref{lem:scale_law_sbon} increases with the temperature parameter  $\beta$ for fixed $N$. Note that the result in Lemma~\ref{lem:scale_law_sbon} also holds for an arbitrary bounded reward model.


Recent works by \citet{gao10256836framework} and \citet{hilton2022measuring} empirically demonstrate that, under a true reward model, the improvement in expected true reward, relative to a reference policy, scales proportionally to $\sqrt{\KLr(\pibontrue \| \pirefer)}$ for both RL and BoN policies. It is also observed by \citet{gao2023scaling} that models optimized using proxy rewards can suffer from overoptimization where the learned policy diverges further from the reference, the alignment may degrade. Despite theoretical advances, the KL divergence analysis for SBoN and BoN under the proxy reward model remains largely unexplored. Therefore, we are interested in investigating the improvement of expected true reward with respect to the SBoN policy under the proxy reward model relative to the reference policy. For this purpose, we first propose the following useful Lemma to study the closeness of the SBoN policy under the true reward model to the SBoN policy under the proxy reward model in KL divergence measure.
\begin{lemma}\label{lem:KL_sbon_true_proxy}
      Under Assumption~\ref{ass:bounded_reward} and \ref{ass:bounded_est_reward}, the following upper bound holds on the KL divergence between the SBoN policies under true reward and proxy reward models respectively,
    \begin{align}\label{eq:approx}
   &\KLr(\pisbontrue(\cdot|x)\|\pisbon(\cdot|x))
       \\\nonumber& \leq\frac{N\beta\sqrt{\varepsilon_{\beta,r}(x)}}{1+(N-1)\exp(-\beta R_{\max})}\Big(\frac{N\exp(2\beta R_{\max})}{{( N-1)^2}}+1\Big).
            \end{align} 
    % where $E(\beta)=$.
\end{lemma}
Note that for $\beta=0$, the upper bound in Lemma~\ref{lem:KL_sbon_true_proxy} is tight. Next, we derive our main result for improvement of the expected true reward under the SBoN policy using the proxy model relative to the reference policy model.

\begin{theorem}\label{thm:main_kl}
    Under Assumption~\ref{ass:bounded_reward}, the following upper bound holds on the improvement of expected true reward under the SBoN policy for the proxy reward model, relative to the reference policy, 
   \begin{align}\label{eq:final}\nonumber
    % \begin{split}
      &\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]\\
      &\leq R_{\max}\sqrt{\frac{1}{2}\log\Big(\frac{N}{1+(N-1)\exp(-\beta R_{\max})}\Big)}\\\nonumber
      &\quad+R_{\max}\min\Big(\sqrt{\frac{N\beta\sqrt{\varepsilon_{\beta,r}(x)}A(\beta,N)}{2(1+(N-1)\exp(-\beta R_{\max}))}},1\Big),
    % \end{split}
\end{align}
where $A(\beta,N)=\Big(\frac{N\exp(2\beta R_{\max})}{{( N-1)^2}}+1\Big)$.
\end{theorem}
\begin{proof}[Sketch of Proof]
Note that the following decomposition holds,
\begin{equation*}\label{eq:final_sketch}
    \begin{split}
    &\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]\\
      &=\underbrace{\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pisbontrue(\cdot|x)}[\rstar(Y,x)]}_{I_2}\\
      &\quad+\underbrace{\mathbb{E}_{Y\sim\pisbontrue(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]}_{I_1}.
    \end{split}
\end{equation*}
Using Lemma~\ref{lem:scale_law_sbon} and Lemma~\ref{lem:KL_sbon_true_proxy} in combination with Pinsker's inequality, we can bound $I_1$ and $I_2$, respectively.
\end{proof}
The upper bound in Theorem \ref{thm:main_kl} includes two terms.
The first term represents the upper bound on the expected true reward under the SBoN policy relative to the reference policy; we are interested in maximizing this term. Note that, as mentioned in \citep{gao2023scaling}, the expected true reward under the aligned policy, relative to the reference policy, is proportional to the square root of KL divergence. The second term quantifies the estimation error introduced by substituting a proxy reward model for the true reward model. We aim to minimize the second term. 
% Note that, \(I_{1}\) as the \emph{estimation error} and
% \(I_{2}\) measures the expected‐reward gain achieved by the SBoN policy
% over the reference policy.  Accordingly, our objective is twofold: \text{minimise } $I_{1}$
% and \text{maximize } $I_{2}$.

Next, we compare BoN and SBoN under the no-reward model and reward model overoptimization. 
% \newpage

\begin{remark}[No overoptimization] We can observe that for a given $\beta$, if we assume $\varepsilon_{\beta,r}(x)=0$, then we have $\KLr(\pisbontrue(\cdot|x)\|\pisbon(\cdot|x))=0$. Under this assumption, the upper bound in Theorem \ref{thm:main_kl} simplifies to $R_{\max}\sqrt{\frac{1}{2}\log\Big(\frac{N}{1+(N-1)\exp(-\beta R_{\max})}\Big)}$ which is monotonically increasing in $\beta$. Because a larger KL divergence is desirable in this context, as proposed by \citep{gao2023scaling}, the BoN policy is preferred under no overoptimization scenario.

\end{remark}
\begin{remark}[Overoptimization] When $\varepsilon_{\beta,r}(x)>0$, we have two conflicting goals in Theorem~\ref{thm:main_kl}: one suggesting for fixed $N$ that $\beta$ needs to be smaller for better estimation of the true policy by the proxy reward model one given in second term of \eqref{eq:final}, and another one suggesting a larger $\beta$ to induce a better upper bound on the expected true reward in first term of \eqref{eq:final}. Hence, for a given $N$, there exists an optimal $\beta$ to balance between the estimation error term and the expected true reward under the SBoN policy for the true reward model. In this scenario, SBoN can lead to better tradeoffs than BoN.  A similar discussion can be done for fixed $\beta$ and varying $N$. 
\end{remark}


\section{Regret Analysis}\label{sec:regret}

In this section, we derive theoretical regret bounds for SBoN and BoN. First, we provide a helpful Lemma regarding the expected coverage assumption that can help us interpret the results of regret for BoN and SBoN. All proof details are deferred to App.~\ref{app:regret}.

 % We start with a lemma built on the expected-coverage assumption, which will be used to interpret the ensuing regret results for both methods.

    \begin{lemma}\label{lem:coverage_prop}
Under Assumption~\ref{ass:bounded_reward} and Assumption~\ref{ass:achieve_reward}, the following properties of $\coverconstr(x)$ hold,
\begin{enumerate}
    \item\label{item1} $\coverconstr(x)=\frac{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))}$.
    \item\label{item2} $\coverconstr(x)$ is an increasing function with respect to $\beta$.
    \item\label{item3} $\coverinfr(x)=\frac{1}{\sum_{i}\pirefer(y^{\max}_{i,r}(x)|x)}$ where $y^{\max}_{i,r}(x)\in\arg\max_y r(y,x)$.
    % is $i$-th maximizer of reward function, $r(y_{\max,i},x)=R_{\max}$.
    \item\label{item4} For all $\beta<\infty$, we have $1\leq \coverconstr(x)\leq \min(\coverinfr(x),\exp(2\beta R_{\max}))$.
\end{enumerate}
\end{lemma}

% \end{tcolorbox}

 Now, we derive an upper bound on the regret of SBoN. 

    \begin{theorem}[Optimal Gap of SBoN]\label{thm:gap_sbon}
  Under Assumptions~\ref{ass:bounded_reward}, \ref{ass:bounded_est_reward}, and \ref{ass:achieve_reward}, the following upper bound holds on the optimal regret gap of the SBoN policy for any $\beta > 0$,
   \begin{equation*}
       \begin{split}  &\DeltaJ(\pi^{\star}_{\rstar}\big(\cdot|x\big), \pisbon(\cdot|x))\\&\leq 
     \sqrt{\varepsilon_{\beta,r}(x)}\big(\sqrt{\coverinfrhat(x)}+\sqrt{\coverinfrstar(x)} \big)\\
      &\quad+2R_{\max} \sqrt{\frac{1}{2}\log\Big(1+\frac{\coverinfrhat(x)-1}{N}\Big)}\\
      &\quad+ \frac{\log(\coverinfrstar(x))}{\beta},
       \end{split}
   \end{equation*}
\end{theorem}

\textbf{Regret of BoN Through Smoothing Lens:}
We now derive an upper bound on the regret of BoN by taking the asymptotic limit of the regret bound on optimal gap of SBoN in Theorem~\ref{thm:gap_bon}.
% \begin{tcolorbox}
    \begin{theorem}[Optimal Gap of BoN]\label{thm:gap_bon}
 Under Assumptions~\ref{ass:bounded_reward}, \ref{ass:bounded_est_reward}, and \ref{ass:achieve_reward}, the following upper bound holds on the optimal regret gap of the BoN policy for any $\beta > 0$,
\begin{equation*}
\begin{split}
&\DeltaJ(\pi^{\star}_{\rstar}(\cdot|x), \pibonEST(\cdot|x))
\\&\leq \sqrt{\varepsilon_{\infty,r}(x)}\big(\sqrt{\coverinfrhat(x)}+\sqrt{\coverinfrstar(x)} \big)\\&\quad+ 2 R_{\max}\sqrt{\frac{1}{2}\log\Big(1+\frac{\coverinfrhat(x)-1}{N}\Big)}.
\end{split}
\end{equation*}
\end{theorem}
