\begin{remark}[Comparison with \citep{huang2025best}]
    The regret bound for BoN policy grows with the $L_{\infty}$-norm of the reward-model estimation error.  In contrast to the result in ~\citep{huang2025best}, our bound remains finite whenever the overoptimization error vanishes, i.e., when $\varepsilon_{\infty,\beta}(x)=0$ or $N$ grows.
     \end{remark}

    \begin{remark}[Quality of reference policy]

   Furthermore, the bound stated in Theorem~\ref{thm:gap_bon} (or Theorem~\ref{thm:gap_sbon}) depends on the quantity,
\[
\coverinfrstar(x)\;=\;\frac{1}{\sum_{i}\pi_{\mathrm{ref}}\!\bigl(y^{\max}_{i,\rstar}(x)\mid x\bigr)},
\]
where $y^{\max}_{i,\rstar}(x)\in\arg\max_{y}\rstar(y,x)$. It can be interpreted as the quality of reference policy under the true reward model. Similarly, the bound in Theorem~\ref{thm:gap_bon} (or Theorem~\ref{thm:gap_sbon}) depends on the quantity,
\[
\coverinfrhat(x)\;=\;\frac{1}{\sum_{i}\pi_{\mathrm{ref}}\!\bigl(y^{\max}_{i,\rhat}(x)\mid x\bigr)},
\]
where $y^{\max}_{i,\rhat}(x)\in\arg\max_{y}\rhat(y,x)$. It can be interpreted as quality of reference policy under the proxy reward model. Therefore, the quality of reference policy under both true and proxy reward models affect the performance of BoN and SBoN policies.
\end{remark}

Next, we compare how BoN and SBoN perform when overoptimization is present and when it is absent.

\begin{remark}[Overoptimization]
Assume that the proxy reward suffers from overoptimization, i.e.\ $\varepsilon_{\beta,r}(x)>0$ for every $\beta>0$.  
Letting $N\to\infty$ and invoking Theorem~\ref{thm:gap_sbon}, we obtain
\begin{equation}\label{eq:asympt_sbon}
\begin{split}
&\DeltaJ\!\bigl(\pi_{r_\star}^{\star}(\cdot\mid x),
                  \pi_{\hat r}^{(\infty,\beta)}(\cdot\mid x)\bigr)
\\&\le
\sqrt{\varepsilon_{\beta,r}(x)}
      \Bigl(\sqrt{\coverinfrhat(x)}
           +\sqrt{\coverinfrstar(x)}\Bigr)
      \\&\quad+\frac{\log \coverinfrstar(x)}{\beta}.
      \end{split}
\end{equation}
Similarly, for BoN we have,
\begin{equation}\label{eq:asympt_bon}
\begin{split}
&\DeltaJ\!\bigl(\pi_{r_\star}^{\star}(\cdot\mid x),
                  \pi_{\hat r}^{(\infty,\infty)}(\cdot\mid x)\bigr)
\\&\le
\sqrt{\varepsilon_{\infty,r}(x)}
      \Bigl(\sqrt{\coverinfrhat(x)}
           +\sqrt{\coverinfrstar(x)}\Bigr).
           \end{split}
\end{equation}
Define the auxiliary function
\[
g(\beta)\;=\;\beta\bigl(\varepsilon_{\infty,r}(x)-\varepsilon_{\beta,r}(x)\bigr), 
\qquad \beta\ge 0.
\]
Because $g(0)=g(\infty)=0$ and $g(\beta)\ge 0$ for all $\beta$, there exists at least one maximizer  
$\beta^{\star}\in(0,\infty)$ such that 
$g(\beta^{\star})=\max_{\beta\ge 0} g(\beta)$.

% \smallskip
% \noindent
% Let $\DeltaJ_{\mathrm{BoN}}^{(\infty)}(x)$ denote the asymptotic bound for BoN obtained in the same limit.  
If
\begin{equation}\label{eq:sbon_better_cond}
\frac{\log C_{\infty,r_\star,\mathrm{ref}}(x)}
     {\sqrt{C_{\beta,\hat r,\mathrm{ref}}(x)}
      +\sqrt{C_{\infty,r_\star,\mathrm{ref}}(x)}}
\;\;\le\;\;
g(\beta^{\star}),
\end{equation}
then the upper bound in \eqref{eq:asympt_sbon} does not exceed  
\eqref{eq:asympt_bon}, and hence the bound on the regret of the SBoN policy is \emph{tighter} than the bound on the regret of the BoN policy under the proxy reward model.  An analogous comparison can be carried out for any fixed $\beta$ and changing $N$.
\end{remark}



\begin{remark}[No overoptimization]
Assume that the overoptimization vanishes, i.e.\ $\varepsilon_{\beta,r}(x)=0$ for every $\beta\in[0,\infty)$.  Then the optimality gaps of the SBoN and BoN policies satisfy
\begin{equation}\label{eq:sbon_no_overopt}
\begin{split}
&\DeltaJ\!\bigl(\pi_{r_\star}^{\star}(\cdot\mid x),\,
               \pi_{\hat r}^{(N,\beta)}(\cdot\mid x)\bigr)
\\\nonumber&\;\le\;
2R_{\max}\sqrt{\frac12\log\!\Bigl(1+\frac{\coverinfrhat(x)-1}{N}\Bigr)}
\;\\\nonumber&\quad+\;
\frac{\log C_{\infty,r_\star,\mathrm{ref}}(x)}{\beta},
\end{split}
\end{equation}
\begin{equation}\label{eq:bon_no_overopt}
\begin{split}
&\DeltaJ\!\bigl(\pi_{r_\star}^{\star}(\cdot\mid x),\,
               \pi_{\hat r}^{(N,\infty)}(\cdot\mid x)\bigr)
\\&\;\le\;
2R_{\max}\sqrt{\frac12\log\!\Bigl(1+\frac{\coverinfrhat(x)-1}{N}\Bigr)}.
\end{split}
\end{equation}
By Lemma~\ref{lem:coverage_prop}, $C_{\infty,r_\star,\mathrm{ref}}(x)\ge 1$; consequently, the bound in~\eqref{eq:bon_no_overopt} is tighter than the bound in~\eqref{eq:sbon_no_overopt}.
\end{remark}


\section{Empirical Evidence}\label{sec:exp}
To support our theoretical analysis, we conducted experiments comparing Soft Best-of-N (SBoN) across different regularization strengths and reward model qualities. We used the Olmo-2 1B model \citep{olmo20242} as the generator and prompts from the Attaq dataset \citep{kour2023unveiling}. For each prompt, we generated multiple responses and selected one using SBoN with varying temperature values $\beta$. We ran two experimental conditions: one using a strong reward model (ArmoRM 8B \citep{ArmoRM}) which is close to true reward model, and another using a weaker reward model (Beaver 7B RM \citep{dai2023safe}). We use LLM-as-a-Judge \cite{zheng2023judging} as our $r^*$. As shown in Figure~\ref{fig:combined}, when the reward model is weak, performance degrades for large $N$ due to reward hacking. However, the smoothing in SBoN helps mitigate this degradation. This observation is also aligned with our theoretical analysis and discussion in Section~\ref{sec:scale_law}, where under overoptimization there exists a $\beta$ for a given $N$ which outperforms BoN. For more details, see App.~\ref{app:experiments}. We also studied the behavior of our upper bound on the KL divergence between the SBoN policy and the reference policy, Lemma~\ref{lem:KL_sbon_true_proxy}, at App.~\ref{app:numerical_example}.
\section{Conclusion}
In this work, we establish a theoretical foundation for alignment strategies based on Soft Best-of-N (SBoN) and Best-of-N (BoN) policies. Specifically, we derive upper bounds on the KL divergence between the aligned policy—such as SBoN or BoN—and the reference policy. We also studied the regret gap between the optimal policy and the aligned policy, e.g., BoN and SBoN policies. We further analyze how errors in reward estimation affect performance in both KL divergence and regret gap. Notably, both our theoretical analysis and empirical results demonstrate that, under a proxy reward model where overoptimization happens, SBoN perform better than BoN under some conditions.
