\section{Gumbel–Max trick}\label{app:gumble}
% \begin{remark}[] \normalfont
We also provide an interpretation for SBoN from the Gumbel-Max trick. An alternative way to sample \(Z\) from
\begin{equation*}
\Pr(Z=i)\;\propto\;\exp\bigl(\beta\,\hat r(Y_i,x)\bigr)
\end{equation*}
is via the Gumbel–Max trick.  We can draw independent Gumbel-distributed random variables
$
G_i\sim\mathrm{Gumbel}(0,1), i=1,\dots,n,
$
and then set
\begin{equation*}
Z =\arg\max_{i\in\{1,\dots,N\}}\biggl[\hat r(Y_i,x)+\frac{G_i}{\beta}\biggr].
\end{equation*}
By properties of the Gumbel distribution, this yields exactly the same
softmax sampling law, without needing to compute the normalizing factor $\sum_{j=1}^N \exp(\beta\hat{r}(Y_j,x))$ explicitly \citep{gumbel1954statistical}. When $\beta\to\infty$, the effect of the Gumbel noises vanishes and the sampling strategy reduces to BoN.
% \end{remark}
\section{Technical Tools}

We denote the set maximizers of the estimated reward via $\hat{\mathcal{Y}}(x)=\{\hat{y}_{j}(x)\}_{j=1}^{m(x)}$. 

We introduce the functional derivative, see~\cite{cardaliaguet2019master}. 
\begin{definition}{\citep{cardaliaguet2019master}}
\label{def:flatDerivative}
A functional $U:\mathcal P(\mathbb R^n) \to \mathbb R$ %is said to 
admits a functional derivative
if there is a map $\frac{\delta U}{\delta m} : \mathcal P(\mathbb R^n) \times \mathbb R^n \to \mathbb R$ which is continuous on $\mathcal P(\mathbb R^n)$ and, for all
$m, m' \in\mathcal P(\mathbb R^n)$, it holds that
\begin{align*}
&U(m') - U(m) =\!\int_0^1 \int_{\mathbb{R}^n} \frac{\delta U}{\delta m}(m_\beta,a) \, (m'
-m)(da)\,\mrd \beta,
\end{align*}
where $m_\beta=m + \beta(m' - m)$.
\end{definition}

\begin{definition}[Sensitivity of a policy]
    We also define the sensitivity of a policy $\pi_r(y|x)$, which is a function of reward function $r(x,y)$, with respect to the reward function as
\begin{equation}
    \frac{\partial \pi}{\partial r}(r):=\lim_{\Delta r\rightarrow 0}\frac{\pi_r(y|x)-\pi_{r+\Delta r}(y|x)}{\Delta r}.
\end{equation}
\end{definition}

\begin{lemma}[Kantorovich-Rubenstein duality of total variation distance, see ~\citep{polyanskiy2022information}]\label{lem: tv} The Kantorovich-Rubenstein duality (variational representation) of the total variation distance is as follows:
\begin{equation}\label{Eq: tv rep}
    \mathbb{TV}(m_1,m_2)=\frac{1}{2L}\sup_{g \in \mathcal{G}_L}\left\{\mathbb{E}_{Z\sim m_1}[g(Z)]-\mathbb{E}_{Z\sim m_2}[g(Z)]\right\},
\end{equation}
where $\mathcal{G}_L=\{g: \mathcal{Z}\rightarrow \mathbb{R}, ||g||_\infty \leq L \}$. 
\end{lemma}

   \begin{lemma}[Lemma~5.4 in \citep{aminian2025theoretical}]\label{lem:sensivitiy_policy}
Consider the softmax policy, $\pi_r^\beta(y|x)\propto\pirefer(y|x)\exp(\beta r(x,y))$. Then, the sensitivity of the policy with respect to the reward function is
\begin{equation*}
    \frac{\partial \pi_r^\beta}{\partial r}(r)=\beta \pi_r^\beta(y|x) (1-\pi_r^\beta(y|x)).
\end{equation*}
\end{lemma}

\begin{lemma}[Pinsker’s Inequality~\citep{canonne2022short}]\label{lem:pinsker}
For $m_1$ and $m_2$, we have,
\begin{equation}
    \mathbb{TV}(m_1,m_2)\leq \sqrt{\frac{1}{2}\KLr(m_2\|m_1)}\,.
\end{equation}
\end{lemma}


The following Lemmata are useful for our technical proofs.
\begin{lemma}\label{lem:Zbound}
    Under Assumption~\ref{ass:bounded_est_reward}, the following upper bound holds,
    \begin{equation}
        \log\Big(\frac{\zstar}{\zhat} \Big)\leq \beta  \sqrt{ \varepsilon_{\beta,r}(x)}\sqrt{\coverconstrstar(x)}.
    \end{equation}
\end{lemma}
\begin{proof}
    \begin{equation}
    \begin{split}
        \frac{\zhat}{\zstar} &=\frac{\sum_{\mathcal{Y}}\exp(\beta\rhat(y,x))\pirefer(y|x)}{\sum_{\mathcal{Y}}\exp(\beta\rstar(y,x))\pirefer(y|x)}\\
&=\frac{\sum_{\mathcal{Y}}\exp(\beta(\rhat(y,x)-\rstar(y,x))) \exp(\beta\rstar(y,x))\pirefer(y|x)}{\sum_{\mathcal{Y}}\exp(\beta\rstar(y,x))\pirefer(y|x)}\\
&=\sum_{\mathcal{Y}} \pibetarstar(y|x) \exp(\beta(\rhat(y,x)-\rstar(y,x)))
    \end{split}
    \end{equation}
    Due to convexity of $-\log(\cdot)$ and using Cauchy–Schwarz inequality, we have,
     \begin{equation}
 \begin{split}
      -\log\Big(\frac{\zhat}{\zstar} \Big)&\leq \beta \sum_{\mathcal{Y}} \pibetarstar(y|x) (\rstar(y,x)-\rhat(y,x))\\
      & \leq \beta \sum_{\mathcal{Y}} \frac{\pibetarstar(y|x)}{\pirefer(y|x)} (\rstar(y,x)-\rhat(y,x))\pirefer(y|x)\\
        &\leq \beta \sqrt{\sum_{\mathcal{Y}} (\rstar(y,x)-\rhat(y,x))^2\pirefer(y|x)}\sqrt{\sum_{\mathcal{Y}}\frac{\pibetarstar^2(y|x)}{\pirefer(y|x)}}\\
        &=\sqrt{\beta}  \sqrt{\sum_{\mathcal{Y}} \log\big(\exp\big(\beta(\rstar(y,x)-\rhat(y,x))^2\big)\big)\pirefer(y|x)}\sqrt{\coverconstrstar(x)}\\
        &\leq \beta  \sqrt{ \frac{1}{\beta}\log\big(\sum_{\mathcal{Y}}\exp\big(\beta(\rstar(y,x)-\rhat(y,x))^2\big)\pirefer(y|x)\big)}\sqrt{\coverconstrstar(x)}\\
         &= \beta  \sqrt{ \varepsilon_{\beta,r}(x)}\sqrt{\coverconstrstar(x)},
 \end{split}
    \end{equation}
\end{proof}

\begin{lemma}\label{lem:KL_C}
    Under Assumption~\ref{ass:bounded_reward}, we have,
\begin{equation}
\begin{split}
\KLr(\pi^{\star}_{\rstar}\big(\cdot|x\big)\|\pirefer(\cdot|x))&\leq \log(\coverinfrstar(x))
\end{split}
\end{equation}
\end{lemma}
\begin{proof}
   Note that, under Assumption~\ref{ass:bounded_reward}, we have,
\begin{equation}
\begin{split}
    \KLr(\pi^{\star}_{\rstar}\big(\cdot|x\big)\|\pirefer(\cdot|x))&\leq \log\Big(\mathbb{E}_{Y\sim\pi^{\star}_{\rstar}\big(\cdot|x\big)}\Big[\frac{\pi^{\star}_{\rstar}\big(\cdot|x\big)}{\pirefer(\cdot|x)}\Big] \Big)\\
&\leq\log(\coverinfrstar(x))
\end{split}
\end{equation} 
\end{proof}


\begin{lemma}\label{lem:KLbound}
    Under Assumption~\ref{ass:bounded_reward} and Assumption~\ref{ass:bounded_est_reward}, the following upper bound holds,
    \begin{equation}
        \begin{split}
            \KLr(\pibetarstar(y|x)\|\pibetarhat(y|x))\leq\beta  \sqrt{ \varepsilon_{\beta,r}(x)}\big(\sqrt{\coverconstrstar(x)}+\sqrt{\coverconstrhat(x)}\big).
        \end{split}
    \end{equation}
\end{lemma}
\begin{proof}

    \begin{equation}
        \begin{split}
            \KLr(\pibetarstar(y|x)\|\pibetarhat(y|x))&=\sum_{\mathcal{Y}} \pibetarstar(y|x)\log\Big(\frac{\pibetarstar(y|x)}{\pibetarhat(y|x)}\Big)\\
            &= \beta \sum_{\mathcal{Y}} (\rstar(y,x)-\rhat(y,x)) \pibetarstar(y|x) + \log(\zhat/\zstar)\\
            &\leq \beta  \sqrt{ \varepsilon_{\beta,r}(x)}\big(\sqrt{\coverconstrstar(x)}+\sqrt{\coverconstrhat(x)}\big),
        \end{split}
    \end{equation}
    where the final inequality holds due to Lemma~\ref{lem:Zbound} and applying Cauchy–Schwarz inequality.
\end{proof}

\begin{lemma}\label{lem:asy}
    Suppose that $f(Z)\in[0,Z_{\max}]$, $\mathcal{Z}_{\max}=\{z_{m,i}\}_{i=1}^m$ is the set of miximizers of $f(Z)$, i.e., $f(z)=Z_{\max}$ for $z\in \mathcal{Z}_{\max}$. Then we have,
    \begin{equation}
        \lim_{\beta\rightarrow \infty}\frac{\mathbb{E}[\exp(2\beta f(Z))]}{\mathbb{E}[\exp(\beta f(Z))]^2}= \frac{1}{\sum_{z\in\mathcal{Z}_{\max}} P(Z=z)}.
    \end{equation}
\end{lemma}
\begin{proof}
    \begin{align}
        &\frac{\mathbb{E}[\exp(2\beta f(Z))]}{\mathbb{E}[\exp(\beta f(Z))]^2}=\frac{\mathbb{E}[\exp(2\beta (f(Z)-Z_{\max}))]}{\mathbb{E}[\exp(\beta (f(Z)-Z_{\max}))]^2}\\
        &\frac{\sum_j P(Z=z_j)\exp(2\beta (f(z_j)-Z_{\max}))}{(\sum_j P(Z=z_j)\exp(\beta (f(z_j)-Z_{\max})))^2}
    \end{align}
    Now, we have,
    \begin{align}
         &\lim_{\beta\rightarrow\infty}\frac{\mathbb{E}[\exp(2\beta f(Z))]}{\mathbb{E}[\exp(\beta f(Z))]^2}\\
        &=\lim_{\beta\rightarrow\infty}\frac{\sum_j P(Z=z_j)\exp(2\beta (f(z_j)-Z_{\max}))}{(\sum_j P(Z=z_j)\exp(\beta (f(z_j)-Z_{\max})))^2}\\
        &=\frac{\sum_{z\in\mathcal{Z}_{\max}} P(Z=z)}{(\sum_{z\in\mathcal{Z}_{\max}} P(Z=z))^2}\\
        &=\frac{1}{\sum_{z\in\mathcal{Z}_{\max}} P(Z=z)},
    \end{align}
    where we used the fact that $\lim_{\beta\rightarrow\infty}\exp(\beta (z_j-Z_{\max}))=0$ for $z_j<Z_{\max}$.
\end{proof}

\begin{lemma}[Theorem~1 in \citep{Flavio2025SoftBoN}]\label{lem:flavio}For $\beta>0$, and $N\geq 1$, we have,
\begin{equation}
    \KLr(\pibetarstar(\cdot|x)\|\pisbontrue(y|x))\leq \log(1+\frac{\coverconstrstar(x)}{N}).
\end{equation}

\end{lemma}

\begin{lemma}\label{lem:sbon_diff}
    Under Assumption~\ref{ass:bounded_reward}, we have,
    \begin{equation}
       \Big|\frac{f(r)}{\delta r}\Big|\leq \frac{N^2\beta\exp(2\beta R_{\max})}{{( N-1)^2}},
    \end{equation}
  where $f(r)=\log\big(\mathbb{E}[\frac{1}{\exp(\beta r)+\sum_{i=1}^{N-1} \exp(\beta R_i)}]\big)$, $r=r(x,y)$ and $R_i=r(Y_i,x)$.
\end{lemma}
\begin{proof}
Note that $\{R_i\}_{i=1}^{N-1}$ are i.i.d.\, . Therefore, we have,
    \begin{equation}
        \begin{split}
            \frac{\delta f(r(y,x))}{\delta r}&=\mathbb{E}[\frac{1}{\exp(\beta r)+\sum_{i=1}^{N-1} \exp(\beta R_i)}]^{-1}\frac{\delta \mathbb{E}[\frac{1}{\exp(\beta r)+\sum_{i=1}^{N-1} \exp(\beta R_i)}]}{\delta r}\\
            &\leq \mathbb{E}[\frac{1}{\exp(\beta r)+\sum_{i=1}^{N-1} \exp(\beta R_i)}]^{-1}\\&\quad\times\Big(\sum_{k=1}^{N}\frac{\beta k\binom{N-1}{k-1}\exp(\beta r)}{(k\exp(\beta r)+ N-1-k)^2} (1-P(R=r))^{N-k}P^{k-1}(R=r)\Big)\\
            &\leq \mathbb{E}[\frac{1}{\exp(\beta r)+\sum_{i=1}^{N-1} \exp(\beta R_i)}]^{-1}\\&\quad\times\frac{\beta\exp(\beta R_{\max})}{{( N-1)^2}}\Big(\sum_{k=1}^{N} k\binom{N-1}{k-1} (1-P(R=r))^{N-k}P^{k-1}(R=r)\Big)\\
            &\leq \frac{N\beta\exp(2\beta R_{\max})}{{( N-1)^2}}(1+(N-1)P(R=r))\\
            &\leq \frac{N^2\beta\exp(2\beta R_{\max})}{{( N-1)^2}}.
        \end{split}
    \end{equation}
\end{proof}

\section{Proof and Details of Section~\ref{sec:scale_law}}\label{app:proofs_kl}
\begin{tcolorbox}
    \begin{replemma}{lem:scale_law_sbon}
    Under Assumption~\ref{ass:bounded_reward}, The following upper bound holds on KL divergence between SBoN and reference policies for a given prompt $x\in\mathcal{X}$,
       \begin{equation}
       \begin{split}
            \KLr(\pisbontrue(y|x)\|\pirefer(y|x))\leq \log\Big(\frac{N}{1+(N-1)\exp(-\beta R_{\max})}\Big).
       \end{split}
    \end{equation}
\end{replemma}
\end{tcolorbox}
\begin{proof}
Recall that,
\[\pisbontrue(y|x)=\pirefer(y|x) \exp(\beta \rstar(y,x))\mathbb{E}\Big[\big( \frac{1}{N}(\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1}\exp(\beta \rstar(Y_i,x)))\big)^{-1}\Big].\]
% and the following Taylor series,
% \begin{equation}
%     \frac{1}{1+x}=\sum_{i=0}^\infty (-x)^i.
% \end{equation}
Now, we have,
    \begin{equation}\label{eq:SL1}
    \begin{split}
                &\KLr(\pisbontrue(y|x)\|\pirefer(y|x))\\&=\sum_{\mathcal{Y}} \pisbontrue(y|x)\log(\pisbontrue(y|x)/\pirefer(y|x))\\
                &=\sum_{\mathcal{Y}} \pisbontrue(y|x)\log(N)+ \sum_{\mathcal{Y}} \pisbontrue(y|x)\log(\mathbb{E}\Big[\big(\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1}\exp(\beta \rstar(Y_i,x))\big)^{-1}\Big])\\
                &=\log(N) + \sum_{\mathcal{Y}} \pisbontrue(y|x)\log(\mathbb{E}\Big[\big(1+\sum_{i=1}^{N-1}\exp(\beta (\rstar(Y_i,x)-\rstar(y,x)))\big)^{-1}\Big]),
    \end{split}
    \end{equation}

    % \begin{equation}
    %     TV(p,q)\leq\min(\sqrt{\frac{1}{2}\KLr(p\|q}),\sqrt{\frac{1}{2}\KLr(q\|p})) 
    % \end{equation}
    For the second term in \eqref{eq:SL1}, consider
    \[A(y,Y,x)=\sum_{i=1}^{N-1}\exp(\beta (\rstar(Y_i,x)-\rstar(y,x)))>0,\]
    where under Assumption~\ref{ass:bounded_reward}, we have \[(N-1)\exp(-\beta R_{\max})\leq A(y,Y,x)\leq (N-1)\exp(\beta R_{\max}).\]
   Therefore, we have,
   \begin{equation}\label{eq:SL2}
    \begin{split}
          &\sum_{\mathcal{Y}} \pisbontrue(y|x)\log(\mathbb{E}\Big[\big(1+\sum_{i=1}^{N-1}\exp(\beta (\rstar(Y_i,x)-\rstar(y,x)))\big)^{-1}\Big]) \\
        &\leq\sum_{\mathcal{Y}} \pisbontrue(y|x) \log(\frac{1}{1+(N-1)\exp(-\beta R_{\max})}) \\
        &=\log(\frac{1}{1+(N-1)\exp(-\beta R_{\max})}).
    \end{split}
    \end{equation}

    Combining \eqref{eq:SL2} with \eqref{eq:SL1}  completes the proof.

\end{proof}


\begin{tcolorbox}
   \begin{replemma}{lem:KL_sbon_true_proxy}
       Under Assumption~\ref{ass:bounded_reward} and \ref{ass:bounded_est_reward}, the following upper bound holds on the KL divergence between the SBoN policies under true reward and proxy reward models respectively,
    \begin{equation}
    \begin{split}
                &\KLr(\pisbontrue(\cdot|x)\|\pisbon(\cdot|x))\\
        &\leq \frac{N\beta\sqrt{\varepsilon_{\beta,r}(x)}}{1+(N-1)\exp(-\beta R_{\max})}\Big(\frac{N\exp(2\beta R_{\max})}{{( N-1)^2}}+1\Big).
            \end{split}
    \end{equation}
   \end{replemma} 
\end{tcolorbox}

\begin{proof}
We first provide the following upper bound,
\begin{equation}\label{eq:kl-b}
    \begin{split}
         &\KLr(\pisbontrue(y|x)\|\pisbon(y|x))\\
            &= \sum_{\mathcal{Y}}\pisbontrue(y|x)\log\big(\frac{\pisbontrue(y|x)}{\pisbon(y|x)}\big) \\
            &= \sum_{\mathcal{Y}}\pisbontrue(y|x)\beta(\rstar(y,x)-
            \rhat(y,x)) \\&\quad+  \sum_{\mathcal{Y}}\pisbontrue(y|x) \Big(\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rstar(Y_i,x))}]\big)\\&\qquad\qquad-\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rhat(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rhat(Y_i,x))}]\big)\Big) \\
             &\leq \frac{N\beta\sqrt{\varepsilon_{\beta,r}(x)}}{1+(N-1)\exp(-\beta R_{\max})} \\
             &\quad + \sum_{\mathcal{Y}}\pisbontrue(y|x) \Big(\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rstar(Y_i,x))}]\big)\\&\qquad\qquad-\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rhat(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rhat(Y_i,x))}]\big)\Big).
    \end{split}
\end{equation}
Note that for the last term in \eqref{eq:kl-b}, we can apply the mean-value theorem as follows,
\begin{equation}\label{eq:kl-1}
    \begin{split}
        &\sum_{\mathcal{Y}}\pisbontrue(y|x) \Big(\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rstar(Y_i,x))}]\big)\\&\qquad\qquad-\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rhat(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rhat(Y_i,x))}]\big)\Big)\\
        &\leq  \sum_{\mathcal{Y}}\pisbontrue(y|x) |\rstar(y,x)-\rhat(y,x)| \Big|\frac{\delta f(r_\gamma(y,x))}{\delta r}\Big|,
    \end{split}
\end{equation}
where $f(r_\gamma(y,x))=\log\big(\mathbb{E}[\frac{1}{\exp(\beta r_{\gamma}(y,x))+\sum_{i=1}^{N-1} \exp(\beta r_{\gamma}(Y_i,x))}]\big)$, for some $\gamma\in(0,1)$ we have $r_{\gamma}(y,x)=\gamma \rhat(y,x)+(1-\gamma)\rstar(y,x)$. Using Lemma~\ref{lem:sbon_diff}, we have,
\begin{equation}\label{eq:kl-2}
    \begin{split}
    \Big| \frac{\delta f(r(y,x))}{\delta r}\Big|&\leq \frac{N^2\beta\exp(2\beta R_{\max})}{{( N-1)^2}}.
    % \beta H_{N}\Big( \mathbb{E}[\frac{1}{\exp(\beta r(y,x))+\sum_{i=1}^{N-1} \exp(\beta r(Y_i,x))}]\Big)^{-1}\\
    % &\leq \beta H_N N\exp(\beta R_{\max}),
    \end{split}
\end{equation}
% where $H_N=\sum_{i}^N\frac{1}{i}$. 
Using \eqref{eq:kl-2} in \eqref{eq:kl-1} and applying Cauchy–Schwarz inequality, we have,
\begin{equation}\label{eq:kl-3}
    \begin{split}
        &\sum_{\mathcal{Y}}\pisbontrue(y|x) \Big(\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rstar(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rstar(Y_i,x))}]\big)\\&\qquad\qquad-\log\big(\mathbb{E}[\frac{1}{\exp(\beta \rhat(y,x))+\sum_{i=1}^{N-1} \exp(\beta \rhat(Y_i,x))}]\big)\Big)\\
        &\leq\sqrt{\sum_{\mathcal{Y}}\mathbb{E}[1/(1+\sum_{i=1}^{N-1}\exp(\beta(\rstar(Y_i,x)-\rstar(y,x))))]^2\pirefer(y|x)} \\&\quad\times\sqrt{\sum_{\mathcal{Y}}|\rstar(y,x)-\rhat(y,x)|^2 \pirefer(y|x) }\sqrt{\sum_{\mathcal{Y}}\Big|\frac{\delta f(r_\gamma(y,x))}{\delta r}\Big|^2\pirefer(y|x)}\\
        &\leq   \frac{\sqrt{\varepsilon_{\beta,r}(x)}}{1+(N-1)\exp(-\beta R_{\max})}\frac{N^2\beta\exp(2\beta R_{\max})}{{( N-1)^2}}.
    \end{split}
\end{equation}
It completes the proof.
\end{proof}
\begin{tcolorbox}
    \begin{reptheorem}{thm:main_kl}
    Under Assumption~\ref{ass:bounded_reward}, the following upper bound holds on the improvement of expected true reward under the SBoN policy for the proxy reward model, relative to the reference policy, 
   \begin{equation*}
    \begin{split}
      &\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]\\
      &\leq R_{\max}\sqrt{\frac{1}{2}\log\Big(\frac{N}{1+(N-1)\exp(-\beta R_{\max})}\Big)}\\
      &\quad+R_{\max}\min\Big(\sqrt{\frac{N\beta\sqrt{\varepsilon_{\beta,r}(x)}A(\beta,N)}{1+(N-1)\exp(-\beta R_{\max})}},1\Big),
    \end{split}
\end{equation*}
where $A(\beta,N)=\Big(\frac{N\exp(2\beta R_{\max})}{{( N-1)^2}}+1\Big)$.
\end{reptheorem}
\end{tcolorbox}

\begin{proof}
Note that the following decomposition holds,
\begin{equation*}
    \begin{split}
    &\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]\\
      &=\underbrace{\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pisbontrue(\cdot|x)}[\rstar(Y,x)]}_{I_2}\\
      &\quad+\underbrace{\mathbb{E}_{Y\sim\pisbontrue(\cdot|x)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pirefer(\cdot|x)}[\rstar(Y,x)]}_{I_1}.
    \end{split}
\end{equation*}
\end{proof}
Using Lemma~\ref{lem:scale_law_sbon} and Lemma~\ref{lem:KL_sbon_true_proxy} completes the proof.
