\section{Proof and details of Section~\ref{sec:regret}}\label{app:regret}

% \subsection{Upper Bound on Regret}
% \todob{why do we care about this lemma? What is the main implication?}\todoa{More details are added.}
\begin{tcolorbox}
    \begin{replemma}{lem:coverage_prop}
Under Assumption~\ref{ass:bounded_reward} and Assumption~\ref{ass:achieve_reward}, the following properties of $\coverconstr(x)$ hold,
\begin{enumerate}
    \item $\coverconstr(x)=\frac{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))}$.
    \item $\coverconstr(x)$ is an increasing function with respect to $\beta$.
    \item $\coverinfr(x)=\frac{1}{\sum_{i}\pirefer(y^{\max}_{i,r}(x)|x)}$ where $y^{\max}_{i,r}(x)\in\arg\max_y r(y,x)$.
    % is $i$-th maximizer of reward function, $r(y_{\max,i},x)=R_{\max}$.
    \item For all $\beta<\infty$, we have $1\leq \coverconstr(x)\leq \min(\coverinfr(x),\exp(2\beta R_{\max}))$.
\end{enumerate}
\end{replemma}
\end{tcolorbox}

\begin{proof}
    \begin{enumerate}
        \item \begin{equation}
            \begin{split}
                \coverconstrhat(x)&=\sum_{\mathcal{Y}}\frac{\pibetarhat^2(y|x)}{\pirefer(y|x)}\\
                &=\sum_{\mathcal{Y}}\frac{\exp(2\beta\rhat(y,x))}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))]}\pirefer(y|x)\\
                &=\frac{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))]}.
                \end{split}
        \end{equation}
        \item We can show that the logarithm function of $\coverconstrhat(x)$ is increasing. Then, due to the increasing feature of the log function, the final result holds. \begin{equation}\label{eq:dif1}
            \begin{split}
              &\log(\frac{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))]})\\
              &=\log(\mathbb{E}[\exp(2\beta\rhat(Y,x))])-2\log(\mathbb{E}[\exp(\beta \rhat(Y,x))]),
            \end{split}
        \end{equation}
        then we can compute the derivative of \eqref{eq:dif1},
        \begin{equation}
            \begin{split}
                &\frac{\mrd \log(\mathbb{E}[\exp(2\beta\rhat(Y,x))])}{\mrd \beta}-2\frac{\mrd \log(\mathbb{E}[\exp(\beta \rhat(Y,x))]}{\mrd \beta}\\
                &=\frac{\mathbb{E}[2\rhat(Y,x)\exp(2\beta\rhat(Y,x))]}{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}-2\frac{\mathbb{E}[\rhat(Y,x)\exp(\beta\rhat(Y,x))]}{\mathbb{E}[\exp(\beta\rhat(Y,x))]}
            \end{split}
        \end{equation}
        Note that we have,
        \begin{equation}
        \begin{split}
                        \frac{\mrd \frac{\mathbb{E}[\rhat(Y,x)\exp(\beta\rhat(Y,x))]}{\mathbb{E}[\exp(\beta\rhat(Y,x))]}}{\mrd \beta}&=\frac{\mathbb{E}[\rhat^2(Y,x)\exp(\beta\rhat(Y,x))]\mathbb{E}[\exp(\beta\rhat(Y,x))]-\mathbb{E}[\rhat(Y,x)\exp(\beta\rhat(Y,x))]^2}{\mathbb{E}^2[\exp(\beta\rhat(Y,x))]}\\
&=\mathbb{E}_{Y\sim \pibetarhat(\cdot|x)}[\rhat^2(Y,x)]-\mathbb{E}_{Y\sim \pibetarhat(\cdot|x)}[\rhat(Y,x)]^2\geq 0.
        \end{split}
        \end{equation}
        Therefore, we have, 
        \begin{equation}
            \frac{\mathbb{E}[\rhat(Y,x)\exp(2\beta\rhat(Y,x))]}{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}\geq \frac{\mathbb{E}[\rhat(Y,x)\exp(\beta\rhat(Y,x))]}{\mathbb{E}[\exp(\beta\rhat(Y,x))]}.
        \end{equation}
        It completes the proof.
        \item Follows directly from Lemma~\ref{lem:asy}.
        \item Due to Jensen inequality for $\mathbb{E}^2[\exp(\beta\rhat(Y,x))]\leq \mathbb{E}[\exp(2\beta \rhat(Y,x))]$, the $\coverconstrhat(x)$. We also have the uniform bound, $\coverconstrhat(x)=\frac{\mathbb{E}[\exp(2\beta\rhat(Y,x))]}{\mathbb{E}^2[\exp(\beta \rhat(Y,x))}\leq \exp(\beta R_{\max})$. Furthermore, due to increasing property in \eqref{item2}, we also have $\sup_{\beta}\coverconstrhat(x)=\coverinfr(x)$. Therefore, the upper bound holds.
    \end{enumerate}
\end{proof}


\begin{tcolorbox}
        \begin{theorem}\label{thm:sub-gap}
  Under Assumption~\ref{ass:bounded_reward}, the following upper bound holds on the sub-optimality gap of the SBoN,
   \begin{equation*}
       \begin{split}  \DeltaJ(\pibetarstar\big(\cdot|x\big), \pisbon(\cdot|x))&\leq \frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad + \sqrt{\varepsilon_{\beta,r}(x)}\big(\sqrt{\coverconstrhat(x)}+\sqrt{\coverconstrstar(x)} \big)\\
      &\quad+2R_{\max} \sqrt{\frac{1}{2}\log\Big(1+\frac{\coverconstrhat(x)-1}{N}\Big)}.
       \end{split}
   \end{equation*}
\end{theorem}
\end{tcolorbox}
\begin{proof}
    Note that, we have,
    \begin{equation}\label{eq:gap3n}
    \begin{split}
                &\DeltaJ(\pibetarstar\big(\cdot|x\big), \pisbon(\cdot|x))\\
&=\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]\\
&=\underbrace{\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rstar(Y,x)]}_{I_1}\\
&\quad+\underbrace{\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]}_{I_2}
    \end{split}
    \end{equation}
     Note that, using the definition of $\pibetarstar\big(\cdot|x\big)$ and $\pibetarhat\big(\cdot|x\big)$ as solutions to KL-regularized problem, we have,
    \begin{equation}
        \mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]=\frac{1}{\beta}\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))+\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rstar(Y,x))]).
    \end{equation}
    \begin{equation}
        \mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rhat(Y,x)]=\frac{1}{\beta}\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))+\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rhat(Y,x))]).
    \end{equation}
   Therefore, for term $I_1$, we have,
    \begin{equation}\label{eq:gap1n}
        \begin{split}
            &\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rstar(Y,x)]\\
            &=\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rhat(Y,x)]\\
            &\quad+\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rhat(Y,x)]-\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rstar(Y,x)]\\
            &=\frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad +\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rstar(Y,x))])-\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rhat(Y,x))])\\
            &\quad+ \sum_{\mathcal{Y}} \pibetarhat\big(\cdot|x\big) (\rhat(y,x)-\rstar(y,x))\\
            &\leq\frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad +\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rstar(Y,x))])-\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rhat(Y,x))])\\
            &\quad+ \frac{1}{\sqrt{\beta}}\sqrt{\sum_{\mathcal{Y}} \frac{\pibetarhat^2(y|x)}{\pirefer(y|x)}} \sqrt{\beta\sum_{\mathcal{Y}}(\rhat(y,x)-\rstar(y,x))^2\pirefer(y|x)}\\
             &\leq\frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad +\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rstar(Y,x))])-\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rhat(Y,x))])\\
            &\quad+ \sqrt{\coverconstrhat(x) \varepsilon_{\beta,r}(x)}\\
              &\leq\frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad +\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rstar(Y,x))])-\frac{1}{\beta}\log(\mathbb{E}_{Y\sim\pirefer(\cdot|x)}[\exp(\beta \rhat(Y,x))])\\
            &\quad+ \sqrt{\coverconstrhat(x) \varepsilon_{\beta,r}(x)}
            \\
              &\leq\frac{1}{\beta}\Big(\KLr(\pibetarstar(\cdot|x)\|\pirefer(\cdot|x))-\KLr(\pibetarhat(\cdot|x)\|\pirefer(\cdot|x))\Big)\\
            &\quad +  \sqrt{\coverconstrstar(x) \varepsilon_{\beta,r}(x)}\\
            &\quad+  \sqrt{\coverconstrhat(x) \varepsilon_{\beta,r}(x)}.
        \end{split}
    \end{equation}

    % where,
    % \begin{equation}
    %     TV_{\infty} = \mathbb{TV}(\pi_{\infty,\rstar},\pi_{\infty,\rhat}).
    % \end{equation}
    For term $I_2$ and using similar approach to term $I_1$ and applying Lemma~\ref{lem:flavio}, we have,
    \begin{equation}\label{eq:gap2n}
        \begin{split}
            &\mathbb{E}_{Y\sim\pibetarhat\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]\\
            &\leq 2R_{\max}\mathbb{TV}(\pibetarhat\big(\cdot|x\big),\pisbon(\cdot|x))\\
            &\leq 2R_{\max} \min\Big(1,\sqrt{\frac{1}{2}\KLr(\pibetarhat\big(\cdot|x\big)\|\pisbon(\cdot|x))}\Big)\\
            &\leq  2R_{\max} \min\Big(1,\sqrt{\frac{1}{2}\log\Big(1+\frac{\coverconstrhat(x)-1}{N}\Big)}\Big)\\
            &\leq 2R_{\max} \sqrt{\frac{1}{2}\log\Big(1+\frac{\coverconstrhat(x)-1}{N}\Big)}
        \end{split}
    \end{equation}
    Combining \eqref{eq:gap1n} and \eqref{eq:gap2n} with \eqref{eq:gap3n} completes the proof.
\end{proof}


\begin{tcolorbox}
    \begin{reptheorem}{thm:gap_bon}
  Under Assumptions~\ref{ass:bounded_reward}, \ref{ass:bounded_est_reward}, and \ref{ass:achieve_reward}, the following upper bound holds on the optimal regret gap of the SBoN policy for any $\beta > 0$,
  \begin{equation*}
       \begin{split}  \DeltaJ(\pi^{\star}_{\rstar}\big(\cdot|x\big), \pisbon(\cdot|x))&\leq 
     \sqrt{\varepsilon_{\beta,r}(x)}\big(\sqrt{\coverinfrhat(x)}+\sqrt{\coverinfrstar(x)} \big)\\
      &\quad+2R_{\max} \sqrt{\frac{1}{2}\log\Big(1+\frac{\coverinfrhat(x)-1}{N}\Big)}\\
      &\quad+ \frac{\log(\coverinfrstar(x))}{\beta},
       \end{split}
   \end{equation*}
\end{reptheorem}
\end{tcolorbox} 

\begin{proof}
     Note that we have,
    \begin{equation}
    \begin{split}
                &\DeltaJ(\pi^{\star}_{\rstar}\big(\cdot|x\big), \pisbon(\cdot|x))\\
&=\mathbb{E}_{Y\sim\pi^{\star}_{\rstar}\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim \pisbon(\cdot|x)}[\rstar(Y,x)]\\
&=\underbrace{\mathbb{E}_{Y\sim\pi^{\star}_{\rstar}\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]}_{I_3}\\
&\quad+\underbrace{\DeltaJ(\pibetarstar\big(\cdot|x\big), \pisbon(\cdot|x))}_{I_4}
    \end{split}
    \end{equation}
    For term $I_4$, we can use Theorem~\ref{thm:sub-gap}. For term $I_3$, note that, we have for $\beta>0$,
\begin{equation}\label{eq:gap1}
    \begin{split}
        \mathbb{E}_{Y\sim\pi^{\star}_{\rstar}\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]&\leq \frac{\KLr(\pi^{\star}_{\rstar}\big(\cdot|x\big)\|\pirefer(\cdot|x))-\KLr(\pibetarstar\big(\cdot|x\big)\|\pirefer(\cdot|x))}{\beta}
    \end{split}
\end{equation}
Combining \eqref{eq:gap1} with Theorem~\ref{thm:sub-gap}, completes the proof due the positiveness of KL divergence and using Lemma~\ref{lem:KL_C} and Lemma~\ref{lem:coverage_prop}.

\end{proof}
\begin{remark}
    For $\beta=0$, we have, $\lim_{\beta\rightarrow 0}\pibetarstar\big(\cdot|x\big) = \pirefer(\cdot|x)$. Therefore, we have,
% \begin{equation}
    \begin{equation}
    \begin{split}
        &\mathbb{E}_{Y\sim\pi^{\star}_{\rstar}\big(\cdot|x\big)}[\rstar(Y,x)]-\mathbb{E}_{Y\sim\pibetarstar\big(\cdot|x\big)}[\rstar(Y,x)]\leq R_{\max}\sqrt{2\KLr(\pi^{\star}_{\rstar}\big(\cdot|x\big)\|\pirefer(\cdot|x))}.
    \end{split}
\end{equation}
\end{remark}

