\title{Modeling and Inferring Metacommunity Dynamics with Maximum Caliber}

\author{Zachary Jackson\textsuperscript{*1}, Mathew A. Leibold\textsuperscript{2}, Robert D. Holt\textsuperscript{2}, BingKan Xue\textsuperscript{1}}
\date{\textsuperscript{1} Department of Physics, \textsuperscript{2} Department of Biology,\\
University of Florida, Gainesville, FL, United States}


