\section*{Supplementary Material}

\subsection*{Detailed derivation of the Maximum Caliber model}

For simplicity and clarity, we will derive the Maximum Caliber solution for a single species, which means dropping the subscript $i$. We start from the loss function:
\begin{align}
L=&-\sum_{\{x^{(t)}\}}P(\{x^{(t)}\}) \log P({\{x^{(t)}\}}) + \eta\left(\sum_{\{x^{(t)}\}}P(\{x^{(t)}\})\frac{1}{T}\sum_{t=1}^{T-1}x^{(t+1)}x^{(t)}-c\right)\nonumber\\
&+\lambda \left(\sum_{\{x^{(t)}\}}P(\{x^{(t)}\}) \frac{1}{T}\sum_{t=1}^{T-1}x^{(t)}-f\right)
+ \mu \left(\sum_{\{x^{(t)}\}}P(\{x^{(t)}\})-1\right)
\end{align}
maximizing with respect to $P(\{x^{(t)}\})$ gives
\begin{align}
\frac{\partial L}{\partial P(\{x^{(t)}\})}= -\log P(\{x^{(t)}\})-1 + \frac{\eta}{T} \sum_{t=1}^{T-1}x^{(t+1)}x^{(t)} + \frac{\lambda}{T}\sum_{t=1}^{T-1}x^{(t)} + \mu = 0
\end{align}
if we renormalize our parameters with $\eta \leftarrow \eta/T$, $\lambda \leftarrow \lambda/T$, and $Z \leftarrow e^{1-\mu}$ and solve for $P(\{x^{(t)}\})$,
\begin{align}
P(\{x^{(t)}\})= \frac{1}{Z} \exp\left(\eta\sum_{t=1}^{T-1}x^{(t+1)}x^{(t)} + \lambda\sum_{t=1}^{T-1}x^{(t)}\right) = \frac{1}{Z} \prod_{t=1}^{T-1}\exp \left(\eta x^{(t+1)}x^{(t)} + \lambda x^{(t)}\right)
\end{align}
To see why this is a Markovian process, we will calculate the conditional probability starting from the end of the time series and working backwards. The joint probability of the full trajectory from $t=1$ to $T$ is given by a product of terms for each time step:
\begin{align}
P\left(x^{(1)} \cdots x^{(T)}\right)=\frac{1}{Z}\exp\left(\eta x^{T}x^{T-1}+\lambda x^{T-1}\right)\exp\left(\eta x^{T-1}x^{T-2}+\lambda x^{T-2}\right)\cdots\exp\left(\eta x^1x^0+\lambda x^0\right)
\end{align}
We then calculate the joint probability of a partial trajectory from $t=1$ to $T-1$ by summing over the possible states of $x^{(T)}$
\begin{align}
P\left(x^{(1)} \cdots x^{(T-1)}\right)&=\sum_{x^{(T)}=0}^1 P\left(x^{(1)} \cdots x^{(T)}\right)\nonumber\\ &= \frac{1}{Z}\left(1+\exp\left(\eta x^{T-1}\right)\right) \exp\left(\lambda x^{T-1}\right)\exp\left(\eta x^{T-1}x^{T-2}+\lambda x^{T-2}\right)\cdots
\end{align}
We can use these to calculate the conditional probability of $x^{(T)}$ given the trajectory up to $T-1$.
\begin{align}
P\left(x^{(T)}|x^{(1)} \cdots x^{(T-1)}\right) = \frac{P\left(x^{(1)} \cdots x^{(T)}\right)}{P\left(x^{(1)} \cdots x^{(T-1)}\right)} =\frac{\exp(\eta x^{(T)}x^{(T-1)})}{1+\exp(\eta x^{(T-1)})}
\end{align}
From this expression we see that the conditional probability depends only on $x^{(T-1)}$, which means this step is Markovian. We can rewrite this conditional probability as $P\left(x^{(T)}|x^{(T-1)}\right)$ and, for $x^{(T)}=1$,:
\begin{equation}
P\left(x^{(T)} \!=\! 1|x^{(T-1)}\right) = \frac{\exp(\eta x^{(T-1)})}{1+\exp(\eta x^{(T-1)})} = \frac{1}{1+\exp(-\eta x^{(T-1)})}
\end{equation}
Through a similar process, we can calculate the joint probability of the trajectory from $t=1$ to $T-2$:
\begin{equation}
P\left(x^{(T)}|x^{(1)} \cdots x^{(T-1)}\right) = ...
\end{equation}
Then we calculate the conditional probability of $x^{(T-1)}$ given the trajectory up to $t=T-2$:
\begin{align}
P\left(x^{(T-1)}|x^{(1)} \cdots x^{(T-2)}\right) &= \frac{P\left(x^{(1)} \cdots x^{(T-1)}\right)}{P\left(x^{(1)} \cdots x^{(T-2)}\right)}\nonumber\\ &=\frac{\left(1+\exp(\eta x^{(T-1)})\right)\exp(\lambda x^{(T-1)} +\eta x^{(T-1)}x^{(T-2)})}{2+(1+\exp(\eta))\exp(\lambda+\eta x^{(T-2)})}
\end{align}
Again we see that this conditional probability depends only on $x^{(T-2)}$, which means it is Markovian. This conditional probability can be simplified as
\begin{align}
P\left(x^{(T-1)} \!=\! 1|x^{(1)} \cdots x^{(T-2)}\right)= \frac{1}{1+\exp(-\eta x^{(T-2)}-\lambda')}
\end{align}
where $\lambda'= \lambda+\log(1+\exp(\eta)/2)$. By continuing this recursion we obtain
\begin{align}
P\left(x^{(T-2)}=1|x^{(T-3)}\right)= \frac{1}{1+\exp(-\eta x^{T-3}-\lambda'')}
\end{align}
with $\lambda''=\lambda+\log\left(\frac{1+\exp(\eta+\lambda')}{1+\exp(\lambda')}\right)$. As we move further away from the end of the time series, the effective parameter value of $\lambda$ quickly approaches a constant. To find this limiting value, $\tilde{\lambda}$, we can set $\lambda'=\lambda''$ in the recursive relation:
\begin{align}
\exp(\tilde{\lambda})=\exp(\lambda)\frac{1+\exp(\eta+\tilde{\lambda})}{1+\exp(\tilde{\lambda})}
\end{align}
Solving this for $\tilde{\lambda}$ gives
\begin{align}
\exp\left(\tilde{\lambda}\right)=\frac{1}{2}\exp(\eta+\lambda)-1+\sqrt{(1-\exp(\eta+\lambda))^2+4exp(\lambda)}\label{eq:lambdatil}
\end{align}
Therefore, for large $T$, the conditional probability at each time step can be taken as:
\begin{align}
P\left(x^{(t+1)}=1|x^{(t)}\right)= \frac{1}{1+\exp(-\eta x^{(t)}-\tilde{\lambda})}
\end{align}

Note that when calculating the average occupancy of a species $f_i$ to use in the Maximum Caliber calculation, there is a choice of whether to sum from $x^{(1)}$ to $x^{(T-1)}$, or from $x^{(2)}$ to $x^{(T)}$. More generally, we can use
\begin{align}
f_i=\frac{1}{T}\sum_{t=1}^{T-1} \alpha x_i^{(t)} + (1-\alpha) x_i^{(t+1)}
\end{align}
for any value of $\alpha$ between $0\leq\alpha\leq1$. Our choice above corresponds to $\alpha = 1$. Following a similar scheme for $\alpha=0$, we find that $\lambda$ converges to the same value. As such, for long time series (large $T$), the resulting model will be the same regardless of the value of $\alpha$ used.


\subsection*{Maximum Caliber versus Logistic Regression}

Here we give a comparison between the parameter inference in Maximum Caliber and in logistic regression. In Maximum Caliber, strictly speaking, we need to find parameter values by solving the constraint equations:
\begin{align}
f_{i}^\textrm{obs}&= \sum_{\{x_i^{(t)}\}} P(\{x_i^{(t)}\})\frac{1}{T} \sum_t x_i^{(t+1)}\\
&=\frac{1}{T} \sum_t \sum_{x_i^{(t+1)}} P(x_i^{(t+1)})x_i^{(t+1)}\\
&=\frac{1}{T} \sum_t \sum_{x_i^{(t+1)}} \sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)}|\mathbf{x}^{(t)}) P(\mathbf{x}^{(t)}) x_i^{(t+1)}
\end{align}
If we assume that the process is stationary, then each $t$ term would give the same result, which means:
\begin{align}
f_{i}^\textrm{obs}&= \sum_{x_i^{(t+1)}} \sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)}|\mathbf{x}^{(t)}) P(\mathbf{x}^{(t)})  x_i^{(t+1)}\\
&=\sum_{\mathbf{x}^{(t)}} P(\mathbf{x}^{(t)}) P(x_i^{(t+1)}\!=\!1|\mathbf{x}^{(t)})\label{eq:f_maxcal}
\end{align}
Similarly for $c_{ij}$:
\begin{align}
c_{ij}^\textrm{obs}&= \sum_{\{x_i^{(t)}\}} P(\{x_i^{(t)}\})\frac{1}{T} \sum_t x_i^{(t+1)}x_j^{(t)}\\
&=\frac{1}{T} \sum_t \sum_{x_i^{(t+1)}} \sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)},x_j^{(t)}) x_i^{(t+1)} x_j^{(t)}\\
&=\frac{1}{T} \sum_t \sum_{x_i^{(t+1)}} \sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)}|\mathbf{x}^{(t)}) P(\mathbf{x}^{(t)}) x_i^{(t+1)}x_j^{(t)}\\
&= \sum_{x_i^{(t+1)}} \sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)}|\mathbf{x}^{(t)}) P(\mathbf{x}^{(t)}) x_i^{(t+1)}x_j^{(t)}\\
&=\sum_{\mathbf{x}^{(t)}} P(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}) P(\mathbf{x}^{(t)})x_j^{(t)}\\
&=\sum_{\mathbf{x}^{(t)}} P(\mathbf{x}^{(t)}) P(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}) x_j^{(t)}\label{eq:c_maxcal}
\end{align}

In logistic regression, we minimize the cross entropy between the predicted probabilities $P_t$ and the realized probabilities $y_t$.
\begin{align}
L=-\sum_t y_t \log P_t +(1-y_t)\log(1-P_t)
\end{align}
where $y_t$ is the presence or absence of a species in a patch at the next time step $x_i^{(t+1)}$, and $P_t$ is the probability of that species being present in that patch given the configuration of the system at the previous time step. 
\begin{align}
P_t&=\prod_iP(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)})=\prod_i\frac{1}{1+e^{-\sum_j\eta_{ij}x_j^{(t)}-\lambda_i}}
\end{align}
With this expression, the log loss becomes:
\begin{align}
L=-\sum_t\sum_i\left(x_i^{(t+1)}\log P(x_i^{(t+1)}|\mathbf{x}^{(t)})+(1-x_i^{(t+1)})\log (1-P(x_i^{(t+1)}|\mathbf{x}^{(t)}))\right)
\end{align}
Differentiating the loss with respect to $\lambda_i$ gives
\begin{align}
\frac{\partial L}{\partial \lambda_i} &= \sum_tx_i^{(t+1)}\left(1-P\left(x_i^{(t+1)}|\mathbf{x}^{(t)}\right)\right)-\left(1-x_i^{(t+1)}P\left(x_i^{(t+1)}|\mathbf{x}^{(t)}\right)\right)\\
&=-\sum_t x_t^{(t+1)}-P\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)\\
&=-T\left(f_i^\textrm{obs}-\frac{1}{T} \sum_t P\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)\right)
\end{align}
Differentiating with respect to $\eta_{ij}$ gives
\begin{align}
\frac{\partial L}{\partial \eta_{ij}}&=-\sum_t x_i^{(t+1)}x_j^{(t)}(1-P\left(x_i^{(t+1)}|\mathbf{x}^{(t)}\right))-\left(1-x_i^{(t+1)}\right)x_j^{(t)}P\left(x_i^{(t+1)}|\mathbf{x}^{(t)}\right)\\
&=-\sum_t \left(x_i^{(t+1)}-P\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)\right)x_j^{(t)}\\
&=-T\left(c_{ij}^\textrm{obs}-\frac{1}{T}\sum_tP\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)x_j^{(t)}\right)
\end{align}
After maximizing the log likelihood, we should get 
\begin{align}
f_i^\textrm{obs} &= \frac{1}{T} \sum_t P\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)\label{eq:f_log}\\
c_{ij}^\textrm{obs} &= \frac{1}{T}\sum_tP\left(x_i^{(t+1)}\!\!=\!\!1|\mathbf{x}^{(t)}\right)x_j^{(t)}\label{eq:c_log}
\end{align}
Note that in these equations the $x_i^{(t)}$'s are the observed values of species presence or absence, rather than dummy indices that are summed over in Eqs.~(\ref{eq:f_maxcal}) \& (\ref{eq:c_maxcal}).

If we compare Eqs.~(\ref{eq:f_log}) \& (\ref{eq:c_log}) to Eqs.~(\ref{eq:f_maxcal}) \& (\ref{eq:c_maxcal}), the difference between the logistic regression calculation and the strict Maximum Caliber calculation is that logistic regression takes an average over time of observed data, whereas Maximum Caliber takes an average over the probability of system trajectories. When the time series are sufficiently long, the two calculations will give equal results.




