\begin{theorem}[{\cite[Corollary 5.1]{RodriguezVillalobosSchwedeBrianconSkoda}}, see also {\cite[Theorem 2.13]{HeitmannPlusClosureMixedChar}}]
\label{theorem: BrianconSkoda}
Let $I\subseteq R^+$ be an ideal generated by $h$ elements such that $p\in \sqrt{I}$. Then $\overline{I^{k+h-1}}\subseteq I^{k}$ for every $k\geq 0$. In particular, if $I$ is generated by two elements and $p\in\sqrt{I}$, then $\overline{I^{k}}\subseteq I^{k-1}$ for every $k>0$. 
\end{theorem}


