%\end{remark}

Lastly, we construct elements $g\in\widehat{R^+}$ such that $\widehat{R^+}/g$ is not $p$-adically separated whenever $\dim(R)\geq 2$. 

\begin{proposition}
\label{proposition: construction of bad g}
Suppose $\dim(R)\geq 2$ and let $v$ be any $\mathbb{R}$-valuation on $\widehat{R^+}$ whose center on $R^+$ contains $p$ and is not $\m_{R^+}$, normalized so that $v(p)=1$.
Then there exists $0\neq g\in \widehat{R^+}$ such that $v(g)=\infty$ (i.e., $g$ is in the support of $v$).
More precisely, if $x\in\m_{R^+}$ is such that $p,x$ is a regular sequence on $R^+$ and $x$ is not in the center of $v$, then $g$ can be taken as the limit of a sequence $\{g_i\}_{i=1}^\infty$ in $R^+$ so that 
\begin{enumerate}
  %\item $v(g_i)=i+1$
  \item $g_1$ satisfies the equation $T^2+xT+p^2=0$.
  \item $g_i={p^{i+1}}/{s_i}$ for some $s_i\in R^+$ with $v(s_i)=0$ for every $i\geq 1$.
  %SSP
  %
  \item $g_{i+1}=g_i+p^ih_i$ where $h_i$ is a root of the equation $T^2+s_iT+p=0$ for every $i\geq 1$.

\end{enumerate}
In particular, there exists $g\in\widehat{R^+}$ such that $\widehat{R^+}/g$ is not $p$-adically separated.
\end{proposition}

\begin{proof}


For $i=1$, we note that the equation $T^2+xT+p^2=0$ has two roots $u_1,u_2\in R^+$.
Since $v(u_1u_2)=2$ while $v(u_1+u_2)=v(-x)=0$, we may without loss of generality assume $v(u_1)=2$ and $v(u_2)=0$.
%SSP
%
We set $g_1=u_1$ and $s_1=u_2$; so (2) is satisfied for $i=1$.
%As $v(g_1)=2$, (1) is satisfied for $i=1$.
%Further, $g_1=\frac {p^2}{-g_1-x}$, satisfying (2).
%Hence $g_1$ can be chosen to satisfy all conditions.

Assume we have chosen $g_i$ and $s_i$.
We now show we may choose $g_{i+1}$ to satisfy (2) and (3).
By the condition (3), $h_i$ must be one of the two roots of $T^2+s_iT+p=0$, so all we need to show is that one of the two choices will produce a $g_{i+1}$ that satisfies (2).
Now $$g_{i+1}=g_i+p^ih_i=\frac {p^{i+1}}{s_i}+p^{i}h_i=p^i(\frac{p+s_ih_i}{s_i}).$$
Since $h_i$ is one of the two roots of $T^2+s_iT+p=0$, $s_ih_i$ is one of the two roots of $T^2+s_i^2T+ps_i^2=0$ and so $p+s_ih_i$ is one of the two roots of
\begin{align*}
  0 & =  (T-p)^2+s_i^2(T-p)+ps_i^2\\
   & =T^2+(-2p+s_i^2)T+(p^2-ps_i^2+ps_i^2) \\
   & =T^2+(-2p+s_i^2)T+p^2
\end{align*}
We know that one root of the equation above has value $2$ and the other has value $0$ (since $v(s_i)=0$). It follows that we can choose $h_i$ so that $v(p+s_ih_i)=2$
and with this choice, $$p+s_ih_i=\frac{p^2}{-(-2p+s_i^2)-(p+s_ih_i)}$$
%SSP
%
and the denominator above (which is the other root) has value $0$. Setting $s_{i+1}$ to be $s_i$ times the denominator above, we have $v(s_{i+1})=0$ and $g_{i+1}={p^{i+2}}/{s_{i+1}}$ as wanted.

We have constructed the desired sequence $\{g_i\}_{i=1}^\infty$ in $R^+$. By (3), the limit $g=\lim_ig_i$ is well-defined as an element in $\widehat{R^+}$. By (2), we know that 
$v(g_i)=i+1$ and so $v(g)=\infty$. By (1), we have $g_1\notin pR^+$: If $g_1=py$, then we have $p^2y^2+pxy+p^2=0$ and thus $xy\in pR^+$, so $y\in pR^+$ as $p, x$ is a regular sequence in $R^+$. But then $g_1=p^2z$ and thus $p^4z^2+p^2xz+p^2=0$, so $p^2z^2+xz+1=0$ a contradiction. Therefore, $g\notin p\widehat{R^+}$ and in particular, $g\neq 0$.
 The last conclusion follows by taking $v=v_Q$ and applying Theorem~\ref{theorem: completeIntegrallyClosed}. 
\end{proof}

%Specifically, one can take a height one prime $Q$ in $R^+$ and consider the valuation ring $V^+:=R^+_Q$, and let $v_Q$ be the valuation on $\widehat{R^+}$ induced by the canonical map $\widehat{R^+}\to \widehat{V^+}$. The conclusion of the proposition then says that $g$ is in the kernel of the canonical map $\widehat{R^+}\to \widehat{V^+}$. By Theorem~\ref{theorem: completeIntegrallyClosed}, $\widehat{R^+}/g$ is not $p$-adically separated.

\begin{remark}
In fact, when $\dim(R)\geq 2$, we can show that the zero ideal in $\widehat{R^+}$ in not the support of any rank one valuation $v$ whose center contains $p$. By Proposition~\ref{proposition: construction of bad g}, it is enough to handle the case that $v$ is centered on $\m_{R^+}$. We may normalize $v$ so that $v(p)=1$ and choose $x\in R^+$ so that $p,x$ is a regular sequence on $R^+$, without loss of generality, we may also assume that $v(x)>1$. Then by applying Lemma~\ref{lemma: constructing h} below repeatedly and taking limit, we obtain an element $g\in \widehat{R^+}$ so that $g\equiv x$ mod $p$ (in particular, $g\neq 0$) and $v(g)=\infty$.  This fact shows that, in the language of \cite[Remark 2.14, Definitions 2.16 and 2.18]{DineTopologicalSpectrum}, that the zero ideal is a spectrally reduced prime ideal of the Tate algebra $S:=\widehat{R^+}[1/p]$ (i.e., $(0)\in \Spec_{\text{Top}}(S)$) that is not the support of any valuation in the Berkovich space $\mathcal{M}(S)$. 
\end{remark}

\begin{lemma}
\label{lemma: constructing h}
Suppose $v$ is any $\mathbb{R}$-valuation on $\widehat{R^+}$ centered on the maximal ideal, normalized so that $v(p)=1$. If $x\in \m_{R^+}$ is such that $v(x)=\lambda>i\geq 1$. Then there exists $h\in R^+$ so that $v(x+p^ih)>i+1$.  
\end{lemma}
\begin{proof}
Consider the monic polynomial $T^N + p^iT^2 +xT +x^N.$
If $h\in R^+$ is a root of this polynomial, then $x+p^ih$ is a root of the polynomial 
$$f(T):=(T-x)^N + p^{(N-1)i}(T-x)^2 + p^{(N-1)i}x(T-x) +p^{Ni}x^N.$$
Writing $f(T)=T^N + b_{N-1}T^{N-1}+ \cdots + b_1T + b_0$, it is straightforward to check that 
$$b_1 = N(-x)^{N-1} -p^{(N-1)i}x \,\ \text{ and } \,\  b_0= (-x)^N+ p^{Ni}x^N.$$
It follows that $v(b_0)= N\lambda$ and $v(b_1)=(N-1)i+\lambda$ for $N\gg0$. Thus for $N\gg0$,
$$v(b_1/b_0)=(N-1)(i-\lambda)< -i-1.$$
Thus there exists an $h$ so that $v(1/(x+p^ih))< -i-1$, that is, $v(x+p^ih)> i+1$. 
\end{proof}

Finally, we can prove Theorem A from the introduction.

\begin{theorem}
\label{theorem: completeIntegrallyClosedShortVersion}
Let $(R,\m)$ be a Noetherian complete local domain of mixed characteristic $(0,p)$ with fraction field $K$ and its algebraic closure $\overline{K}$. Then $\widehat{R^+}$ is completely integrally closed in $\widehat{R^+}\otimes_{R^+}\overline{K}$, while $\widehat{R^+}$ is completely integrally closed in its own fraction field if and only if $\dim(R)=1$. 
\end{theorem}
\begin{proof}
If $\dim(R)=1$, then $\widehat{R^+}$ is a valuation ring of rank one. In particular $\widehat{R^+}$ is completely integrally closed in its fraction field. Suppose $\dim(R)\geq 2$. If $g\in R^+$, then condition $(2)$ in Theorem~\ref{theorem: completeIntegrallyClosed} is obvious and the theorem follows from Theorem~\ref{theorem: completeIntegrallyClosed} and Proposition~\ref{proposition: construction of bad g}.
\end{proof}


