\section{The intrinsic shapes of \texorpdfstring{$^{96}$Ru and $^{96}$Zr}{96Ru and 96Zr}}
\label{sec:3}

\subsection{Knowledge from low-energy experiments}
\label{sec:Wimmer}
\newcommand{\nuc}[2]{$^{#1}$#2}
\newcommand{\betwo}{$B(E2)$\xspace}
\newcommand{\bev}{$B(E2)$ value\xspace}
\newcommand{\bevs}{$B(E2)$ values\xspace}
\newcommand{\bevup}{$B(E2;\;0^+ \rightarrow 2^+)$ value\xspace}
\newcommand{\bevups}{$B(E2;\;0^+ \rightarrow 2^+)$ values\xspace}
\newcommand{\bevoup}{$B(E2;\;0_1^+ \rightarrow 2_1^+)$ value\xspace}
\newcommand{\bevoups}{$B(E2;\;0_1^+ \rightarrow 2_1^+)$ values\xspace}
