     \hspace{-0.5cm} W_4(p_i) \hspace{-2mm} &\hspace{-2mm} =\hspace{-2mm} & \hspace{-2mm} \left(\dbar(1+\varepsilon) - \alpha p_i(1-\varepsilon) \right)^+\left(p_i- \Cmq \right) - O_\sM . \nonumber 
     \\ \label{eqn_W_4}
