\section*{ Appendix A}


\subsection{Equilibrium Cycle}
\label{sec_eql_cycle}
Any set $\E_1 \times \E_2$ is an equilbrium cycle for two player games if it satisfies the following properties (\cite{Walunj}):\\
  {\bf Property 1 (Stability):} For any player $i$ and interior strategy profile of the opponent's action $a_{-i} \in \E_{-i}$, there exists an interior action $a_i \in \E_i$ such that 
      \begin{eqnarray}\label{eq_prop_1}
      U_{i}(a_i,a_{-i}) > U_{i}(\tilde a_{i},a_{-i})     
      \end{eqnarray}
       for all exterior actions $\tilde a_{i} \in A_i \notin \E_i$.\\
  {\bf Property 2 (Unrest):} For any interior strategy profile $a \in \E$, there exists a player $i \in N$, and an alternate interior action $a_{i}^{'} \in \E_i$ such that 
       \begin{eqnarray}\label{eq_prop_2}
       U_{i}(a_{i}^{'},a_{-i}) > U_{i}(a_{i},a_{-i})
       \end{eqnarray}
       and further
       \begin{eqnarray}\label{eq_prop_2_dash}
         U_{i}(a_{i}^{'},a_{-i}) > U_{i}(\tilde{a_{i}},a_{-i})  
       \end{eqnarray}
       for all exterior actions $\tilde a_{i} \in A_i \notin \E_i$.\\
{\bf Property 3 (Minimality):}   No closed of $\E_1^{o} \times \E_{2}^{o} \subsetneq \E_1 \times \E_2 $ satisfies the above two conditions .

\begin{defn}\label{dominant_EC}
 An equilibrium cycle $\E$ is said to be dominant, if for any $a_i \notin \E_i$, and for any $a_{-i} \in A_{-i}$, there exists $a_{i}^{'} \in \E_i$ such that
\begin{eqnarray}\label{eq_dominant_ec}
 U_i(a^{'}_{i},a_{-i}) > U_i(a_i,a_{-i}) \mbox{ and  }  U_i(a^{'}_{i},a_{-i}) \ge U_i(\tilde{a_{i}},a_{-i})   \forall \tilde{ a_i}\notin \E_i   
\end{eqnarray}
\end{defn}


\subsection{Proofs}
We begin with some important lemmas. 
In all these proofs, $i \in \{1,2\}$ represents one of the manufacturers and $j$ refers to its opponent;  so if $i = 1$ then $j = 2$ and vice-versa.




\begin{lem}\label{lem_best_response}
 Let $q \le \bqd $.  For any $p_j \le \pdl$,   the best response set of player $i$  has unique element, which equals $\pdu$. 
\end{lem}
\noindent{\bf Proof:}

Observe from  \eqref{Eqn_W1}, 
for any fixed $p'$, the function
   $p \mapsto W_1 (p', p)$ is   increasing       and $p \mapsto W_1 (p, p')$ is concave and is increasing for all $p \le \pup_d$.  Thus, 
for any  $p_i < p_j \le \pdwn_d$, the  utility of player $i$ against given $p_j$ can be bounded as below using  \eqref{eqn_util_cases} and definition of $\pdl$ \eqref{eqn_pdwn_d}:

\vspace{-3mm}
{\small
\begin{eqnarray*}
U_i (p_i, p_j) = W_1 (p_i,  p_j) \le  W_1 (p_i,  \pdwn_d) \hspace{30mm}\\
\stackrel{a}{<}     W_1 (\pdwn_d,  \pdwn_d)  = W_2^* = U_i (\pup_d, p_j),
\end{eqnarray*}}%
where inequality $a$ is because of $p_i < \pdwn_d$.  
From \eqref{Eqn_W1} we also have $p \mapsto W_1(p,p)$ is strictly increasing. Hence again from \eqref{eqn_util_cases}-\eqref{Eqn_W3}, for   $p_i = p_j \le \pdwn_d$,
$$
U_i (p_i, p_j) =  W_3 (p_j) <  W_1(p_j,p_j)) \le W_2^* = U_i (\pup_d, p_j).
$$
