\begin{proof}
 We know that $\nicefrac{d\pdu}{dq} = \nicefrac{1}{2}$. 
 Also we have the following:
 \begin{eqnarray*}
 \frac{d\pdl}{dq}\left( -\alpha_\sMi(1-2\varepsilon)(\pdl - q - C_\sMi) 
 +
 (\dbar_\sMi -\alpha_\sMi\pdl(1-2\varepsilon)\right) \\
 = \dbar_\sMi - \alpha_\sMi\pdl(1-2\varepsilon).
 \end{eqnarray*}
 Thus we get,
 \begin{eqnarray*}
  \frac{d\pdl}{dq}  = \frac{\dbar_\sMi - \alpha_\sMi\pdl(1-2\varepsilon)}{\dbar_\sMi - 2\alpha_\sMi \pdl(1-2\varepsilon) + \alpha_\sMi(1-2\varepsilon)(q+ C_\sMi)}  
 \end{eqnarray*}
 Our aim is to prove that $\nicefrac{d\pdu}{dq} - \nicefrac{d\pdl}{dq} < 0$ which implies that we need to prove that $\nicefrac{d\pdl}{dq} > \nicefrac{1}{2}$.
 Let $M = \dbar_\sMi - \alpha_\sMi\pdl(1-2\varepsilon) $.Thus we get that,
 \begin{eqnarray}\label{eqn_derivative}
  \frac{d\pdl}{dq} = \frac{M}{M - \alpha_\sMi(1-2\varepsilon)(\pdl - q - C_\sMi)}   
 \end{eqnarray}
 Now consider a case when $\pdl -(q + C_\sMi) > 0$.
 For $\nicefrac{d\pdu}{dq} - \nicefrac{d\pdl}{dq} < 0$  to hold, we need
 \begin{eqnarray}\label{eqn_M}
 -\alpha_\sMi(1-2\varepsilon)(\pdl - (q+C_\sMi)) < M.
 \end{eqnarray}
As if \eqref{eqn_M} holds true, we will have 
\begin{eqnarray*}
  \frac{d\pdl}{dq} = \frac{M}{M + x}   
\end{eqnarray*}
where $x \le M$ and we additionally need $M \ge 0$ for $ \nicefrac{d\pdl}{dq} > \nicefrac{1}{2}$ to hold true. Notice that, \eqref{eqn_M} can b rewritten as follows after substituting the value of $M$:
\begin{eqnarray}\label{eqn_M_dash}
\alpha_\sMi(1-2\varepsilon)(q+ C_\sMi) < \dbar_\sMi
\end{eqnarray}
Now consider $\pdl -(q + C_\sMi) > 0$. 
As $\varepsilon > \nicefrac{1}{2}$, $\alpha_\sMi(1-2\varepsilon)(q+ C_\sMi) < 0$, thus \eqref{eqn_M_dash} holds true and also $M \ge 0$ by definition of $M$ and as $\varepsilon > \nicefrac{1}{2} $.


\end{proof}

