In the Lemma below, we demonstrate that the notions introduced in Definition \ref{D1} and Definition \ref{FSC1} can be verified for Köthe spaces by considering only the basis of Köthe spaces.

\begin{lem}\label{L1} 
Let $K(a_{n,k})$ be a Köthe space, and let $T: K(a_{n,k}) \to K(a_{n,k})$ be a linear continuous operator.
\begin{itemize}
\item[i.] $T$ is topologizable if and only if  for every $p\in \mathbb{N}$ there exists $q\in \mathbb{N}$ such that for every $k\in \mathbb{N}$ there is $M_{k,p}>0$ satisfying 
$$\|T^{k}(e_{n})\|_{p}\leq M_{k,p}\|e_{n}\|_{q}$$ 
for every $n\in \mathbb{N}$.
\item[ii.] $T$ is m-topologizable if and only if for every $p\in \mathbb{N}$ there exist  $q\in \mathbb{N}$ and $C_{p}\geq 1$ such that 
$$\|T^{k}(e_{n})\|_{p}\leq C_{p}^{k}\|e_{n}\|_{q}$$
holds for every $k,n\in  \mathbb{N}$.
\item[iii.] $T$ is power bounded if and only if  for every $p\in \mathbb{N}$ there exists $q\in \mathbb{N}$ such that
$$\|T^{k}(e_{n})\|_{p}\leq \|e_{n}\|_{q}$$
holds for every $k,n\in  \mathbb{N}$.
\item[iv.] $T$ is Ces\'aro bounded if and only if  for every $p\in \mathbb{N}$ there exists $q\in \mathbb{N}$ such that 
$$\|T^{[k]}(e_{n})\|_{p}\leq \|e_{n}\|_{q}$$
holds for every $k,n\in  \mathbb{N}$. 
\item[v.]  $T$ is strongly tame if and only if for every $p\in \mathbb{N}$ there exists a constant $C_{p}>0$ satisfying
$$\hspace{1.55in}\|Te_{n}\|_{p}\leq C_{p} \|e_{n}\|_{p}\hspace{1.25in}$$
holds for every $n\in \mathbb{N}$.
\end{itemize}
\end{lem}
\begin{proof} The proof of (i) is given below. The remaining parts (ii), (iii), (iv), and (v) can be established in a similar manner. The sufficient part is clear. 
%Now we assume 
