\subsection{Products Within Convolution and Dual Convolution Operator Classes}
In this section, we establish that the product of convolution (respectively, dual convolution) operators is again a convolution (respectively, dual convolution) operator. This is due to the fact that the matrix representation of a convolution (respectively, dual convolution) operator is a lower (respectively, upper) triangular Toeplitz matrix. This result follows from the fundamental property that the product of two lower (respectively, upper) triangular matrices is again lower (respectively, upper) triangular, and the Toeplitz structure is preserved under such matrix multiplication.

We begin by considering the product of two convolution operators.

Let $\theta,\phi\in \Lambda_{r}(\alpha)$, $r\in \{1,\infty\}$. We note that for $r=\infty$, the sequence $\alpha$ is assumed to be stable in the context of the convolution operator $\widehat{T}_{\theta}$.
We aim to show that
\begin{equation}\label{LT1}
\widehat{T}_{\phi}\widehat{T}_{\theta}=\widehat{T}_{\phi * \theta}.
\end{equation}
where $\phi*\theta$ denotes the convolution of $\beta$ and $\theta$.  We want to note that $\phi*\theta\in \Lambda_{r}(\alpha)$, $r\in\{1,\infty\}$ by Corollary \ref{CC}. Proposition \ref{PC1} and Proposition \ref{PC2} implies that $\widehat{T}_{\phi*\theta}$ is well-defined and continuous. Since all operators $\widehat{T}_{\theta}$,$\widehat{T}_{\phi}$ and $\widehat{T}_{\phi*\theta}$ are continuous, it suffices to verify that equality (\ref{LT1}) holds for the elements of basis $(e_{n})_{n\in \mathbb{N}}$. Let $n\in \mathbb{N}$ and write $\displaystyle \widehat{T}_{\theta}(e_{n})=\sum^{\infty}_{j=1}y_{j}e_{j}$ where $y_{j}=0$ if $j<n$ and $y_{j}=\theta_{j-n}$ if $j\geq n$. Hence 
\begin{equation*}
\begin{split}
\widehat{T}_{\phi}\widehat{T}_{\theta}(e_{n})&= \sum^{\infty}_{j=n}y_{j}\widehat{T}_{\phi}(e_{j}) =y_{n}\widehat{T}_{\phi}(e_{n})+\cdots+y_{m+n}\widehat{T}_{\phi}(e_{n+m})+\cdots \\ 
&= y_{n}\sum^{\infty}_{j=n}\phi_{j-n}e_{j}  +\cdots + y_{m+n}\sum^{\infty}_{j=m+n} \phi_{j-(m+n)}e_{j} +\cdots \\
&= y_{n}\phi_{0} e_{n}+\cdots + (y_{n}\phi_{m}+y_{n+1}\phi_{m-1}+\cdots+y_{n+m}\phi_{0})e_{n+m}+\cdots\\
&=\sum^{\infty}_{j=n} \gamma_{j-n}e_{j}=\widehat{T}_{\gamma}(e_{n})
\end{split}
\end{equation*}
where $\displaystyle \gamma_{m}=\sum^{m}_{i=0}y_{n+i}\phi_{m-i}=\sum^{m}_{i=0}\theta_{i}\phi_{m-i}=(\phi*\theta)_{m}$ for all $m\in \mathbb{N}_{0}$. This in turn implies that   $\widehat{T}_{\phi}\widehat{T}_{\theta}=\widehat{T}_{\phi * \theta}.$

Since $\phi*\theta=\theta*\phi$, it follows that $\widehat{T}_{\phi}\widehat{T}_{\theta}=\widehat{T}_{\theta}\widehat{T}_{\phi}$, and consequently, $\widehat{T}_{\phi}$ and $\widehat{T}_{\theta}$ commute.
\begin{prop}\label{CF} Let $\phi,\theta\in \Lambda_{r}(\alpha)$, $r\in \{1,\infty\}$. The convolution operators $\widehat{T}_{\phi}$ and $\widehat{T}_{\theta}$ commute and
$$\widehat{T}_{\phi}\widehat{T}_{\theta}=\widehat{T}_{\theta}\widehat{T}_{\phi}=\widehat{T}_{\phi * \theta}.$$
\end{prop}

Next, we investigate the product of two dual convolution operators.
Let $\beta, \psi\in (\Lambda_{r}(\alpha))^{\prime}$, $r\in \{1,\infty\}$.  We note that power series spaces are nuclear, and when $r=1$, the sequence $\alpha$ is assumed to be stable for the operators $\widecheck{T}_{\beta}$. 
We aim to show that
$$\widecheck{T}_{\beta}\widecheck{T}_{\psi}=\widecheck{T}_{ \psi*\beta}.$$
where $\beta*\psi$ denotes the convolution of $\beta$ and $\psi$. But first, we need to show that $\beta*\psi\in (\Lambda_{r}(\alpha))^{\prime}$ for $\beta, \psi\in (\Lambda_{r}(\alpha))^{\prime}$, $r\in \{1,\infty\}$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{prop} Let $\Lambda_{\infty}(\alpha)$ be a nuclear power series space of infinite type. For all $\beta, \psi \in (\Lambda_{\infty}(\alpha))^{\prime}$, their convolution $\beta * \psi$ also belongs to $(\Lambda_{\infty}(\alpha))^{\prime}$.
\end{prop}
\begin{proof} In the proof Proposition of \ref{PC4}, we used the nuclearity of $\Lambda_{\infty}(\alpha)$,  to show that there exist $m_{1}\in \mathbb{N}$ and $D>0$ such that for all $p,n \in \mathbb{N}$
\begin{equation*}
\sum^{n}_{j=1} e^{p\alpha_{j}}\leq D e^{(p+m_{1})\alpha_{n}}.
\end{equation*} 
Let 
$\beta,\psi\in (\Lambda_{\infty}(\alpha))^{\prime}$. Then there exist $m_{2}, m_{3}\in \mathbb{N}$ and $C_{1}, C_{2}>0$ such that $|\beta_{n-1}|\leq C_{1}e^{m_{2}\alpha_{n}}$ and $|\psi_{n-1}|\leq C_{2}e^{m_{3}\alpha_{n}}$ for all $n\in \mathbb{N}$.  It follows that 
\begin{equation*}
\begin{split}
(\beta*\psi)_{n}&= \sum^{n}_{j=1} |\psi_{n-j}||\beta_{j-1}| \\
& \leq C_{1}C_{2}\sum^{n}_{j=1} e^{m_{2}\alpha_{n-j}}e^{m_{3}\alpha_{j-1}} \\ & \leq C_{1}C_{2}e^{m_{2}\alpha_{n}}\sum^{n}_{j=1} e^{m_{3}\alpha_{j}}\leq C_{1}C_{2}D e^{(m_{1}+m_{2}+m_{3})\alpha_{n}}
\end{split}
\end{equation*}
for all $n\in\mathbb{N}$. 
This implies that $\beta*\theta\in (\Lambda_{\infty}(\alpha))^{\prime}$.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{prop} Let $\alpha=(\alpha_{n})_{n\in \mathbb{N}}$ be a stable sequence, and assume that the space $\Lambda_{1}(\alpha)$ is nuclear. 
For all $\beta, \psi \in (\Lambda_{1}(\alpha))^{\prime}$, their convolution $\beta * \psi$ also belongs to $(\Lambda_{1}(\alpha))^{\prime}$.
\end{prop}
\begin{proof}  In the proof of Proposition \ref{PC3}, we used the nuclearity of $\Lambda_{1}(\alpha)$,  to show that for every $k\in \mathbb{N}$, there exists a $D>0$ satisfying  
$$n e^{-\frac{1}{k}\alpha_{n}}\leq De^{-\frac{1}{2k}\alpha_{n}}$$
for all $n\in \mathbb{N}$. 
Moreover, in the same proof, the stability of $\alpha$ imply the existence of a constant  $M\in \mathbb{N}$ such that
$$\alpha_{n}\leq M(\alpha_{n-j+1}+\alpha_{j})$$
for every $j\leq n$ and $n\in \mathbb{N}$ . 

Let $\beta,\theta\in (\Lambda_{1}(\alpha))^{\prime}$. Then there exist $m_{1}, m_{2}\in \mathbb{N}$ and $C_{1}, C_{2}>0$ such that $|\beta_{n-1}|\leq C_{1}e^{-\frac{1}{m_{1}}\alpha_{n}}$ and $|\psi_{n-1}|\leq C_{2}e^{-\frac{1}{m_{2}}\alpha_{n}}$ for all $n\in \mathbb{N}$.  
It follows that 
\begin{equation*}
\begin{split}
(\beta*\psi)_{n}&= \sum^{n}_{j=1} |\psi_{n-j}||\beta_{j-1}|  \leq C_{1}C_{2}\sum^{n}_{j=1}e^{-\frac{1}{m_{1}}\alpha_{n-j+1}}e^{-\frac{1}{m_{2}}\alpha_{j}} \\ & \leq C_{1}C_{2}\sum^{n}_{j=1} e^{-\frac{1}{\max\{m_{1},m_{2}\}}(\alpha_{n-j+1}+\alpha_{j})}\leq C_{1}C_{2} \sum^{n}_{j=1} e^{-\frac{1}{M\max\{m_{1},m_{2}\}}\alpha_{n}} \\
&= C_{1}C_{2} ne^{-\frac{1}{M\max\{m_{1},m_{2}\}}\alpha_{n}}\leq C_{1}C_{2}D e^{-\frac{1}{2M\max\{m_{1},m_{2}\}}\alpha_{n}}
\end{split}
\end{equation*}
for all $n\in\mathbb{N}$ which implies that $\beta*\psi\in (\Lambda_{1}(\alpha))^{\prime}$.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
To show that $\widecheck{T}_{\beta}\widecheck{T}_{\psi}=\widecheck{T}_{ \psi*\beta}$, it is enough to verify that $\widecheck{T}_{\beta}\widecheck{T}_{\psi}(e_{n})=\widecheck{T}_{\psi* \beta}(e_{n})$
for every $n\in \mathbb{N}$. Let $n\in \mathbb{N}$ and write  $\displaystyle \widecheck{T}_{\psi}(e_{n})=\sum^{n}_{j=1}y_{j}e_{j}$ where $y_{j}=\psi_{n-j}$ for all $1\leq j\leq n$. Then
\begin{equation*}
\begin{split}
\widecheck{T}_{\beta}\widecheck{T}_{\psi}(e_{n})&= \sum^{n}_{j=1}y_{j}\widecheck{T}_{\beta}(e_{j}) =y_{1}\beta_{0}e_{1}+ y_{2}(\beta_{1}e_{1}+\beta_{0}e_{2}) +\cdots y_{n}(\beta_{n-1}e_{1}+\cdots+\beta_{0}e_{n}) \\
&=(y_{1}\beta_{0}+y_{2}\beta_{1}+\cdots+y_{n}\beta_{n-1})e_{1}+(y_{2}\beta_{0}+y_{3}\beta_{1}+\cdots+y_{n}\beta_{n-2})e_{2}\\
&\hspace{0.15in}+\cdots +(y_{i}\beta_{0}+y_{i+1} \beta_{1}+\cdots+y_{n}\beta_{n-i})e_{i}+\cdots+y_{n}\beta_{0}e_{n}
\\
&=\bigg(\sum^{n-1}_{j=1}y_{j}\beta_{j-1}\bigg)e_{1}+\bigg(\sum^{n-2}_{j=1}y_{j+1}\beta_{j-1}\bigg)e_{2}\\
&\hspace{0.15in}+\cdots+\bigg(\sum^{n-i}_{j=1}y_{j+i}\beta_{j-1}\bigg)e_{i}+\cdots +y_{n}\beta_{0}e_{n}
\\
&=\sum^{n}_{i=1} \gamma_{n-i}e_{i}
\end{split}
\end{equation*}
where $\displaystyle \gamma_{m}=\sum^{m}_{j=1}y_{j+n-m}\beta_{j-1}=\sum^{m}_{j=1}\psi_{m-j}\beta_{j-1}=(\psi*\beta)_{m}$  for all $m\in \mathbb{N}$. It follows that $\widecheck{T}_{\beta}\widecheck{T}_{\psi}=\widecheck{T}_{\beta * \psi}$.
~\\

Since $\psi*\beta=\beta*\psi$, it follows that $\widecheck{T}_{\beta}\widecheck{T}_{\psi}=\widecheck{T}_{\psi}\widecheck{T}_{\beta}$, and consequently,  $\widecheck{T}_{\beta}$ and $\widecheck{T}_{\psi}$ commute.
\begin{prop} Let $\beta,\psi\in (\Lambda_{r}(\alpha))^{\prime}$, $r\in \{1,\infty\}$. The operators $\widecheck{T}_{\beta}$ and $\widecheck{T}_{\psi}$ commute and
$$\widecheck{T}_{\beta}\widecheck{T}_{\theta}=\widecheck{T}_{\psi}\widecheck{T}_{\beta}=\widecheck{T}_{\psi * \beta}.$$
\end{prop}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
 \section{Topologizability and 
 Power Boundedness of Convolution Operators on Power Series Spaces}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In this section, we establish necessary and sufficient conditions for the convolution operators $\widehat{T}_{\theta}$ defined on power series spaces to be topologizable, m-topologizable, and power bounded.

We first examine the convolution operators $\widehat{T}_{\theta}$ defined on a power series space of finite type $\Lambda_{1}(\alpha)$.

Let $\theta\in \Lambda_{1}(\alpha)$.
In the proof of Proposition \ref{PC1}, specifically in (\ref{FL}), we showed that  
\begin{equation}\label{FP1}
\|\widehat{T}_{\theta}e_{n}\|_{p}\leq \|\theta\|_{2p} \|e_{n}\|_{2p}
\end{equation}
holds for every $p,n\in \mathbb{N}$.
In the following, since we will consider powers of convolution operators, we use the notation  $\theta^{*k}$ 
\[
\theta^{*k} := \underbrace{\theta * \theta * \cdots * \theta}_{k\ \text{times}}
\]
to denote the $k$-times convolution of $\theta$ with itself. In Proposition \ref{CF}, we showed that the product of two convolution operators $\widehat{T}_{\theta}$ and $\widehat{T}_{\phi}$, is again a convolution operator $\widehat{T}_{\theta*\phi}$. By using (\ref{FP1}) and Proposition \ref{CF}, we obtain 
\begin{equation*}
\|\widehat{T}^{k}_{\theta} e_{n}\|_{p} =\|\widehat{T}_{\theta^{*k}}e_{n}\|_{p}\leq \|\theta^{*k}\|_{2p}\|e_{n}\|_{2p} .
\end{equation*}
for every $p,k,n\in \mathbb{N}$ and it is easy to write that
\begin{equation*}
\|\widehat{T}^{k}_{\theta} x\|_{p} =\|\widehat{T}_{\theta^{*k}}x\|_{p}\leq \|\theta^{*k}\|_{2p}\|x\|_{2p}
\end{equation*}
for every $x\in \Lambda_{1}(\alpha)$ and $p,k\in \mathbb{N}$, indeed it follows from 
\begin{equation*}
\|\widehat{T}^{k}_{\theta} x\|_{p} =\|\widehat{T}_{\theta^{*k}}x\|_{p} =\sum^{\infty}_{n=1} |x_{n}| \|\widehat{T}_{\theta^{*k}}e_{n}\|_{p} \leq \|\theta^{*k}\|_{2p} \sum^{\infty}_{n=1}|x_{n}|\|e_{n}\|_{2p}= \|\theta^{*k}\|_{2p} \|x\|_{2p}.
\end{equation*}
Moreover, we have
\begin{equation*}
\begin{split}
\|\theta^{*k}\|_{p}&=\|\widehat{T}_{\theta^{*k}}e_{1}\|_{p}=\|\widehat{T}_{\theta}(\widehat{T}_{\theta^{*(k-1)}}e_{1})\|_{p}=\\ &\leq \|\theta\|_{2p} \|\widehat{T}_{\theta^{*(k-1)}}e_{1}\|_{2p} \leq \dots\leq (\|\theta\|_{2p})^{k}
\end{split}
\end{equation*}
for every $p,k\in \mathbb{N}$. Hence, we obtain that
\begin{equation}\label{E1}
\|\widehat{T}^{k}_{\theta} e_{n}\|_{p} \leq (\|\theta\|_{2p})^{k}\|e_{n}\|_{2p} .
\end{equation}
for every $p,k,n\in \mathbb{N}$. This ensures that $\widehat{T}_{\theta}$ is topologizable, even m-topologizable for every $\theta\in \Lambda_{1}(\alpha)$. 
\begin{thm}
The convolution operator $\widehat{T}_{\theta}:\Lambda_{1}(\alpha)\to \Lambda_{1}(\alpha)$ is topologizable, even m-topologizable for every $\theta\in \Lambda_{1}(\alpha)$.
\end{thm}
 \begin{proof} The proof follows immediately from the inequality (\ref{E1}) and Lemma \ref{L1}.
 \end{proof} 

Given that the operators $\widehat{T}_{\theta}$ and $\widehat{T}_{\phi}$ commute and their product satisfies $\widehat{T}_{\theta}\widehat{T}_{\phi}=\widehat{T}_{\theta*\phi}$, we can conclude that their product is always topologizable - and even 
m-topologizable for every $\theta,\phi\in \Lambda_{1}(\alpha)$.

\begin{thm}\label{FP}  The convolution operator $\widehat{T}_{\theta}:\Lambda_{1}(\alpha)\to \Lambda_{1}(\alpha)$ is power bounded if and only if $\displaystyle \sup_{p\in \mathbb{N}} \|\theta\|_{p}\leq 1$.
\end{thm}
\begin{proof} If  $\displaystyle \sup_{p\in \mathbb{N}} \|\theta\|_{p}\leq 1$, the inequality (\ref{E1}) and Lemma \ref{L1} implies that  $\widehat{T}_{\theta}$ is power bounded. To prove the converse, we assume that 
$\widehat{T}_{\theta}$ is power bounded. Then, for every $p\in \mathbb{N}$ there exists a $q\in \mathbb{N}$ such that for every $k,n\in \mathbb{N}$
$$\|\widehat{T}^{k}_{\theta}(e_{n})\|_{p}\leq \|e_{n}\|_{q}$$
holds. In particular, taking $k=n=1$, we get   
$$\|\theta\|_{p}=\|\widehat{T}_{\theta}(e_{1})\|_{p}\leq \|e_{1}\|_{q}=e^{-\frac{1}{q}\alpha_{n}}< 1$$
which shows that $\displaystyle \sup_{p\in \mathbb{N}}\|\theta\|_{p}\leq 1$. This completes the proof.
 \end{proof}
 ~\\
 Based on Proposition \ref{ABR} and Theorem \ref{KT}, we are able to derive the following result:

 \begin{cor}\label{CCP}
 The following properties are equivalent for the convolution operator $\widehat{T}_{\theta}:\Lambda_{1}(\alpha)\to \Lambda_{1}(\alpha)$, where $\theta\in \Lambda_{1}(\alpha)$; 
\begin{itemize}
    \item[1.] $\widehat{T}_{\theta}$ is power bounded.
    \item[2.] $\widehat{T}_{\theta}$ mean ergodic.
    \item[3.]  $\widehat{T}_{\theta}$ is uniformly mean ergodic.
    \item[4.] $\widehat{T}_{\theta}$ is Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widehat{T}_{\theta}^{\hspace{0.025in}n}}{n}=0,$ pointwise in $\Lambda_{1}(\alpha)$.
    \item[5.] $\sup_{p\in \mathbb{N}} \|\theta\|_{p}\leq 1$.
\end{itemize}
 \end{cor}
\begin{proof}
Theorem \ref{FP} asserts the equivalence between conditions (1) and (5).
Theorem \ref{ABR}, which relies on the result of Albanese, Bonet, and Ricker regarding the mean ergodicity of Montel Köthe spaces, establishes that (1) implies (2).
Furthermore, based on the result of Kalmes and Santacreu presented in Theorem \ref{KT}, we know that statements (2), (3), and (4) are equivalent.
We now turn to proving that (4) implies (5). Let us  assume that 
$\widehat{T}_{\theta}$ is Ces\'aro bounded. Then, for every $p\in \mathbb{N}$ there exists a $q\in \mathbb{N}$ such that for every $k,n\in \mathbb{N}$
$$\|\widehat{T}^{[k]}_{\theta}(e_{n})\|_{p}\leq \|e_{n}\|_{q}$$
holds. In particular, taking $k=n=1$, we get   
$$\|\theta\|_{p}=\|\widehat{T}_{\theta}(e_{1})\|_{p}\leq \|e_{1}\|_{q}=e^{-\frac{1}{q}\alpha_{n}}< 1$$
which shows that $\displaystyle \sup_{p\in \mathbb{N}}\|\theta\|_{p}\leq 1$. This completes the proof.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We next turn to convolution operators on the power series spaces of infinite type to examine their properties. The stability of the sequence $\alpha$ is required to define the convolution operator $\widehat{T}_{\theta}$ on the space $\Lambda_{\infty}(\alpha)$.

Let $\theta\in \Lambda_{\infty}(\alpha)$. In the proof of Proposition \ref{PC2}, specifically in (\ref{E2}), we showed that  
\begin{equation}\label{E22}
\|\widehat{T}_{\theta}e_{n}\|_{p}\leq \|\theta\|_{Mp} \|e_{n}\|_{Mp}
\end{equation}
holds for every $p,n\in \mathbb{N}$ and here, $M \in \mathbb{N}$ denotes a constant satisfying $\displaystyle \sup_{n\in \mathbb{N}}\frac{ \alpha_{2n}}{\alpha_{n}} < M$.
In Proposition \ref{CF}, we showed that the product of two convolution operators, say $\widehat{T}_{\theta}$ and $\widehat{T}_{\phi}$, is again a convolution operator $\widehat{T}_{\theta*\phi}$. By using (\ref{E22}), we obtain 
\begin{equation*}
\|\widehat{T}^{k}_{\theta} e_{n}\|_{p} =\|\widehat{T}_{\theta^{*k}}e_{n}\|_{p}\leq \|\theta^{*k}\|_{Mp}\|e_{n}\|_{Mp} .
\end{equation*}
for every $p,k,n\in \mathbb{N}$ and it is easy to write that
\begin{equation*}
\|\widehat{T}^{k}_{\theta} x\|_{p} =\|\widehat{T}_{\theta^{*k}}x\|_{p}\leq \|\theta^{*k}\|_{Mp}\|x\|_{Mp}
\end{equation*}
for every $x\in \Lambda_{\infty}(\alpha)$ and $p,k\in \mathbb{N}$.
Moreover, we have
\begin{equation*}
\begin{split}
\|\theta^{*k}\|_{p}&=\|\widehat{T}_{\theta^{*k}}e_{1}\|_{p}=\|\widehat{T}_{\theta}(\widehat{T}_{\theta^{*(k-1)}}e_{1})\|_{p}\\ &\leq \|\theta\|_{Mp} \|\widehat{T}_{\theta^{*(k-1)}}e_{1}\|_{2p} \leq \dots\leq (\|\theta\|_{Mp})^{k}
\end{split}
\end{equation*}
for every $p,k\in \mathbb{N}$. Hence, we obtain that
\begin{equation}\label{IT1}
\|\widehat{T}^{k}_{\theta} e_{n}\|_{p} \leq (\|\theta\|_{Mp})^{k}\|e_{n}\|_{Mp} .
\end{equation}
holds for every $p,k,n\in \mathbb{N}$. This ensures that $\widehat{T}_{\theta}$ is topologizable, even m-topologizable for every $\theta\in \Lambda_{\infty}(\alpha)$. 
\begin{thm} Let $\alpha$ be a stable sequence. 
The convolution operator $\widehat{T}_{\theta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is topologizable, even m-topologizable for every $\theta\in \Lambda_{\infty}(\alpha)$.
\end{thm}
 \begin{proof} The proof follows immediately from the inequality (\ref{IT1}) and Lemma \ref{L1}.
 \end{proof} 
We again note that the operators $\widehat{T}_{\theta}$ and $\widehat{T}_{\phi}$ commute and their product satisfies $\widehat{T}_{\theta}\widehat{T}_{\phi}=\widehat{T}_{\theta*\phi}$, then we can conclude that their product is always topologizable - and even 
m-topologizable for every $\theta,\phi\in \Lambda_{\infty}(\alpha)$. 
\begin{thm}\label{IP} Let $\alpha$ be a stable sequence. The convolution operator $\widehat{T}_{\theta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is power bounded if and only if for every $p\in \mathbb{N}$, there exists a $q\in \mathbb{N}$ so that 
$$\|\theta^{*k}\|_{p}\leq \|e_{1}\|_{q}$$
for every $k\in\mathbb{N}$ 
\end{thm}
\begin{proof} If the convolution operator $\widehat{T}_{\theta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is power bounded, then for every $p\in \mathbb{N}$ there is a $q\in \mathbb{N}$ such that
$$\|\theta^{*k}\|_{p}=\|\widehat{T}_{\theta}^{k}e_{1}\|_{p} \leq \|e_{1}\|_{q}$$
for every $k\in \mathbb{N}$. For the converse, let us assume that for every $p\in \mathbb{N}$, there exists a $q\in \mathbb{N}$ so that 
$$\|\theta^{*k}\|_{p}\leq \|e_{1}\|_{q}$$
for every $k\in\mathbb{N}$. Then, by using (\ref{IT1}) we obtain that for every $p\in \mathbb{N}$ there exist $q^{\prime},q^{\prime\prime}\in \mathbb{N}$ such that for every $k\in \mathbb{N}$ the inequalities
$$\|\widehat{T}_{\theta}^{k}e_{n}\|_{p}\leq \|\theta^{*k}\|_{Mp}\|e_{n}\|_{Mp}\leq \|e_{1}\|_{q^{\prime}}\|e_{n}\|_{Mp}\leq \|e_{n}\|_{Mp+q^{\prime}}=\|e_{n}\|_{q^{\prime\prime}}$$
hold for every $n\in \mathbb{N}$. Lemma \ref{L1}  says that $\widehat{T}_{\theta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is power bounded.
\end{proof}

We make use of the conclusions of Proposition \ref{ABR} and Theorem \ref{KT} to establish the following result.
\begin{cor}
  Let $\alpha$ be a stable sequence and $\theta\in \Lambda_{\infty}(\alpha)$. Suppose that for every $p\in \mathbb{N}$, there exists a $q\in \mathbb{N}$ so that
$$\|\theta^{*k}\|_{p}\leq \|e_{1}\|_{q}$$
for every $k\in\mathbb{N}$. Then  
the convolution operator $\widehat{T}_{\theta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ satisfies the following properties:
\begin{itemize}
    \item[1.] $\widehat{T}_{\theta}$ is power bounded.
    \item[2.] $\widehat{T}_{\theta}$ is  mean ergodic.
    \item[3.]  $\widehat{T}_{\theta}$ is uniformly mean ergodic.
    \item[4.] $\widehat{T}_{\theta}$ is Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widehat{T}_{\theta}^{\hspace{0.025in}n}}{n}=0,$ pointwise in $\Lambda_{1}(\alpha)$.
\end{itemize}
 \end{cor}
