\section{Topologizability and Power Boundedness  of Dual Convolution Operators on Power Series Spaces}

In this section, we establish necessary and sufficient conditions for dual convolution operators $\widecheck{T}_{\beta}$ defined on power series spaces to be topologizable, m-topologizable, and power bounded.

\begin{thm}\label{TU1} Let $\Lambda_{\infty}(\alpha)$ be a nuclear power series space and $\beta\in (\Lambda_{\infty}(\alpha))^{\prime}$. Then, the operator $\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha) \to \Lambda_{\infty}(\alpha)$ is topologizable if and only if for every $p\in \mathbb{N}$ there exists a $q\in \mathbb{N}$ so that for every $k\in \mathbb{N}$ there is a $L_{k,p}>0$ such that
$$|\beta^{*k}_{n-1}|\leq L_{k,p}e^{q\alpha_{n}}$$
for every $n\in \mathbb{N}$.
\end{thm}
\begin{proof} If the operator $\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha) \to \Lambda_{\infty}(\alpha)$ is topologizable, then for every $p\in \mathbb{N}$ there exists a 
$q\in \mathbb{N}$ so that for every $k\in \mathbb{N}$ there is a $M_{k,p}>0$ such that
$$\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p}=\|\widecheck{T}_{\beta^{*k}}e_{n}\|=\sum^{n}_{j=1}|\beta^{*k}_{n-j}|e^{p\alpha_{j}}\leq M_{k,p}\|e_{n}\|_{q}$$
for every $ n\in \mathbb{N}$ and this gives us that 
$$|\beta^{*k}_{n-j}|e^{p\alpha_{j}}\leq M_{k,p}e^{q\alpha_{n}}$$
for every $1\leq j\leq n$. Taking $j=1$, we obtain
$$|\beta^{*k}_{n-1}|\leq L_{k,p} e^{q\alpha_{n}}$$
where $L_{k,p}=e^{-p\alpha_{1}}M_{k,p}$. For the converse, assume that for every $p\in \mathbb{N}$ there exists a $q\in \mathbb{N}$ so that for every $k\in \mathbb{N}$ there is a $L_{k,p}>0$ such that
$$|\beta^{*k}_{n-1}|\leq L_{k,p}e^{q\alpha_{n}}$$
holds for every $n\in \mathbb{N}$. Then we can write
\begin{equation*}
 \begin{split}
\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p}&=\sum^{n}_{j=1}|\beta^{*k}_{n-j}|e^{p\alpha_{j}}=\sum^{n}_{j=1}|\beta^{*k}_{j-1}|e^{p\alpha_{n-j+1}}\\ &\leq L_{k,p}\sum^{n}_{j=1}e^{q\alpha_{j}} e^{p\alpha_{n-j+1}} \leq L_{k,p}e^{p\alpha_{n}}\sum^{n}_{j=1}e^{q\alpha_{j}} 
 \end{split}
\end{equation*}
for every $n\in \mathbb{N}$. In the proof Proposition of \ref{PC4}, we used the nuclearity of $\Lambda_{\infty}(\alpha)$,  to show that there exist $m_{1}\in \mathbb{N}$ and $D>0$ such that for all $p,n \in \mathbb{N}$
\begin{equation*}
\sum^{n}_{j=1} e^{p\alpha_{j}}\leq D e^{(p+m_{1})\alpha_{n}}.
\end{equation*} 
Hence for every $p\in \mathbb{N}$ there exists a $q^{\prime}=p+q+m_{1}$ such that for every $k\in \mathbb{N}$ there is $M_{k,p}=DL_{k,p}$ such that
\begin{equation*}
\begin{split}
\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p} & \leq L_{k,p}e^{p\alpha_{n}}\sum^{n}_{j=1}e^{q\alpha_{j}}\leq D L_{k,p} e^{(q+p+m_{2})\alpha_{n}}\\ &= DL_{k,p} \|e_{n}\|_{p+q+m_{1}}=M_{k,p} \|e_{n}\|_{q^{\prime}}.
\end{split}
\end{equation*}
 This says that $\widecheck{T}_{\beta}$ is topologizable.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The proof of the following theorem follows by analogous arguments to those in Theorem \ref{TU1} and is therefore omitted.
\begin{thm}  Let $\Lambda_{\infty}(\alpha)$ be a nuclear power series space and $\beta\in (\Lambda_{\infty}(\alpha))^{\prime}$. Then,
\begin{itemize}
\item[(i)]
$\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha) \to \Lambda_{\infty}(\alpha)$ is m-topologizable if and only if for every $p\in \mathbb{N}$ there exist $q\in \mathbb{N}$ and $D_{p}>0$ so that for every $k\in \mathbb{N}$  such that
$$|\beta^{*k}_{n-1}|\leq D^{k}_{p}e^{q\alpha_{n}}$$
for every $n\in \mathbb{N}$.
\item[(ii)] $\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha) \to \Lambda_{\infty}(\alpha)$ is power bounded if and only if for every $p\in \mathbb{N}$ there exist $q\in \mathbb{N}$ and  so that
$$|\beta^{*k}_{n-1}|\leq e^{q\alpha_{n}}$$
for every $k,n\in \mathbb{N}$.
\end{itemize}
\end{thm}

