We now examine the properties of the dual convolution operator defined on power series spaces of finite type.

\begin{thm}\label{TU2}  Let $\alpha=(\alpha_{n})_{n\in \mathbb{N}}$ be a stable sequence, $\beta\in (\Lambda_{1}(\alpha))^{\prime}$, and assume that the power series space of finite type $\Lambda_{1}(\alpha)$ is nuclear.  $\widecheck{T}_{\beta}:\Lambda_{1}(\alpha) \to \Lambda_{1}(\alpha)$ is topologizable if and only if for every $p\in \mathbb{N}$ there exists a $q\in \mathbb{N}$ so that for every $k\in \mathbb{N}$ there is a $L_{k,p}>0$ such that
$$|\beta^{k}_{n-1}|\leq L_{k,p}e^{-\frac{1}{q}\alpha_{n}}$$
for every $n\in \mathbb{N}$.
\end{thm}
\begin{proof} If the operator $\widecheck{T}_{\beta}:\Lambda_{1}(\alpha) \to \Lambda_{1}(\alpha)$ is topologizable, it follows that for every $p\in \mathbb{N}$ there exists a 
$q\in \mathbb{N}$ so that for every $k\in \mathbb{N}$ there is a $M_{k,p}>0$ such that
$$\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p}=\sum^{n}_{j=1} |\beta^{*k}_{n-1}|e^{-\frac{1}{p}\alpha_{j}}\leq M_{k,p}\|e_{n}\|_{q}$$
for every $ n\in \mathbb{N}$, which in turn implies
$$|\beta^{*k}_{n-j}|e^{-\frac{1}{p}\alpha_{j}}\leq M_{k,p}e^{-\frac{1}{q}\alpha_{n}}$$
for all $1\leq j\leq n$ and 
$$|\beta^{*k}_{n-1}|\leq L_{k,p} e^{-\frac{1}{q}\alpha_{n}}$$
where $L_{k,p}=e^{\frac{1}{p}\alpha_{1}}M_{k,p}$. To prove the converse, suppose that for every $p\in \mathbb{N}$ there exists $q\in \mathbb{N}$ such that for every $k\in \mathbb{N}$, one can find a constant $L_{k,p}$ satisfying
$$|\beta^{*k}_{n-1}|\leq L_{k,p}e^{-\frac{1}{q}\alpha_{n}}$$
for every $n\in \mathbb{N}$. Hence, for every $n\in \mathbb{N}$, we obtain
\begin{equation*}
 \begin{split}
\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p}&=\sum^{n}_{j=1}|\beta^{*k}_{n-j}|e^{-\frac{1}{p}\alpha_{j}}=\sum^{n}_{j=1}|\beta^{*k}_{j-1}|e^{-\frac{1}{p}\alpha_{n-j+1}}\\ 
 &\leq L_{k,p}\sum^{n}_{j=1}e^{-\frac{1}{q}\alpha_{j}} e^{-\frac{1}{p}\alpha_{n-j+1}} \leq  L_{k,p}\sum^{n}_{j=1}e^{-\frac{1}{\max\{q,p\}}(\alpha_{j}+\alpha_{n-j+1})}
 \end{split}
\end{equation*}
The stability of $\alpha$ ensures the existence of $M\in \mathbb{N}$ satisfying $\alpha_{n}\leq M(\alpha_{n-j+1}+\alpha_{j})$ for all $1\leq j\leq n$, $n\in \mathbb{N}$, see (\ref{S1}) in Proposition \ref{PC3} for details. Due to the nuclearity of $\Lambda_{1}(\alpha)$, for every $k\in \mathbb{N}$ there exists a $D_{k}>0$ satisfying
$$ne^{-\frac{1}{k}\alpha_{n}}\leq D_{k}e^{-\frac{1}{2k}\alpha_{n}}$$
for every $n\in \mathbb{N}$, for details, refer to (\ref{FND}) in Proposition \ref{PC3}.  Employing these properties, we now establish the following
\begin{equation*}
 \begin{split}
\|\widecheck{T}^{k}_{\beta}e_{n}\|_{p}& \leq  L_{k,p}\sum^{n}_{j=1}e^{-\frac{1}{\max\{q,p\}}(\alpha_{j}+\alpha_{n-j+1})}
\leq L_{k,p} \sum^{n}_{j=1} e^{-\frac{1}{M\max\{q,p\}}\alpha_{n}}\\ &=   L_{k,p} n e^{-\frac{1}{M\max\{q,p\}}\alpha_{n}} \leq D_{p} L_{k,p} e^{-\frac{1}{2M\max\{q,p\}}\alpha_{n}}= D_{p}L_{k,p} \|e_{n}\|_{2M\max\{q,p\}}
 \end{split}
\end{equation*}
This says that $\widecheck{T}_{\beta}$ is topologizable.
\end{proof}
