\section{Topologizability and Power Boundedness  of Toeplitz Operators $\mathbf{T_{\theta,\beta}}$ on $\mathbf{\Lambda_{1}(n)}$ and $\mathbf{\Lambda_{\infty}(n)}$}

In this section, we aim to establish necessary conditions for the Toeplitz operator $T_{\theta, \beta}$, defined on the power series spaces $\Lambda_{1}(n)$ and $\Lambda_{\infty}(n)$, to be topologizable, m-topologizable, and power bounded. This, in turn, will allow us to identify necessary conditions for the operator $T_{F}$ to be topologizable, m-topologizable, and power bounded on the spaces $H(\mathbb{C})$ and $H(\mathbb{D})$.

Since the sequence $(n)_{n\in \mathbb{N}}$
is stable and satisfies
$\displaystyle \lim_{n \to \infty}\frac{\ln n}{n}=0$, the power series spaces $\Lambda_{1}(n)$ and $\Lambda_{\infty}(n)$ are nuclear, in this setting, the operator
\begin{equation*}
\begin{split}
T_{\theta,\beta}:&\;\Lambda_{r}(n)\to \Lambda_{r}(n) \\
&T_{\theta, \beta}=\widehat{T}_{\theta}+\widecheck{T}_{\beta}
\end{split}
\end{equation*}
is well-defined and continuous for all $\theta\in \Lambda_{r}(n)$ and $\beta\in (\Lambda_{r}(n))^{\prime}$, $r\in \{1,\infty\}$. 

The operators $\widehat{T}_{\theta}$ and $\widecheck{T}_{\beta}$, and are generally non-commuting, it becomes essential to examine the behavior of $\widehat{T}_{\theta}$ and $\widecheck{T}_{\beta}$ on the spaces $\Lambda_{1}(n)$ and $\Lambda_{\infty}(n)$ in greater detail.

Definition \ref{FSC1} introduced the concept of strongly tame operators, which naturally ensures m-topologizability. Furthermore, when the constants $C_{p}$ satisfy $C_{p}\leq 1$ for all $p\in \mathbb{N}$, the operator becomes power bounded. Given that this property is preserved under both operator addition and multiplication, we aim to identify conditions guaranteeing that both 
$\widehat{T}_{\theta}$ and 
$\widecheck{T}_{\beta}$ are strongly tame. This will, in turn, ensure the desired properties for the operator $T_{\theta,\beta}=\widehat{T}_{\theta} +\widecheck{T}_{\beta}$.

\begin{prop} For every $\theta\in \Lambda_{1}(n)$, the convolution operator $\widehat{T}_{\theta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is strongly tame since  
$$\|\widehat{T}_{\theta}e_{n}\|_{p}\leq e^{\frac{1}{2p}}\|\theta\|_{2p}\|e_{n}\|_{p}$$
holds for every $p,n\in \mathbb{N}$.
\end{prop}
\begin{proof} Let $\theta\in \Lambda_{1}(n)$. For every $p,n\in \mathbb{N}$, the inequalities 
\begin{equation*}
\begin{split}\|\widehat{T}_{\theta}e_{n}\|_{p}&=\sum^{\infty}_{j=n} |\theta_{j-n}|e^{-\frac{1}{p}j}=\sum^{\infty}_{j=n} |\theta_{j-n}|e^{-\frac{1}{2p}(j-n+1)}e^{\frac{1}{2p}(j-n+1)}e^{-\frac{1}{p}j} \\
&= \sum^{\infty}_{j=n} |\theta_{j-n}|e^{-\frac{1}{2p}(j-n+1)}e^{-\frac{1}{2p}(j+n)}e^{\frac{1}{2p}} \\
&\leq e^{\frac{1}{2p}} e^{-\frac{1}{p}n}\sum^{\infty}_{j=n}|\theta_{j-n}|e^{-\frac{1}{2p}(j-n+1)}=e^{\frac{1}{2p}}\|\theta\|_{2p}\|e_{n}\|_{p}
\end{split}
\end{equation*}
holds. This implies that $\widehat{T}_{\theta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is strongly tame by Lemma \ref{L1}.
\end{proof}

\begin{prop} For every $\theta\in \Lambda_{\infty}(n)$, the convolution operator $\widehat{T}_{\theta}:\Lambda_{\infty}(n)\to \Lambda_{\infty}(n)$ is strongly tame since  
$$\|\widehat{T}_{\theta}e_{n}\|_{p}\leq \|\theta\|_{p}\|e_{n}\|_{p}$$
holds for every $p,n\in \mathbb{N}$.
\end{prop}
\begin{proof} Let $\theta\in \Lambda_{\infty}(n)$.  For every $p,n\in \mathbb{N}$, the inequalities
\begin{equation*}
\begin{split}\|\widehat{T}_{\theta}e_{n}\|_{p}&=\sum^{\infty}_{j=n} |\theta_{j-n}|e^{pj}=e^{pn} \sum^{\infty}_{j=n} |\theta_{j-n}|e^{p(j-n)}\\ &\leq e^{pn} \sum^{\infty}_{j=n} |\theta_{j-n}|e^{p(j-n+1)} =\|\theta\|_{p}\|e_{n}\|_{p}
\end{split}
\end{equation*}
holds. This implies that $\widehat{T}_{\theta}:\Lambda_{\infty}(n)\to \Lambda_{\infty}(n)$ is strongly tame, by Lemma \ref{L1}.
\end{proof}

\begin{prop} Let $\Lambda_{\infty}(\alpha)$ be a nuclear space and $\beta\in (\Lambda_{\infty}(\alpha_n))^{\prime}$. If $\displaystyle A=\sum^{\infty}_{n=1} |\beta_{n-1}|<\infty$, then it follows that
$$\|\widecheck{T}_{\beta}e_{n}\|_{p}\leq A\|e_{n}\|_{p}$$
for every $n,p\in \mathbb{N}$ and this implies that the dual convolution operator $\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is strongly tame.
\end{prop}
\begin{proof} For every $\beta\in (\Lambda_{\infty}(\alpha))^{\prime}$ satisfying $\displaystyle A=\sum^{\infty}_{n=1} |\beta_{n-1}|<\infty$, it follows that
\begin{equation*}
\begin{split}
\|\widecheck{T}_{\beta}e_{n}\|&=\sum^{n}_{j=1}|\beta_{n-j}|\|e_{j}\|_{p}=\sum^{n}_{j=1}|\beta_{n-j}|e^{p\alpha_{j}} \leq e^{p\alpha_{n}} \sum^{n}_{j=1}|\beta_{n-j}| \\
&=e^{p\alpha_{n}} \sum^{n}_{j=1} |\beta_{j-1}|\leq A e^{p\alpha_{n}}= A \|e_{n}\|_{p}  
\end{split}
\end{equation*}
for every $n,p\in \mathbb{N}$. Hence the dual convolution operator $\widecheck{T}_{\beta}:\Lambda_{\infty}(\alpha)\to \Lambda_{\infty}(\alpha)$ is strongly tame by Lemma \ref{L1}.
\end{proof}

%We want to note that for every $\beta\in (\Lambda_{\infty}(n))^{\prime}$, the sum $\sum^{\infty}_{n=1}|\beta_{n-1}|$ is finite. Indeed, there exist $m_{0}\in \mathbb{N}$ and $C_{0}>0$ satisfying $|\beta_{n-1}|\leq Ce^{}$ 

\begin{prop} Let  $\beta\in (\Lambda_{1}(n))^{\prime}$. If $\displaystyle B=\sum^{\infty}_{n=1} |\beta_{n-1}|e^{n}<\infty$, then it follows that
$$\|\widecheck{T}_{\beta}e_{n}\|_{p}\leq B\|e_{n}\|_{p}$$
for every $n,p\in \mathbb{N}$ and this implies that the dual convolution operator $\widecheck{T}_{\beta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is strongly tame.
\end{prop}
\begin{proof}  For every $\theta\in (\Lambda_{\infty}(\alpha))^{\prime}$ satisfying $\displaystyle B=\sum_{n\in \mathbb{N}} |\beta_{n-1}|e^{n}<\infty$, it follows that
\begin{equation*}
\begin{split}
\|\widecheck{T}_{\beta}e_{n}\|_{p}&=\sum^{n}_{j=1}|\beta_{n-j}|e^{-\frac{1}{p}j}  =e^{-\frac{1}{p}n}\sum^{n}_{j=1}|\beta_{n-j}|e^{\frac{1}{p}(n-j)}
\\ &=e^{-\frac{1}{p}n} \sum^{n-1}_{j=0}|\beta_{j}|e^{\frac{1}{p}j} \leq Be^{-\frac{1}{p}n} =B\|e_{n}\|_{p}  
\end{split}
\end{equation*}
for every $n,p\in \mathbb{N}$. Hence the dual convolution operator $\widecheck{T}_{\beta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is strongly tame by Lemma \ref{L1}.
\end{proof}


\begin{prop}\label{ST1}Let $\theta\in \Lambda_{\infty}(n)$ and $\beta\in (\Lambda_{\infty}(n))^{\prime}$. The Toeplitz operator $T_{\theta,\beta}:\Lambda_{\infty}(n)\to \Lambda_{\infty}(n)$ is 
\begin{itemize}
\item[(i)] strongly tame, and hence m-topologizable if $\displaystyle \sum^{\infty}_{n=1} |\beta_{n-1}|<\infty$.
\item[(ii)] power bounded if $\displaystyle \sup_{p\in \mathbb{N}} \|\theta\|_{p}+ \sum_{n\in \mathbb{N}} |\beta_{n-1}|\leq 1$.
\end{itemize}
\end{prop}

\begin{proof} Let $\theta\in \Lambda_{\infty}(n)$ and $\beta\in (\Lambda_{\infty}(n))^{\prime}$. The convolution operator $\widehat{T}_{\theta}$ is strongly tame and
$$\|\widehat{T}_{\theta}e_{n}\|_{p}\leq \|\theta\|_{p}\|e_{n}\|_{p}$$
holds for every $p,n\in \mathbb{N}$. If $\displaystyle A=\sum_{n\in \mathbb{N}} |\beta_{n-1}|<\infty$, the dual convolution operator $\widecheck{T}_{\beta}:\Lambda_{\infty}(n)\to \Lambda_{\infty}(n)$ is strongly tame and 
$$\|\widecheck{T}_{\beta}e_{n}\|_{p}\leq A\|e_{n}\|_{p}$$
for every $n,p\in \mathbb{N}$. Hence, we obtain
\begin{equation*}
\begin{split}
\|T_{\theta,\beta}e_{n}\|_{p}&= \|\widehat{T}_{\theta}e_{n}+\widecheck{T}_{\beta}e_{n}\|  \leq \|\widehat{T}_{\theta}e_{n}\|_{p} +\|\widecheck{T}_{\beta}e_{n}\|_{p} \\
& \leq (\|\theta\|_{p}+A)\|e_{n}\|_{p}
\end{split}
\end{equation*}
for every $n,p\in \mathbb{N}$. This implies that $T_{\theta,\beta}$ is strongly tame, and hence it is m-topologizable. Moreover, if $\displaystyle \sup_{p\in \mathbb{N}} \|\theta\|_{p}+ \sum_{n\in \mathbb{N}} |\beta_{n-1}|\leq 1$, it follows directly that $T_{\theta,\beta}$ is power bounded.
\end{proof}

An analogous result holds for the power series space of finite type $\Lambda_{1}(n)$, as stated in the following proposition.
As the proof is based once again on the property that the sum and the product of strongly tame operators remain strongly tame, it is omitted.
\begin{prop}\label{ST2}
 Let $\theta\in \Lambda_{1}(n)$ and $\beta\in (\Lambda_{1}(n))^{\prime}$. The Toeplitz operator $T_{\theta,\beta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is 
\begin{itemize}
\item[(i)] strongly tame, and hence m-topologizable if $\displaystyle \sum_{n\in \mathbb{N}} |\beta_{n-1}|e^{n}<\infty$.
\item[(ii)] power bounded if $\displaystyle \sup_{p\in \mathbb{N}} e^{\frac{1}{2p}}\|\theta\|_{2p}+\sum_{n\in \mathbb{N}} |\beta_{n-1}|e^{n}\leq 1.$
\end{itemize}
\end{prop}

The following result follows as a direct consequence of Proposition \ref{ABR} and Theorem \ref{KT}.
\begin{cor}
Let $\theta\in \Lambda_{r}(n)$ and $\beta\in (\Lambda_{r}(n))^{\prime}$, $r\in \{1,\infty\}$. 
\begin{itemize}
\item[(a)]  The Toeplitz operator $T_{\theta,\beta}:\Lambda_{1}(n)\to \Lambda_{1}(n)$ is 
\begin{itemize}
    \item[1.] power bounded,
    \item[2.] mean ergodic,
    \item[3.] uniformly mean ergodic,
    \item[4.] Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widecheck{T}^{\hspace{0.025in}n}_{\beta}}{n}=0,$ pointwise in $\Lambda_{1}(n)$
\end{itemize}
provided that $\displaystyle \sup_{p\in \mathbb{N}} e^{\frac{1}{2p}}\|\theta\|_{2p}+\sum_{n\in \mathbb{N}} |\beta_{n-1}|e^{n}\leq 1$.
\item[(b)] The Toeplitz operator $T_{\theta,\beta}:\Lambda_{\infty}(n)\to \Lambda_{\infty}(n)$ is 
\begin{itemize}
    \item[1.] power bounded,
    \item[2.] mean ergodic,
    \item[3.] uniformly mean ergodic,
    \item[4.] Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widecheck{T}^{\hspace{0.025in}n}_{\beta}}{n}=0,$ pointwise in $\Lambda_{\infty}(n)$
\end{itemize}
provided that $\displaystyle \sup_{p\in \mathbb{N}} \|\theta\|_{p}+ \sum_{n\in \mathbb{N}} |\beta_{n-1}|\leq 1$.
\end{itemize}
 \end{cor}

Next, we turn our attention to Toeplitz operators defined on $H(\mathbb{C})$ and $H(\mathbb{D})$. As shown in Theorems \ref{J1} and \ref{J2}, for a symbol $F$, the entries of the Toeplitz matrix associated with the operator $T_F$, defined as in (\ref{T}) and (\ref{TFF}), arise from the Laurent expansion of $F$ at the origin.
Building upon this and Propositions \ref{ST1} and \ref{ST2}, we derive the following corollaries.

\begin{cor} Let $\displaystyle F(z)=\sum^{\infty}_{n=-\infty}a_{n}z^{n}$ be a holomorphic function in a punctured neighborhood $\infty$.  The Toeplitz operator $T_{F}:H(\mathbb{C})\to H(\mathbb{C})$ is
\begin{itemize}
\item[(i)] strongly tame, and hence m-topologizable if $\displaystyle \sum^{\infty}_{n=1} |a_{-n+1}|<\infty$.
\item[(ii)] power bounded if $\displaystyle \sup_{p\in \mathbb{N}} \left(\sum^{\infty}_{n=1}|a_{n}|e^{pn}\right)+ \sum_{n\in \mathbb{N}} |a_{-n+1}|\leq 1$.
\end{itemize}
\end{cor}


\begin{cor} Let $\displaystyle F(z)=\sum^{\infty}_{n=-\infty}a_{n}z^{n}$ be a holomorphic function in some annulus $\{R<|z|<1\}$ $R<1$.  The Toeplitz operator $T_{F}:H(\mathbb{\mathbb{D}})\to H(\mathbb{\mathbb{D}})$ is
\begin{itemize}
\item[(i)] strongly tame, and hence m-topologizable if $\displaystyle \sum^{\infty}_{n=1} |a_{-n+1}|e^{n}<\infty$.
\item[(ii)] power bounded if $\displaystyle \sup_{p\in \mathbb{N}} e^{\frac{1}{2p}}\left(\sum^{\infty}_{n=1}|a_{n}|e^{2pn}\right)+ \sum_{n\in \mathbb{N}} |a_{-n+1}|e^{n}\leq 1$.
\end{itemize}
\end{cor}

We again apply the Proposition \ref{ABR} and Theorem \ref{KT} to obtain the following.

\begin{cor}
\begin{itemize}
\item[(a)] Let $\displaystyle F(z)=\sum^{\infty}_{n=-\infty}a_{n}z^{n}$ be a holomorphic function in a punctured neighborhood $\infty$.  The Toeplitz operator $T_{F}:H(\mathbb{C})\to H(\mathbb{C})$ is
\begin{itemize}
    \item[1.] power bounded,
    \item[2.] mean ergodic,
    \item[3.] uniformly mean ergodic,
    \item[4.] Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widecheck{T}^{\hspace{0.025in}n}_{\beta}}{n}=0,$ pointwise in $\Lambda_{1}(n)$
\end{itemize}
provided that $\displaystyle \sup_{p\in \mathbb{N}} \left(\sum^{\infty}_{n=1}|a_{n}|e^{pn}\right)+ \sum_{n\in \mathbb{N}} |a_{-n+1}|\leq 1$.
\item[(b)] Let $\displaystyle F(z)=\sum^{\infty}_{n=-\infty}a_{n}z^{n}$ be a holomorphic function in some annulus $\{R<|z|<1\}$ $R<1$.  The Toeplitz operator $T_{F}:H(\mathbb{\mathbb{D}})\to H(\mathbb{\mathbb{D}})$ is 
\begin{itemize}
    \item[1.] power bounded,
    \item[2.] mean ergodic,
    \item[3.] uniformly mean ergodic,
    \item[4.] Ces\'aro bounded and $\displaystyle \lim_{n\to \infty} \frac{\widecheck{T}^{\hspace{0.025in}n}_{\beta}}{n}=0,$ pointwise in $\Lambda_{1}(n)$
\end{itemize}
provided that $\displaystyle \sup_{p\in \mathbb{N}} e^{\frac{1}{2p}}\left(\sum^{\infty}_{n=1}|a_{n}|e^{2pn}\right)+ \sum_{n\in \mathbb{N}} |a_{-n+1}|e^{n}\leq 1$.
\end{itemize}
 \end{cor}
