\section{Model Analysis}\label{sec_three}
\subsection*{Positivity of Solutions}
The proposed TB transmission dynamics model provided in equation \(\left( \ref{eq:4.1} \right)\) is epidemiologically meaningful if we can show that the solution of the system with nonnegative initial conditions will remain nonnegative for all $t > 0$.
%
\begin{theorem}
Let $S(0)\geq 0,~ V(0) \geq 0, ~ E(0) \geq  0,~ I(0) \geq  0,~ T(0) \geq 0$, and $R(0) \geq 0$, then the solutions $S(t), V(t), E(t), I(t), T(t), R(t)$ of the system of equations in \eqref{eq:4.1} are nonnegative for all $ t \geq 0$.
\end{theorem}
%
\begin{proof}
Consider $(S(t), V(t), E(t), I(t), T(t), R(t))$ to be the solution of the system of equations with the initial conditions $(S(0), V(0), E(0), I(0), T(0), R(0))$. Now, from the first equation of the system in \ref{eq:4.1}, we initially have		
\begin{equation*}
\displaystyle\frac{dS}{dt} = \Lambda + \eta R + \theta V-(\beta I + \pi + \mu)S  \geq - (\beta I + \pi + \mu)S.
\end{equation*}	
Using techniques of separation of variables, we obtain
\begin{equation}\label{eq.thm1}
\displaystyle\frac{dS}{S}\geq - (\beta I + \pi + \mu)dt.
\end{equation}
Integrating both sides of Equation \eqref{eq.thm1} and solving for $S(t)$ yields
\begin{equation*}
S(t)\geq S(0) \cdot e^{\displaystyle-\left(\beta I + \pi + \mu\right)t} > 0.
\end{equation*}
Similarly, for $V(t), E(t), I(t), T(t)$ and $R(t)$, we obtain
\begin{align*}
V(t) &\geq V(0) \cdot e^{\displaystyle -\left(\theta + \mu\right)t} \geq 0,~ E(t) \geq E(0) \cdot e^{\displaystyle -\left(\gamma +  \mu\right)t} \geq 0,\\
I(t) &\geq I(0) \cdot e^{\displaystyle -\left(\delta + \tau + \mu\right)t} \geq 0,~T(t) \geq T(0) \cdot e^{\displaystyle -\left(\alpha + \omega + \mu\right)t}\geq 0,~ \text{and}\\
R(t) &\geq R(0) \cdot e^{\displaystyle -\left(\eta +  \mu\right)t}\geq 0
\end{align*} \end{proof}
%
\subsection*{Invariant Region (Boundedness of the solution)}
\begin{theorem}
All the solutions $N(t) = S(t) +  V(t) +  E(t) + I(t) +T(t) + R(t)$ of the system of the model equation  \eqref{eq:4.1} are bounded.
\end{theorem}
\begin{proof}
To show that the population size of each compartment is bounded, we prefer to show that the total population size at time $t$ of the whole system $N(t)$ is bounded. The total population size $N$ at any time $t$  can be given by: 
\begin{equation*}
 N(t) = S(t) + V(t) + E(t) + I(t) + T(t) + R(t).
\end{equation*}
Differentiating with respect to time $t$ and using the system of equations of the model, we obtain: 
\begin{equation}\label{eq.thm2}
\displaystyle\frac{dN}{dt} = \displaystyle\frac{dS}{dt} + \displaystyle\frac{dV}{dt} + \displaystyle\frac{dE}{dt} + \displaystyle\frac{dI}{dt} + \displaystyle\frac{dT}{dt} +
\displaystyle\frac{dR}{dt}.
\end{equation}
Substituting the differential equation \eqref{eq:4.1} into Equation \eqref{eq.thm2}, we obtain
\begin{equation}\label{eq.thm3}
\displaystyle \frac{dN}{dt} = \Lambda - \mu N - \tau I - \omega T.
\end{equation}
Using the standard comparison theorem, if there is no disease-induced death rate of individuals in the population (i.e., $\tau$, $\omega$ = 0), Equation \eqref{eq.thm3} becomes
\begin{equation}\label{eq.thm4}
\displaystyle\frac{dN}{\Lambda - \mu N} \leq dt.
\end{equation}
By integrating both sides of Equation \eqref{eq.thm4} and solving it, we obtain
\begin{equation}\label{eq.thm5}
\Lambda - \mu N \geq N(0)e^{-\mu t}.
\end{equation}	
Since $\lim_{t \to \infty} \displaystyle e^{\displaystyle -\mu t} = 0$, Equation \eqref{eq.thm5} can be simplified as
\begin{equation*}
\Lambda - \mu N \geq  0 \Longrightarrow N \leq \displaystyle\frac{\varLambda}{\mu},
\end{equation*}
where $N$ is the total number of the human population. Therefore, the feasible solution set of equation \eqref{eq:4.1} is bounded and remains in the following region
\begin{equation*}
\Omega = \bigg\{(S,V,E,I,T,R) \in \mathbb{R}^6_+:0 \leq N \leq \displaystyle\frac{\varLambda}{\mu}\bigg\}.
\end{equation*}
\end{proof}

\subsection{Analysis of Disease-Free Equilibrium $(\mathscr{E}_0)$, and Basic Reproduction Number $(\mathscr{R}_0)$}\label{sec_four}
The mathematical expression $\mathscr{E}_0$ represents for the disease-free equilibrium point (DFEP), where there are no diseases in the human population. To obtain the disease-free equilibrium point, take the derivatives in the model equation \(\left( \ref{eq:4.1} \right)\) to zero and evaluate it at $E = I = T = R = 0$. Then, we are left with susceptible and vaccinated individuals from the model equation \(\left( \ref{eq:4.1} \right)\).
%
\begin{equation}
\label{eq:5.1}
\left\{
\begin{aligned}
\frac{dS}{dt} &= \Lambda + \eta R + \theta V - (\beta I + \pi + \mu)S \\
\frac{dV}{dt} &= \pi S - (\theta + \mu)V .
\end{aligned}
\right.
\end{equation} 
%
Thus, the disease-free equilibrium point (DFEP), which is given by
\begin{equation*}
\mathscr{E}_0 = \left( \displaystyle\frac{\varLambda(\theta + \mu)}{\mu(\theta + \pi + \mu)}, \frac{\varLambda\pi}{\mu(\theta + \pi + \mu)}, 0, 0, 0, 0 \right)
\end{equation*}

\subsubsection{Basic Reproductive Number}
The average number of secondary infections caused by a single infectious individual in a population that is completely susceptible during the mean infectious period is known as the basic reproduction number, denoted by $\mathscr{R}_0$ \cite{heffernan2005perspectives}.To obtain it, considering the model equations containing the infected compartments in general, i.e., $E$, $I$, and $T$, as shown in equation \eqref{eq:3} below, we used the next generation matrix method \cite{van2002reproduction}. 
\begin{equation}
\label{eq:3}
\left\{
\begin{aligned}
\frac{dE}{dt} &= \beta SI - (\gamma + \mu)E \\
\frac{dI}{dt} &= \gamma E  -(\delta +\tau + \mu)I \\
\frac{dT}{dt} &= \delta I  -(\alpha +\omega + \mu)T \\
\end{aligned}
\right.
\end{equation}
%
Splitting the right-hand side of equation \eqref{eq:3} as $\mathscr{F}-\mathscr{V}$, where $\mathscr{F}$ is the matrix of the new infection terms and $\mathscr{V}$ is the matrix of the transition terms in compartments $E ,I~ \& ~T$. Now, computing the Jacobian matrix $\mathscr{F}$ and $\mathscr{V}$ with respect to $E, I\ \&\ T$ and evaluating them at the disease-free equilibrium point (DFEP), $\mathscr{E}_0$, gives
%
\begin{center}
$F=\begin{bmatrix}
0 & \quad\displaystyle\frac{\varLambda\beta(\theta + \mu)}{\mu(\theta + \pi + \mu)}&\quad0 \\ 
0 & 0 &\quad 0\\
0 & 0 &\quad 0  
\end{bmatrix}$
\quad and \quad 
$V=\begin{bmatrix}
(\gamma + \mu) & 0& 0  \\
-\gamma & (\delta + \tau + \mu)&  0 \\
0 & - \delta&  (\alpha+\omega+\mu) 
\end{bmatrix}$.
\end{center}
%
Hence, following \cite{van2002reproduction}, the reproduction number of the model in equation \eqref{eq:4.1}, defined as the highest eigenvalue of $FV^{-1}$ given by $\mathscr{R}_0 = \rho(FV^{-1})$, is obtained as
%
\begin{equation}\label{eq.effective}
\mathscr{R}_v = \frac{\varLambda \beta \gamma (\theta + \mu)}{\mu (\delta + \tau + \mu)(\theta + \pi + \mu)(\gamma + \mu)}
\end{equation}
%
The threshold quantity $\mathscr{R}_V$ given in \ref{eq.effective} is known as the effective reproduction number, also called the control reproduction number. It calculates the typical number of new secondary infections that one infected person can spread over the course of an infection in a population that is totally vulnerable even with control measures in place \cite{ojo2023mathematical}. In this way, the number $\mathscr{R}_v$ in \ref{eq.effective} shows how many new TB cases one infected person is likely to cause in a population that is completely susceptible and has a vaccination program. A similar threshold quantity identified as the basic reproduction number can be obtained by setting the control measure and its parameters to zero (i.e., $\theta = \pi = 0$), such that 
%
\begin{equation}\label{eq.basic}
\mathscr{R}_0 = \frac{\varLambda \beta \gamma}{\mu (\delta + \tau + \mu)(\gamma + \mu)}
\end{equation}
%
Notably, the basic reproduction number $\mathscr{R}_0$ measures the average number of secondary cases produced by a single infected individual in a population that is completely susceptible, in a population without any control measure (see, for example, \cite{sulayman2021sveire}, \cite{ojo2023mathematical}).

\subsection{Stability Analysis}\label{sec_five}
Stability analysis can predict the long-term behavior of the model solution. We employ two types of stability analysis: local and global stability. Local stability is concerned with the behavior of the solution near the equilibrium points, whereas global stability can describe the behavior of the solution in the whole domain.

\subsubsection{Local Stability of the Disease-Free Equilibrium Point}
The DFEP $(\mathscr{E}_0)$ is said to be locally asymptotically stable if the real parts of the eigenvalue are all negative and unstable if at least one of the real parts of the eigenvalue is positive. If $\mathscr{R}_v< 1$, then the disease-free equilibrium point is locally asymptotically stable, i.e., no tuberculosis epidemic can develop in the population. If $\mathscr{R}_v> 1$, then the disease-free equilibrium point is unstable.

\begin{theorem}
The disease-free equilibrium point for model equation \eqref{eq:4.1} is locally asymptotically stable if $\mathscr{R}_v< 1$ and unstable if $\mathscr{R}_v> 1$.
\end{theorem}
%
\begin{proof}
The Jacobian matrix of the model equation \eqref{eq:4.1} at the disease free equilibrium point $\mathscr{E}_0$ is given by 
$$J(\mathscr{E}_0)=\begin{bmatrix} -(\pi + \mu) & \theta &  0 & \frac{-\varLambda \beta(\theta + \mu)}{\mu(\theta + \pi + \mu)} & 0 &  \eta\\ 
\pi &  -(\theta + \mu) &  0 &\quad  0 &  0 & 0\\ 
0  &  0 &  -(\gamma + \mu) &   \frac{\varLambda \beta(\theta + \mu)}{\mu(\theta + \pi + \mu)} &  0 & 0\\  
0 &  0 &  \gamma &  -(\delta + \tau + \mu) & 0 &  0\\ 
0 &  0 &  0 &  \delta &  -(\alpha + \omega + \mu) & 0\\
0 &  0 &  0 & 0 &  \alpha & -(\eta + \mu)\\ 
\end{bmatrix}.$$ 

The eigenvalues of $J(\mathscr{E}_0)$ can be obtained from $|J(\mathscr{E}_0) - \lambda I_6| = 0$, where $I_6$ is the identity matrix of order 6. Then we have

\begin{flalign}\label{eq.jacobian}
\begin{bmatrix} 
-(\pi\! +\! \mu\! +\! \lambda) & \theta &  0 & \frac{-\varLambda \beta(\theta\! +\! \mu\! +\! \lambda)}{\mu(\theta\! +\! \pi\! +\! \mu)} & 0 &  \eta\\
\pi &  -(\theta\! +\! \mu\! +\! \lambda) &  0 &\quad  0 &  0 & 0\\ 
0  &  0 &  -(\gamma\! +\! \mu\! +\! \lambda) &   \frac{\varLambda \beta(\theta\! +\! \mu)}{\mu(\theta\! +\! \pi\! +\! \mu)} &  0 & 0\\  
0 &  0 &  \gamma &  -(\delta\! +\! \tau\! +\! \mu \!+\! \lambda) & 0 &  0\\ 
0 &  0 &  0 &  \delta &  -(\alpha\! +\! \omega\! +\! \mu\! +\! \lambda) & 0\\
0 &  0 &  0 & 0 &  \alpha & -(\eta\! +\! \mu\! +\! \lambda)\\ 
\end{bmatrix}\!=\!0
\end{flalign}

From the matrix in Equation \eqref{eq.jacobian}, we obtain the characteristic equation given by
\begin{equation*}
\big[(\pi +\mu + \lambda)(\theta + \mu +\lambda) - \theta\pi\big]\big[(\eta+ \mu+ \lambda)(\alpha + \omega + \mu +\lambda)\big] \bigg[(\gamma +\mu + \lambda)(\delta + \tau + \mu + \lambda)-\displaystyle\frac{\varLambda \beta\gamma(\theta + \mu)}{\mu(\theta + \pi + \mu)}\bigg] = 0.
\end{equation*}
Obviously, $\lambda_1$, $\lambda_2$, $\lambda_3$, and $\lambda_4$ are negative, and for stability, all the real parts of the eigenvalues must be negative, which means 
\begin{equation*}
(\gamma +\mu)(\delta + \tau + \mu)-\displaystyle\frac{\varLambda \beta\gamma(\theta + \mu)}{\mu(\theta + \pi + \mu)} < 0 \Longrightarrow  \frac{\varLambda \beta\gamma(\theta + \mu)}{\mu(\theta + \pi + \mu)(\gamma +\mu)(\delta + \tau + \mu)} < 1.
\end{equation*}
Hence, $\displaystyle\mathscr{R}_v < 1$, and therefore, the disease-free equilibrium point $\mathscr{E}_0$ is locally asymptotically stable if $\mathscr{R}_v<1$.
\end{proof}
%

\subsubsection{Global Stability of the Disease-Free Equilibrium Point}
This section examines the global stability of the equilibrium points of the ordinary differential equation (ODE) in \eqref{eq:4.1}. We analyzed the global stability of the disease-free equilibrium point via the Castillo-Chavez approach \citep{castillo2002mathematical}. The Castillo-Chavez approach claims globally asymptotic stability of the disease-free equilibrium point if two specific conditions (specified below) are met when $\mathscr{R}_v < 1$. First, Equation \eqref{eq:4.1} can be restated in the following manner:
%
\begin{equation}\label{eq.global1}
\begin{cases}
\frac{dX}{dt} = F(X,Z) \\
\frac{dZ}{dt} = G(X,Z); \quad G(X,0) = 0
\end{cases}
\end{equation}
%
where $X =(S, V, R) \in \mathbb{R}^3_+$ represents the class of uninfected individuals and where $Z = (E, I, T)\in \mathbb{R}^3_+$ represents the class of infected individuals. Thus, $\mathscr{E}_0 = (x^*, 0)$ denotes the disease-free equilibrium of the system in equation \ref{eq.global1}. The specific conditions, I and II, are defined below and must be satisfied to guarantee local asymptotic stability:
\begin{itemize}
\item [\textbf{I}.] For $\frac{dX}{dt} = F(X, 0), \mathscr{E}_0$ is globally asymptotically stable.
\item [\textbf{II}.] $G(X, Z) = AZ - \hat{G}(X, Z),  \hat{G}(X, Z) \geq 0$ for all $(X , Z)$ $\in \mathbb{R} $, where $A = D_Z G(\mathscr{E}_0)$ is an M-matrix (the off-diagonal elements $A$ are nonnegative) and $\mathbb{R}$ is the region where the model makes biological sense. If System \ref{eq.global1} satisfies the above two conditions, then the following theorem holds \cite{castillo2002mathematical}:
\end{itemize}

\begin{theorem}[\textbf{Castillo-Chavez Theorem}]\label{CC}
The fixed point $\mathscr{E}_0 = (x^*, 0)$ is a globally asymptotic stable equilibrium of \ref{eq.global1}, provided that $\mathscr{R}_0<1$ under assumptions I and II are satisfied.
\end{theorem}

Now, an application of theorem \ref{CC} for System \eqref{eq:4.1} yields:
\begin{equation*}
X =(S, V, R)^T \in \mathbb{R}^3_+, Z = (E, I,  T)^T\in \mathbb{R}^3_+, \mathscr{E}_0 = (x^*, 0) = (S_0, V_0, 0).
\end{equation*}
As $t\rightarrow\infty$,\ $(S(t), V(t), R(t)) \rightarrow$ $(\frac{\Lambda(\theta + \mu)}{\mu(\theta + \pi + \mu)}$, $ \frac{\Lambda\pi}{\mu(\theta + \pi + \mu)}, 0) = \mathscr{E}_0 = (x^*, 0)$ is globally asymptotically stable. Moreover,

\begin{center}
$A= \begin{pmatrix}  
-(\gamma + \mu) &\frac{\Lambda\beta(\theta + \mu)}{\mu(\theta + \pi + \mu)} & 0 \\ 
\gamma & -(\delta + \tau + \mu) & 0 \\
0 & \delta & -(\alpha + \omega + \mu)
\end{pmatrix}\quad\&\quad \hat{G}(X, Z) = \begin{pmatrix}  
\beta I[S_0-S] \\ 
0 \\
0
\end{pmatrix}$	
\end{center}

For System \eqref{eq:4.1}, $S_0=\frac{\Lambda(\theta+\mu)}{\mu(\theta+\pi+\mu)}$, since $\frac{\Lambda}{\mu}$ represents the upper bound of the total population. Hence, $S_0 > S$, which leads to $\hat{G}(X, Z) \geq 0$ for all $(X,Z) \in \mathbb{R}^6_+$. Thus, the assumptions, \textbf{I} and \textbf{II}, of the Castillo-Chavez theorem are satisfied for System \eqref{eq:4.1}, hence, the theorem follows.

\subsection{Endemic Equilibrium Point $(\mathscr{E}^*)$, and Sensitivity Analysis}\label{sec_six}
The endemic equilibrium point (EEP) $\mathscr{E^*}=(S^*, V^*, E^*, I^*, T^*, R^*)$ is the point at which the disease remains alive in the population when at least one of the infected classes of the model is nonzero. To obtain the endemic equilibrium point, we equate all expressions of model equations \(\left( \ref{eq:4.1} \right)\) of the derivative to zero. From the system of equations \(\left( \ref{eq:4.1} \right)\), we get the following simplified endemic equilibrium point:
 \begin{align*}
S^* &= \frac{\varLambda(\theta + \mu)}{ \mu(\theta + \tau + \mu)\mathscr R_0},~ V^* = \frac{\varLambda\pi}{\mu(\theta + \pi + \mu)\mathscr R_0} \\
E^* &= \frac{\mu(\eta + \mu)(\alpha +\omega +\mu)(\gamma + \mu)(\theta + \pi +\mu)(\delta + \tau + \mu)^2(\mathscr{R}_0 -1)}{\beta\gamma(\theta + \mu)[(\delta + \tau + \mu)(\alpha + \omega + \mu)(\gamma + \mu)(\eta + \mu) - \eta\delta\gamma\alpha]},\\ 
I^* &= \frac{\mu(\eta + \mu)(\alpha +\omega +\mu)(\delta + \tau + \mu)(\gamma + \mu)(\theta + \pi +\mu)(\mathscr{R}_0 -1)}{\beta(\theta + \mu)[(\delta + \tau + \mu)(\alpha + \omega + \mu)(\gamma + \mu)(\eta + \mu) - \eta\delta\gamma\alpha]}, \\
T^* &= \frac{\delta\mu(\eta + \mu)(\delta + \tau + \mu)(\gamma + \mu)(\theta + \pi +\mu)(\mathscr{R}_0 -1)}{\beta(\theta + \mu)[(\delta + \tau + \mu)(\alpha + \omega + \mu)(\gamma + \mu)(\eta + \mu) - \eta\delta\gamma\alpha]},~ \text{and}\\ 
R^* &= \frac{\alpha\delta\mu(\delta + \tau + \mu)(\gamma + \mu)(\theta + \pi +\mu)(\mathscr{R}_0 -1)}{\beta(\theta + \mu)[(\delta + \tau + \mu)(\alpha + \omega + \mu)(\gamma + \mu)(\eta + \mu) - \eta\delta\gamma\alpha]}.
\end{align*}

\subsubsection{Local Stability of the Endemic Equilibrium Point}
\begin{theorem}
The endemic equilibrium point of the system of equations in  \eqref{eq:4.1} is locally asymptotically stable if $\mathscr{R}_0>1$ and unstable if $\mathscr{R}_0<1$.
\end{theorem}
\begin{proof}
The stability of the endemic equilibrium point is then determined on the bases of the sign of the eigenvalues of the Jacobian matrix obtained as: 
$$J(\mathscr{E^*})=\begin{bmatrix}
-( \beta I^* +\pi + \mu) & \theta & 0 & -\beta S^*& 0& \eta\\ 
\pi & -(\theta + \mu) & 0 & 0 & 0&0\\ 
\beta I^* & 0 & -(\gamma + \mu) &  \beta S^* & 0&0\\  
0 & 0 & \gamma & -(\delta + \tau + \mu) & 0&0\\ 
0 & 0 & 0 & \delta & -(\alpha + \omega + \mu)&0\\
0 & 0 & 0 & 0 &\alpha&-(\eta + \mu)
\end{bmatrix}.$$
To find the eigenvalues, we have
\begin{equation}\label{eq.locstable1}
|J (\mathscr{E^*}) - \lambda I_6|  = 0
\end{equation}
Let	$a = (\beta I^* + \pi + \mu), b = \beta I^*,  c = (\theta + \mu),  d = (\gamma + \mu), e = \beta S^*, f = (\delta + \tau + \mu), g = (\eta +\mu)$ and $h = (\alpha + \omega + \mu)$. Then the characteristic polynomial representation of equation \eqref{eq.locstable1} is given by:
\begin{equation*}
a_6 \lambda^6 + a_5\lambda^5 + a_4\lambda^4 + a_3\lambda^3 + a_2\lambda^2 + a_1\lambda^1 + a_0\lambda^0 = 0
\end{equation*}
 where
\begin{align*}
a_0 &= acdfgh + egh\pi\theta\gamma - acegh\gamma - bcegh\gamma - dfgh\pi\theta - bc\alpha\eta\gamma\delta,\\
a_1 &= acfgh + acdfg + acdfh + adfgh +cdfgh + acdgh + eg\pi\theta\gamma + eh\pi\theta\gamma - aceg\gamma - aceh\gamma- aegh\gamma - cegh\gamma -\\ 
& dfg\pi\theta - dfh\pi\theta - dgh\pi\theta - bceg\gamma - bceh\gamma - begh\gamma - fh\pi\theta - b\alpha\gamma\eta\delta, \\
a_2 &=acfg + acfh + afgh + cfgh + acgh + acdf + adfg + adfh + cdfg + cdfh + acdg + acdh + adgh + cdgh + \\ 
& e\pi\theta\gamma - ace\gamma - aeg\gamma - aeh\gamma - ceg\gamma - ceh\gamma- egh\gamma- bce\gamma -beg\gamma - beh\gamma - df\pi\theta - dg\pi\theta - dh\pi\theta - \\ 
& fg\pi\theta - fh\pi\theta - gh\pi\theta, \\
a_3 &= acf + afg + afh + cfg  + cfh + fgh + acg + ach + agh + cgh + adf + dfh + acd + adg + adh + cdg + cdh + \\ 
& dgh - ae\gamma - ce\gamma -be\gamma - eg\gamma- eh\gamma - eg\gamma - d\pi \theta - f\pi\theta - g\pi\theta - h\pi\theta, \\
a_4 &= af+ cf + fg + fh + ac + ag + ah +cg +ch +gh + df + ad + cd + dg +dh - e\gamma - \pi\theta,\\
a_5 &= (a + c + d + f + g +h),~ \text{and}~ a_6 = 1.
\end{align*}
After substitution and simplification by the Routh-Hurwitz stability criterion \citep{rcet}, the endemic equilibrium point $\mathscr{E}^*$ is locally asymptotically stable if $\mathscr{R}_0>1$.
\end{proof}

\subsubsection{Global Stability of Endemic Equilibrium Point}
\begin{theorem}
If $\mathscr{R}_0>1$, the endemic equilibrium $\mathscr{E}^*$ of the system of equations in  \eqref{eq:4.1} is globally asymptotically stable, whereas if $\mathscr{R}_0<1$, it is unstable.
\end{theorem}
\begin{proof}
To prove the global asymptotic stability at the endemic equilibrium point, we use the Lyapunov function $\mathcal{V}$ \cite{shuai2013global}, which is defined and derived as follows:: 
%
\begin{align*}
\mathcal{V}(S^*, V^*, E^*, I^*, T^*, R^*) &= \bigg(S - S^* - S^*\displaystyle\ln \frac{S^*}{S}\bigg) + \bigg(V - V^* - V^*\displaystyle\ln \frac{V^*}{V}\bigg) + \bigg(E - E^* - E^*\displaystyle\ln \frac{E^*}{E}\bigg) +\\  
& \bigg(I - I^* - I^*\displaystyle\ln \frac{I^*}{I}\bigg) + \bigg(T - T^* - T^*\displaystyle\ln \frac{T^*}{T}\bigg) + \bigg(R - R^* - R^*\displaystyle\ln \frac{R^*}{R}\bigg).
\end{align*}
%
By calculating the derivatives $\mathcal{V}(S^*, V^*, E^*, I^*, T^*, R^*)$ with respect to $t$, we obtain
\begin{align*}
\displaystyle\frac{d\mathcal{V}}{dt} &= \bigg(\displaystyle\frac{S-S^*}{S}\bigg)\displaystyle\frac{dS}{dt} +  \bigg(\displaystyle\frac{V - V^*}{V}\bigg)\displaystyle\frac{dV}{dt} +  \bigg(\displaystyle\frac{E - E^*}{E}\bigg)\frac{dE}{dt} + \\
& \bigg(\displaystyle\frac{I - I^*}{I}\bigg)\displaystyle\frac{dI}{dt} +  \bigg(\displaystyle\frac{T - T^*}{T}\bigg)\displaystyle\frac{dT}{dt} + \bigg(\displaystyle\frac{R - R^*}{R}\bigg)\displaystyle\frac{dR}{dt}	
\end{align*}
By direct substitution of the model equation \ref{eq:4.1}, we have
\begin{align*}
\displaystyle\frac{d\mathcal{V}}{dt} &= \bigg(\displaystyle\frac{S-S^*)}{S}\bigg)(\Lambda + \eta R + \theta V- (\beta I + \pi + \mu)S) + \bigg(\displaystyle\frac{V- V^*}{V}\bigg)(\pi S - (\theta + \mu)V) +\\
& \bigg(\displaystyle\frac{E-E^*}{E}\bigg)(\beta SI - (\gamma + \mu)E) +\bigg(\displaystyle\frac{I-I^*}{I}\bigg)(\gamma E -(\delta +\tau + \mu)I) +\\
& \bigg(\displaystyle\frac{T-T^*}{T}\bigg)(\delta I -(\alpha + \omega +\mu)T) +\bigg(\displaystyle\frac{R-R^*}{R}\bigg)(\alpha T - (\eta + \mu)R).
\end{align*}
Then by simplifying the above equation, we have
\begin{align*}
\displaystyle\frac{d\mathcal{V}}{dt} &= \Lambda + \beta IS^* + \pi S^* + \mu S^* + \theta V^* + \mu V^* + \gamma E^* + \mu E^* +\delta I^* +\tau I^* + \mu I^* + \alpha T^* + \\
& \omega T^* + \mu T^* + \eta R^* + \mu R^* - \mu S - \Lambda\displaystyle\frac{S^*}{S} - \eta R\frac{S^*}{S} - \theta V\frac{S^*}{S} - \mu V -\pi S\frac{V^*}{V}  - \mu E - \\
& \beta SI \displaystyle\frac{E^*}{E}- \tau I - \mu I - \gamma E \displaystyle\frac{I^*}{I} -\omega T -\mu T - \delta I \frac{T^*}{T}- \mu R - \delta I\frac{R^*}{R}.
\end{align*}
Now, let us take $X$ as the positive term and $Y$ as the negative term of the equation above such that
$$\displaystyle\frac{dV}{dt} = X - Y.$$
Thus, if $X < Y$, then $\displaystyle\frac{d\mathcal{V}}{dt}< 0$; note that $S = S^*, V = V^*, E = E^*, I = I^*, T = T^*, R = R^*$ if and only if  $\frac{d\mathcal{V}}{dt}= 0$. Therefore, Lasalle’s invariant principle \cite{lasalle1960some} indicates that the endemic equilibrium $\mathscr{E^*}$ is globally asymptotically stable if $X < Y$.
\end{proof}

\subsection{Sensitivity Analysis}
We aim to ascertain the sensitivity of each parameter to the effective reproduction number of the model. We apply the following sensitivity index formula:
\begin{equation}\label{eq.SA_1}
\displaystyle\varUpsilon^{\mathscr{R}_v}_{mi} = \displaystyle\frac{\partial \mathscr{R}_v }{\partial mi} \times \displaystyle\frac{mi}{\mathscr{R}_0}	
\end{equation}
where $mi$ are the system’s parameters in the quantity $\mathscr{R}_v$. We recall that the effective reproduction number $\mathscr{R}_v$ is given by:
\begin{equation}\label{basic_repro}
\mathscr{R}_v = \displaystyle\frac{\varLambda \beta \gamma(\theta + \mu)}{\mu(\theta + \pi + \mu)(\delta + \tau + \mu)(\gamma + \mu)}.
\end{equation}
Then, via Equation \eqref{basic_repro}, direct computation yields

\begin{align*}
\displaystyle \varUpsilon^{\mathscr{R}_v}_{\varLambda} &= 1 > 0,~\displaystyle \varUpsilon^{\mathscr{R}_v}_{\beta}  = 1 > 0,~ \displaystyle\varUpsilon^{\mathscr{R}_v}_{\gamma} = \displaystyle\frac{\mu}{(\gamma + \mu)}  > 0,~
\displaystyle\varUpsilon^{\mathscr{R}_v}_{\theta} = \displaystyle\frac{\pi}{(\theta + \pi + \mu)(\theta + \mu)}  > 0,\\
\displaystyle \varUpsilon^{\mathscr{R}_v}_{\mu} &= -[\displaystyle\frac{\theta}{(\theta + \mu)} + \frac{\mu}{(\theta + \pi + \mu)} + \frac{\mu}{(\delta + \tau + \mu)} + \frac{\mu}{(\gamma + \mu)}] < 0,\\
\displaystyle\varUpsilon^{\mathscr{R}_v}_{\pi} &=  \displaystyle\frac{-\pi}{(\theta + \pi + \mu)} < 0,~
\displaystyle\varUpsilon^{\mathscr{R}_v}_{\delta} = \displaystyle\frac{-\delta}{(\delta + \tau + \mu)} < 0,~\text{and}~
\displaystyle\varUpsilon^{\mathscr{R}_0}_{\tau} = \displaystyle\frac{-\tau}{(\delta + \tau + \mu)} < 0.
\end{align*}

We use sensitivity analysis to explain how our reproduction number should be interpreted. Parameters with negative sensitivity indices $(\mu, \pi, \delta, \tau )$ have the effect of lowering the community's TB burden if their values increases (i.e., the disease's reproduction number decreases as its parameter values increase). Additionally, if the values of those parameters with positive sensitivity indices $(\Lambda, \beta, \gamma, \theta)$ increase, they play a large part in the spread of tuberculosis in the community. This means that if the values of those parameters increase, so does secondary infection in the community. Therefore, it is essential to increase the negative indices and decrease the positive indices to reduce the disease incidence in the community. Since increasing the human mortality rate to contain disease epidemics is unethical, we do not take this into consideration when studying sensitivity. 

However, many of these studies have either relied on data from countries with more robust health infrastructures or have focused on theoretical applications rather than incorporating region-specific epidemiological data. 

\section{Parameter Estimation}\label{sec_seven}
The SVEITRS model is an extension of the SEIR model, that is specifically tailored to tuberculosis dynamics, and it has several compartments that represent different stages of the disease and different types of interventions. To accurately reflect and capture the transitions of individuals between different disease states, incorporating region-specific epidemiological data is crucial during model parameter estimation. A significant gap in the current literature is the use of locally relevant temporal data to estimate model parameters accurately, with particular emphasis on the choice of estimation techniques. Hence, to accomplish these goals, we use a nonlinear least squares method by implementing minimum search algorithms (gradient descent) and maximum likelihood estimation (MLE) to estimate parameters. We employ these methods to estimate relevant parameters for our model on a synthetic example case and assess the performance and validity of our model via real tuberculosis data from Ethiopia from 2011-2021.

The systems of ODEs in Equation \ref{eq:4.1} can be expressed in more general form as:
\begin{equation}\label{par.eq}
\Dot{\mathbf{x}}(t) = f(\mathbf{x}(t),\theta), ~~ \mathbf{x}(t_0) = \mathbf{x}_0
\end{equation}
where $\mathbf{x}(t) = \big[S(t), V(t), E(t), I(t), T(t), R(t)\big]^t$ and $\mathbf{x}_0 = \mathbf{x}(0)$ are 6-dimensional state vectors and constant initial states, respectively; $\boldsymbol{\theta} = \big[\varLambda, \beta, \gamma, \nu, \pi, \eta, \theta, \delta, \sigma, \tau, \alpha, \omega\big]^t$ is a 12-dimensional vector of the model parameters, and $f : \Omega\subset \mathbb{R}^6\times\mathbb{R}^9\rightarrow\mathbb{R}^6$ is a continuous map, which is described on the open set
\begin{equation}\label{par.eq1}
\Omega = \big\{ (\mathbf{x}(t),\boldsymbol{\theta})\in\mathbb{R}^6\times\mathbb{R}^9|\mathbf{x}_n(t),~\boldsymbol{\theta}_m>0~ \text{for}~ n = 1,\cdots,6~ \text{and}~ m=1,\cdots, 12\big\}.
\end{equation}

The above notation for the SVEITRS models has been used in to illustrate the basic setup of the parameter estimation problem. If we have given the initial conditions $\mathbf{x}_0$ and a set of parameters $\boldsymbol{\theta}$, we can compute the state vectors $\mathbf{x}(t)$ of the model given in Equation \ref{par.eq}. In other words, if we have been given a set of observed data $\mathbf{y}(t), t = 1,\cdots, T$, we try to estimate parameters $\boldsymbol{\theta}$, and then the state vector $\mathbf{x}(t)$ for all $t$ can make predictions for $\mathbf{y}(t)$ for $t > T$. In the following subsection, we describe the two parameter estimation approaches, nonlinear least squares and maximum likelihood estimation, that we use in this study.

\subsection{Nonlinear least squares}
The nonlinear least squares method (NLS) is used to numerically approximate a solution of the model Equation \ref{par.eq1} and observations within the least-squares fitting, where we look for the $\hat{\boldsymbol{\theta}}$ value of the model parameter $\boldsymbol{\theta}$, which minimizes the least squares criterion
\begin{equation}\label{par.eq2}
J(\boldsymbol{\theta}) = \sum_{t=1}^{T} ||\mathbf{y}(t) - f(\mathbf{x}(t),\boldsymbol{\theta})||^2,
\end{equation}
where $f(\cdot)$ is the output of the model for a given set of parameters and where $\boldsymbol{\theta}$ and $\mathbf{y(t)}$ are the observable outputs. The function $J(\boldsymbol{\theta})$ measures the difference between observed data and model predictions, typically using the sum of squared errors. This problem can be classified as a nonlinear least-squares problem because the relationship between the solution system and the parameter $\boldsymbol{\theta}$ is based on a complex system of nonlinear differential equations.

\subsection{Maximum likelihood estimation}
Maximum likelihood estimation (MLE) is a statistical method used to estimate the parameters of a model by maximizing the likelihood function. This technique finds the parameter values that make the observed data most likely, offering a robust approach for parameter estimation in complex models. It is particularly useful in cases where the data are subject to significant variability. The likelihood function is
\begin{equation}\label{par.eq3}
L(\boldsymbol{\theta}) = p(\mathbf{y}|\boldsymbol{\theta})
\end{equation}

For a given set of observations $\mathbf{y}$, the likelihood function is defined as the joint probability of the observed data, given the parameters. This means that we assume that there is some uncertainty in the observed data $\mathbf{y}(t)$ and that the only thing we know about those errors is that they are centered (zero mean) and identically and independently distributed with constant variance; then the likelihood function for the SVEITRS model can be expressed as
\begin{equation}\label{par.eq4}
p(\mathbf{y}|\boldsymbol{\theta}) \propto \exp\left(-\frac{1}{2\sigma_y^2}J(\boldsymbol{\theta})\right) 
\end{equation}
where $\sigma^2_y$ is a fixed variance that can be estimated together with the parameters. The log-likelihood function, $\log L(\boldsymbol{\theta})$, is often used instead of the likelihood function because it simplifies the computations. Maximizing the log-likelihood function is equivalent to minimizing the negative log-likelihood function, and then the optimization problem for MLE can be formulated as:
\begin{equation}\label{par.eq5}
\hat{\boldsymbol{\theta}} = \arg\max_{\boldsymbol{\theta}}\left( p(\mathbf{y}|\boldsymbol{\theta})\right) = \arg\min_{\boldsymbol{\theta}}\left( -\ln{p(\mathbf{y}|\boldsymbol{\theta})}\right)
\end{equation}

