\section{Wilson and Sommerfeld Quantization Rules in Wave Mechanics\/}

{\scshape{Topics to review\/:}} 
Kepler problems in classical mechanics \cite{Biedenharn1983}, \cite[pp.~146--148]{Gantmacher}, \cite[pp.~92--102, pp.~466--477, pp.~481--482]{Goldstein}, \cite[pp.~84--90, pp.~109--119, pp.~251--258]{SomAS};
spherical harmonics \cite{EEKS-SKS, La:Lif, Ni:Uv, Varshalovich1988};
Schr\"{o}dinger equation \cite{Dav, La:Lif, MerzB, Schiff}, relativistic Schr\"{o}dinger 
and Dirac equations \cite{AkhBer, Barleyetal2021, BerLifPit, Dav, Schiff, Sus:Vega:Barl};
the spinor spherical harmonics \cite{AkhBer, BerLifPit, Rose, Sus:Trey2008, Sus:Vega:Barl, Varshalovich1988} 
and separation of variables for the Dirac equation in a central field; 
semiclassical approximation \cite{BerryMount-SKS, Ghatetal, Ni:Uv, Schiff}.

{\scshape{Brief history\/:}} As an extension of Bohr's rules, Wilson \cite{Wilson} and Sommerfeld \cite{Somm1916} 
independently proposed a method of quantizing action integrals in classical mechanics 
for a multi-dimensional periodic system over one period of motion (see also \cite[footnote on p.~111]{SomAS}).
%

\subsection{Sommerfeld fine structure formula}

We follow \cite{Biedenharn1983} and \cite[pp.~251--258]{SomAS} with somewhat different details.
%
The classical relativistic Hamiltonian, or the total energy $E\/$ of hydrogen-like systems, for an
attractive Coulomb potential, has the quadratic form:%
\begin{equation}
\left( E+\frac{Ze^{2}}{r}\right) ^{2}=\mathbf{p}^{2}c^{2}+m^{2}c^{4}.
\label{BidSom1}
\end{equation}%
In polar coordinates,%
\begin{equation}
\mathbf{p}^{2}=\left( p_{r}\right) ^{2}+\frac{1}{r^2}\left( p_{\theta }\right)
^{2},  \label{BidSom2}
\end{equation}%
with $p_{r}=\gamma m\overset{\cdot}{r}=$ $\gamma m\ (dr/dt)$ (radial momentum) and 
$p_{\theta }=\gamma mr^{2}\overset{\cdot}{\theta }=\gamma mr^{2}\ (d\theta /dt)$
(angular momentum). [In the relativistic case, $\gamma =\left(
1-v^{2}/c^{2}\right) ^{-1/2} {\textrm{is the familiar Lorentz factor}}.]$

Due to angular momentum conservation, $p_{\theta }$ is a constant. Introduce
the new variable $s=1/r$ and note that%
\begin{equation}
\frac{ds}{d\theta }=-\frac{p_{r}}{p_{\theta }}.  \label{BidSom3}
\end{equation}%
In this notation, Eq.~(\ref{BidSom1}) becomes%
\begin{equation}
\left( \frac{E}{mc^{2}}+\frac{Ze^{2}}{mc^{2}}\, s\right)^{2}=1+\left( \frac{%
p_{\theta }}{mc}\right) ^{2}\left[ \left( \frac{ds}{d\theta }\right)
^{2}+s^{2}\right] .  \label{BidSom4}
\end{equation}%
Differentiation with respect to $\theta $ results in the linear
ordinary differential equation:%
\begin{equation}
\frac{d^{2}s}{d\theta ^{2}}+\omega ^{2}\left( s-D\right) =0.  \label{BidSom5}
\end{equation}%
Here, by definition%
\begin{equation}
\omega ^{2}=1-\frac{Z^{2}e^{4}}{c^{2}p_{\theta }^{2}},\qquad D=\frac{Ze^{2}E%
}{\omega ^{2}c^{2}p_{\theta }^{2}}.  \label{BidSom6}
\end{equation}

Solving (\ref{BidSom5}), one obtains the relativistic Kepler orbits as
follows%
\begin{equation}
s=\frac{1}{r}=C_{1}\cos \left( \omega \theta \right) +C_{2}\sin \left(
\omega \theta \right) +D,  \label{BidSom7}
\end{equation}%
where $C_{1}$ and $C_{2}$ are constants. If the distance of closest approach
(perihelion) occures at $\theta =0,$ then $C_{2}=0$ and%
\begin{equation}
\frac{1}{r}=C_{1}\cos \left( \omega \theta \right) +D.  \label{BidSom8}
\end{equation}

Classical relativistic Kepler orbits have the form of conic sections, as in
the non-relativistic case \cite{Biedenharn1983} and \cite[pp.~251--258]%
{SomAS}, but with the new angle variable $\phi =\omega \theta\/.$ Thus, for
the elliptic orbits (bound states), to move from perihelion ($\phi =0$) to
the next perihelion ($\phi =2\pi $) requires $\theta =2\pi /\omega \/$ and $\Delta\theta =2\pi /\omega - 2\pi\/$
per revolution (see Figure~\ref{FigureRelativistic}).
%

%%%%% Figure 3: Ellipses, Kepler's problem  %%%%%%
\begin{figure}[hbt!]
\centering
\includegraphics[width=0.5\textwidth]{relativistic_kepler_orbit.pdf}
\caption{Relativistic Kepler motion \cite[p.~254]{SomAS}\/. 
(Here $\textrm{O}$ is the fixed focus at which the nucleus is situated,
$\textrm{P}$ is the initial position of the perihelion.)
The perihelion and aphelion move in two concentric
circles round the nucleus at $\textrm{O}$\/.}
\label{FigureRelativistic}
\end{figure}

Introducing the eccentricity $\epsilon\/,$ for $\phi = 0\/,$ we have the perihelion
distance $r_{\textrm{min}}=a(1-\epsilon )$ and for $\phi =\pi\/,\,$ the aphelion distance $%
r_{\textrm{max}}=a(1+\epsilon ).$ In standard geometrical terms, the orbit equation states%
\begin{equation}
\frac{1}{r}=\frac{1+\epsilon \cos \left( \omega \theta \right) }{a\left(
1-\epsilon ^{2}\right) }.\label{BidSom9}
\end{equation}%
One can now apply the original Wilson--Sommerfeld quantization rules%
\begin{equation}
\int_{\theta =0}^{\theta =2\pi }p_{\theta }\ d\theta =h\ n_{\theta }\qquad
\left( \text{which gives }p_{\theta }=\hbar \ n_{\theta }\right) \label%
{BidSom10}
\end{equation}%
and%
\begin{equation}
\int_{\theta =0}^{\theta =2\pi/\omega }p_{r}\ dr=h\ n_{r}.\label{BidSom11}
\end{equation}

In order to evaluate the last integral, we may transform the radial momentum
as follows%
\begin{equation}
p_{r}=\gamma m\overset{\cdot}{r}=\gamma m\left( \frac{dr}{d\theta }\right) 
\overset{\cdot}{\theta }=\frac{p_{\theta }}{r^{2}}\left( \frac{dr}{d\theta }%
\right) .\label{BidSom12}
\end{equation}%
Thus%
\begin{equation}
p_{r}\ dr=p_{\theta }\left( \frac{1}{r}\frac{dr}{d\theta }\right) ^{2}\
d\theta =p_{\theta }\epsilon ^{2}\omega \frac{\sin ^{2}\phi }{\left(
1+\epsilon \cos \phi \right) ^{2}}\ d\phi \label{BidSom13}
\end{equation}%
upon using the orbit equation (\ref{BidSom9}). The radial quantization condition (%
\ref{BidSom11}) takes the form%
\begin{equation}
\frac{1}{2\pi }\int_{\phi =0}^{\phi =2\pi }\frac{\epsilon ^{2}\sin ^{2}\phi
~d\phi }{\left( 1+\epsilon \cos \phi \right) ^{2}}=\frac{n_{r}}{\omega
n_{\theta }}.\label{BidSom14}
\end{equation}%
For the integral evaluation,%
\begin{equation}
\frac{1}{2\pi }\int_{\phi =0}^{\phi =2\pi }\frac{\epsilon ^{2}\sin ^{2}\phi
~d\phi }{\left( 1+\epsilon \cos \phi \right) ^{2}}=\left( 1-\epsilon
^{2}\right) ^{-1/2}-1,\label{BidSom15}
\end{equation}%
see our complementary Mathematica notebook \cite{BarleySusMath}.

%
As a result, we obtain%
\begin{equation}
\frac{1}{1-\epsilon ^{2}}=\left( 1+\frac{n_{r}}{\omega n_{\theta }}\right)
^{2}\label{BidSom16}
\end{equation}%
and%
\begin{equation}
D=\frac{\alpha ZE}{n_{\theta }^{2}\omega ^{2}\hbar c}=\frac{1}{a\left(
1-\epsilon ^{2}\right) } \quad \left(\alpha =\frac{e^{2}}{\hbar c} \; {\textrm{is the fine structure constant}}\right).\label{BidSom17}
\end{equation}%
Finally, using the last two equations together with the orbit (\ref{BidSom9}) and energy (\ref{BidSom4})
equations, after tedious but straightforward calculations, one arrives at
the original Sommerfeld formula:%
%
\begin{equation}
\frac{E_{n_{r}, n_{\theta }}}{mc^{2}}=\left( 1+\frac{\alpha ^{2}Z^{2}}{\left(
n_{r}+\left( n_{\theta }^2-\alpha ^{2}Z^{2}\right) ^{1/2}\right) ^{2}}\right)
^{-1/2}
%\quad \left(\alpha =\frac{e^{2}}{\hbar c} \; {\textrm{is the fine structure constant}}\right)
,\label{BidSomEnd}
\end{equation}%
%
where $n_{r}\/,$ the {\textit{radial quantum number}\/,} and $n_{\theta \/,}$ the {\textit{azimuthal quantum number\/,}} are positive integers. This result made it possible to explain, for the first time, the fine structure of spectral lines.
(More details can be found in \cite{Biedenharn1983}, \cite[pp.~251--258]{SomAS}, and our Appendix~\ref{App:Appendixe}). 
%

%
\noindent {\textbf{Note.\/}}  Equations (\ref{BidSom6}), (\ref{BidSom10}), and (\ref{BidSom16})--(\ref{BidSomEnd}) allow us to determine the quantized values of parameters of the electron elliptic orbits (\ref{BidSom9}) as follows:%
%
\begin{eqnarray}
\omega _{n_{\theta }}n_{\theta } &=&\left( n_{\theta }^{2}-\alpha
^{2}Z^{2}\right) ^{1/2},  \label{BidSom18} \\
\epsilon _{n_{r},n_{\theta }} &=&\sqrt{n_{r}}\frac{{\left(n_{r}+2\sqrt{%
n_{\theta }^{2}-\alpha ^{2}Z^{2}}\right)^{1/2}}}{n_{r}+\sqrt{n_{\theta }^{2}-\alpha
^{2}Z^{2}}},  \label{BidSom19} \\
a_{n_{r},n_{\theta }} &=&\frac{a_{0}}{Z}\left( n_{r}+\sqrt{n_{\theta
}^{2}-\alpha ^{2}Z^{2}}\right)   \label{BidSom20} \\
&&\times \sqrt{\alpha ^{2}Z^{2}+\left( n_{r}+\sqrt{n_{\theta }^{2}-\alpha
^{2}Z^{2}}\right) ^{2}},  \notag
\end{eqnarray}%
%
where $a_{0}=\hbar ^{2}/(me)$ is the familiar Bohr radius. There formulas are extending the circular orbits (more details can be found in a complementary Mathematica notebook \cite{BarleySusMath} and Appendix~\ref{App:Appendixe}).%
%
\footnote{Classical solutions of the relativistic Kepler problem are also discussed in \cite[pp.~481--482]{Goldstein} and \cite[pp.~100--102]{LaLif2}.}
%

In the non-relativistic limit, one gets%
\begin{eqnarray}
\omega _{n_{\theta }} &=&1-\frac{\alpha ^{2}Z^{2}}{2n_{\theta }^{2}}-\frac{%
\alpha ^{4}Z^{4}}{8n_{\theta }^{4}}+\mathcal{O}\left( \alpha ^{6}\right) ,\label%
{BidSom21} \\
\epsilon _{n_{r},n_{\theta }} &=&\frac{\sqrt{n_{r}}\left( n_{r}+2n_{\theta
}\right) ^{1/2}}{n_{r}+n_{\theta }}+\frac{\sqrt{n_{r}}\alpha ^{2}Z^{2}}{%
2\left( n_{r}+n_{\theta }\right) ^{2}\left( n_{r}+2n_{\theta }\right) ^{1/2}}%
\label{BidSom22} \\
&&+\frac{\sqrt{n_{r}}\left( 3n_{r}+5n_{\theta }\right) \alpha ^{4}Z^{4}}{%
8n_{\theta }\left( n_{r}+n_{\theta }\right) ^{3}\left( n_{r}+2n_{\theta
}\right) ^{3/2}}+\mathcal{O}\left( \alpha ^{6}\right) ,  \notag \\
\dfrac{Z a_{n_{r},n_{\theta }}}{a_{0}} &=&\left( n_{r}+n_{\theta }\right) ^{2}-\frac{\alpha
^{2}Z^{2}\left( 2n_{r}+n_{\theta }\right) }{2n_{\theta }}\label{BidSom23} \\
&&-\frac{\alpha ^{4}Z^{4}}{8}\left( \frac{2n_{r}}{n_{\theta }^{3}}+\frac{1}{%
\left( n_{r}+n_{\theta }\right) ^{2}}\right) +\mathcal{O}\left( \alpha
^{6}\right) ,  \notag
\end{eqnarray}%
and%
%
\begin{equation}
\frac{E_{n_{r},n_{\theta }}}{mc^{2}}=1-\frac{\alpha ^{2}Z^{2}}{2\left(
n_{r}+n_{\theta }\right) ^{2}}-\frac{\alpha ^{4}Z^{4}\left( 4n_{r}+n_{\theta
}\right) }{8n_{\theta }\left( n_{r}+n_{\theta }\right) ^{4}}+\mathcal{O}\left(
\alpha ^{6}\right) ,\label{BidSom24}
\end{equation}%
where $\alpha =e^{2}/(\hbar c)$ and $%
c\rightarrow \infty $ (see our Mathematica file). [This asymptotic expansion will be analyzed below (\ref{lim3}).]
In this limit, we did recover Sommerfeld's elliptic orbits for hydrogen-like systems \cite[pp.~109--119]{SomAS} (see Figure~\ref{SommerfeldEllipses}).
As follows from (\ref{BidSom22}), Bohr's circular orbits occur only when $n_r=0\/.$ 

