\section*{Appendix A: Velocity, Acceleration and Angular Momentum for \newline
the Uniform Circular Motion\/}\label{App:Appendixa}

For a uniform circular motion one gets%
\begin{equation}
a=\frac{v^{2}}{r}.  \label{A1}
\end{equation}%
%
%
%%% Figure 7, a uniform circular motion  %%%%
%
\begin{figure}[hbt!]
\centering
\includegraphics[width=0.45\textwidth]{figure5.pdf}
\caption{Uniform circular motion\/.}
\label{Figure5}
\end{figure}
%

Indeed, if%
\begin{equation}
\mathbf{r}=\mathbf{r}\left( t\right) =r\cos \left( \omega t\right) \mathbf{e}%
_{1}+r\sin \left( \omega t\right) \mathbf{e}_{2},\qquad \mathbf{r}\left(
0\right) =r\mathbf{e}_{1},  \label{A2}
\end{equation}%
where $\mathbf{e}_{1}$ and $\mathbf{e}_{2}$ are two orthonormal vectors
(Figure~\ref{Figure5}), then%
\begin{equation}
\mathbf{v}=\frac{d\mathbf{r}}{dt}=r\omega \left( -\sin \left( \omega
t\right) \mathbf{e}_{1}+\cos \left( \omega t\right) \mathbf{e}_{2}\right)
,\qquad \mathbf{r}\cdot \mathbf{v}=0,  \label{A3}
\end{equation}%
and%
\begin{equation}
\mathbf{a}=\frac{d\mathbf{v}}{dt}=-r\omega ^{2}\left( \cos \left( \omega
t\right) \mathbf{e}_{1}+\sin \left( \omega t\right) \mathbf{e}_{2}\right)
=-\omega ^{2}\mathbf{r}.  \label{A4}
\end{equation}%
%
Thus,%
\begin{equation}
\mathbf{v}^{2}=\mathbf{v}\cdot \mathbf{v}=r^{2}\omega ^{2}\left( \sin
^{2}\left( \omega t\right) +\cos ^{2}\left( \omega t\right) \right)
=r^{2}\omega ^{2}=v^{2},\quad v=\omega r.  \label{A5}
\end{equation}%
In a similar fashion,%
\begin{equation}
\mathbf{a}^{2}=\mathbf{a}\cdot \mathbf{a}=\omega ^{4}r^{2},\qquad a=\omega
^{2}r.  \label{A6}
\end{equation}%
Relation (\ref{A1}) follows from the last two expressions: $a=\omega ^{2}r$
and $\omega =v/r.$
%

Moreover,%
\begin{eqnarray}
\mathbf{r}\times \mathbf{v} &=&r^{2}\omega \left\vert 
\begin{array}{ccc}
\mathbf{e}_{1} & \mathbf{e}_{2} & \mathbf{e}_{3} \\ 
\cos \left( \omega t\right) & \sin \left( \omega t\right) & 0 \\ 
-\sin \left( \omega t\right) & \cos \left( \omega t\right) & 0%
\end{array}%
\right\vert  \label{A7} \\
&=&r^{2}\omega \left( \cos ^{2}\left( \omega t\right) +\sin ^{2}\left(
\omega t\right) \right) \mathbf{e}_{3}=rv\mathbf{e}_{3}  \notag
\end{eqnarray}%
(see Figure~\ref{Figure1}). Eq.~(\ref{BidSom2}) can be derived in a similar way.


