\section*{Appendix~C: An Independent Evaluation of the Sommerfeld-type
Integrals\/}\label{App:Appendixc}

On the contrary, one can use the technique of differentiation with respect to
parameters for the familiar integrals related to the Bohr--Sommerfeld
quantization rule \cite{SomAS, SomQM}. As is well known, if%
\begin{equation}
J(x) = \int_{f(x)}^{g(x)} F(x,y)\ dy,  \label{J1}
\end{equation}
then%
\begin{equation}
\frac{dJ}{dx} = \int_{f(x)}^{g(x)} \frac{\partial F(x,y)}{\partial x}\ dy 
+ F(x, g(x))\,\frac{dg}{dx} - F(x, f(x))\,\frac{df}{dx}.  \label{J2}
\end{equation}
In the WKB case, the last two terms vanish because the limits are turning points where the integrand vanishes \cite{Ghatetal}.
%\smallskip
%

%
We now apply this procedure for an independent evaluation of the
\textquotedblleft Sommerfeld-type\textquotedblright\ integrals discussed
in this note \cite{SusPuzz}. Indeed,
\begin{equation}
I = \int_{r_{1}}^{r_{2}} p(r)\ dr, \qquad 
p(r) = \sqrt{ -A + \frac{B}{r} - \frac{C}{r^{2}} } 
\quad (A, C > 0),  \label{Som1}
\end{equation}
provided $p(r_{1}) = p(r_{2}) = 0$, one finds:
\begin{eqnarray}
\frac{dI}{dB} &=& \frac{1}{2} \int_{r_{1}}^{r_{2}} \frac{dr}{\sqrt{-Ar^{2} + Br - C}}  \label{Som2} \\
&=& \frac{1}{2\sqrt{A}} \int_{r_{1}}^{r_{2}} \frac{dr}{\sqrt{ \dfrac{B^{2} - 4AC}{4A^{2}} - \left(r - \dfrac{B}{2A}\right)^{2} }}  \notag \\
&=& \frac{1}{2\sqrt{A}} \left. \arcsin \left( \frac{2Ar - B}{\sqrt{B^{2} - 4AC}} \right) \right\vert_{r_{1}}^{r_{2}} 
= \frac{\pi}{2\sqrt{A}}.  \notag
\end{eqnarray}
As a result,
\begin{equation}
\frac{dI}{dB} = \frac{\pi}{2\sqrt{A}}, \qquad 
I(B_{0} = 2\sqrt{AC}) = 0,  \label{Som3}
\end{equation}
and by integration,
\begin{equation}
I = \pi \left( \dfrac{B}{2\sqrt{A}} - \sqrt{C} \right).  \label{Som4}
\end{equation}

