\section{Solitary wave and periodic traveling wave solutions}

Having motivated the need for continuum approximations beyond the classical KdV one in the previous section, we now begin
our investigation of the two continuum models proposed in section~\ref{s:models}.
We start with the traveling wave solutions to both models \eqref{e:KdV-like PDE} and \eqref{e:BBM-like PDE}. 




%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Solitary wave solutions}
\label{s:Soliton solutions}

\paragraph{Solitary waves in the non-regularized model.}

%
For the non-regularized model \eqref{e:KdV-like PDE} 
%(as we will often refer to the KdV-like model),
we first take the following traveling-wave ansatz,
\begin{equation}
    r\left(X,T\right) = R(Z), \hspace{5mm} Z = X-cT,
    \label{Traveling-wave ansatz}
\end{equation}
where $c \in \mathbb{R}$ denotes the propagation speed of the solitary wave.
%
Substituting the ansatz \eqref{Traveling-wave ansatz} into the continuum PDE \eqref{e:KdV-like PDE} yields
\begin{equation}
    -cR_Z + \frac{2\sqrt{p}}{p+1}\left(R^{\frac{p+1}2}\right)_Z + \frac{\sqrt{p}\epsilon^2}{12\left(p+1\right)}\left(R^{\frac{p+1}2}\right)_{ZZZ} = 0.
    \label{Traveling-wave ODE}
\end{equation}
We then apply the change of variables $v = R^{\frac{p+1}2}$, and integrate the ODE \eqref{Traveling-wave ODE} twice to obtain that
\begin{equation}
    \frac{\sqrt{p}\epsilon^2}{24\left(p+1\right)}\left(v_Z\right)^2 = -\frac{\sqrt{p}}{p+1}v^2 + \frac{c\left(p+1\right)}{p+3}v^{\frac{p+3}{p+1}} + Av + B.
    \label{final TW ODE}
\end{equation}
where $A, B$ are two constants of integration.
%
We then compute the associated traveling solitary solutions on a zero background. 
To this end, we require that $\lim_{Z\to\pm\infty} = 0$ so that $A = B = 0$ and hence Eq.~\eqref{final TW ODE} now becomes
\begin{equation}
    \frac{\sqrt{p}\epsilon^2}{24\left(p+1\right)}\left(v_Z\right)^2 = -\frac{\sqrt{p}}{p+1}v^2 + \frac{c\left(p+1\right)}{p+3}v^{\frac{p+3}{p+1}}.
    \label{traveling soliton ODE}
\end{equation}
We notice that the co-traveling frame ODE \eqref{traveling soliton ODE} does not always admit an analytical solution, 
%
However, for some specific cases of $p$ including $p = 3, 2, \frac{3}2$, the analytical solutions exist and are given as follows,
\bse
\begin{align}
    &R_{p = 3}\left(Z\right) = -\frac{a_3}{2a_2}\left[\sin\left(\frac{\sqrt{-a_2}}{\sqrt{4a_1}}\left(Z - Z_0\right)\right) + 1\right],
    \label{e:TW solution for p = 3}\\
    &R_{p = 2}\left(Z\right) = \left(\frac{a_3}{2a_2}\right)^2\left[\sin\left(\frac{\sqrt{-a_2}}{\sqrt{\widetilde{a}_1}}\left(Z-Z_0\right)\right) + 1\right]^2,\label{e:TW solution for p = 2}\\
    &R_{p = \frac{3}2}\left(Z\right) = \left(\frac{a_3}{2a_2}\right)^{4}\left[\sin\left(\frac{\sqrt{-a_2}}{2\sqrt{\widetilde{a}_{1}}}\left(Z - Z_0\right)\right) + 1\right]^{4},
    \label{e:TW solution for p = 1.5}  
\end{align}
\ese
where $a_1 = {\sqrt{p}\epsilon^2}/[{24\left(p+1\right)}]$, $ \widetilde{a}_1 = (p+1)^2a_1$, $a_2 = -\sqrt{p}/(p + 1)$, and $a_3 = c(p+1)/(p+3)$. 
It is important to note that these are not solitary but rather periodic 
wave solutions, as constructed.
Hence, when referring to solitary waves here, we mean them in a similar way 
to earlier works such as~\cite{Nester2001,Ahnert_2009}, where a single interval
of positive values between two zeros
of the periodic solution is ``glued'' with zeros on both sides to constitute
an approximation to the relevant solitary wave.


\paragraph{Solitary waves in the regularized model.}

%
We now turn to the derivation of the solitary waves of the regularized continuum model \eqref{e:BBM-like PDE}. 
Similarly to before, we substitute the ansatz \eqref{Traveling-wave ansatz} into~\eqref{e:BBM-like PDE} and integrate the resulting ODE twice to obtain that
\begin{equation}\label{e:Traveling ODE}
    \frac{\epsilon^2c}{24}\left(R'\right)^2 = cR^2 - \frac{8\sqrt{p}}{\left(p+1\right)\left(p+3\right)}R^{\frac{p+3}2} + 2DR + E,
\end{equation}
where $D, E$ are two constants of integration. 

We then introduce the change of dependent variable $R = \phi^2$ and insert it into the Eq.~\eqref{e:Traveling ODE} to obtain that,
\begin{equation}\label{e:BBM traveling ode}
    \frac{\epsilon^2c}{6}\phi^2\left(\phi'\right)^2 = c\phi^{4} - \frac{8\sqrt{p}}{\left(p+1\right)\left(p+3\right)}\phi^{p+3}+2a\phi^2 + b.
\end{equation}
To compute the solitary wave on the zero background, we set $D = E = 0$, and then integrating Eq.~\eqref{e:BBM traveling ode} yields
\begin{equation}
    \phi\left(Z\right) = \left(\frac{c\left(p+1\right)\left(p+3\right)}{8\sqrt{p}}\right)^{\frac{1}{p-1}}\text{sech}^{\frac2{p-1}}\left(\frac{\sqrt{6}\left(p-1\right)}{2\epsilon}\left(Z-Z_0\right)\right),
\end{equation}
where $Z_0$ is a constant of integration. Finally, we recall that since $R = \phi^2$, the traveling solitary wave solutions read,
\begin{equation}\label{e:Traveling wave solutions}
    R\left(Z\right) = \left(\frac{c\left(p+1\right)\left(p+3\right)}{8\sqrt{p}}\right)^{\frac2{p-1}}\text{sech}^{\frac{4}{p-1}}\left(\frac{\sqrt{6}\left(p-1\right)}{2\epsilon}\left(Z-Z_0\right)\right).
\end{equation}


