%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{DSW fitting}
\label{s:DSW fitting}

In this section we apply the so-called DSW fitting method \cite{El_2005} to characterize the leading and trailing edges of the dispersive shock waves.
%
We first perform DSW fitting on the two continuum models~\eqref{e:KdV-like PDE} and \eqref{e:BBM-like PDE}, and finally on the discrete granular chain \eqref{Granular Crystals}. 



\paragraph{Non-regularized model.}

%
For the non-regularized model~\eqref{e:KdV-like PDE}
we solve~\eqref{e:DSW fitting BVP} with $\Omega_0$ given by~\eqref{e:final LDR}.
This yields
\begin{equation}
    \overline{r} = r^+\left(\frac{1}{1-\frac{1}{24}\epsilon^2K^2}\right)^{\frac{3}{p-1}}, \qquad
    \overline{r} = r^-\left(\frac{1}{1 + \frac{1}{24}\epsilon^2\widetilde{K}^2}\right)^{\frac{3}{p-1}}.
\end{equation}
Then, we notice that the trailing-edge wavenumber $K^{-}$ and the leading-edge conjugate wavenumber $\widetilde{K}^{+}$ are simply obtained as $K^{-} = K(r^{-})$ and $\widetilde{K}^{+} = \widetilde{K}(r^{+})$. 
%
Namely,
\begin{equation}
    K^- = \frac{\sqrt{24\left(1 - (r^-/r^+)^{\frac{1-p}{3}}\right)}}{\epsilon}, \qquad
    \widetilde{K}^+ = \frac{\sqrt{24\left((r^+/r^-)^{\frac{1-p}{3}}-1\right)}}{\epsilon}
\end{equation}
Furthermore, the trailing and leading-edge velocities, denoted respectively as $s^-$ and $s^+$, are obtained as the phase and group velocities ($\widetilde\Omega_s/\widetilde{K}$ and
$\partial\Omega_0/\partial K$), respectively. Namely, 
%
\bse
\begin{align}
    s^- &= \frac{\partial \Omega_0}{\partial K}\left(r^-, K^-\right) = \sqrt{p}\left(r^-\right)^{\frac{p-1}2}\left(1 - \frac{1}{8}\epsilon^2\left(K^-\right)^2\right),
    \label{e:non-reg trailing-edge speed}\\
    s^+ &= \frac{\widetilde\Omega_s}{\widetilde{K}}\left(r^+, \widetilde{K}^+\right) = \sqrt{p}\left(r^+\right)^{\frac{p-1}2}\left(1 + \frac{1}{24}\epsilon^2\left(\widetilde{K}^+\right)^2\right).\label{e:non-reg leading-edge speed}
\end{align}
\ese



\paragraph{Regularized model.}

%
For the regularized model~\eqref{e:BBM-like PDE}
we solve~\eqref{e:DSW fitting BVP} with $\Omega_0$ given by~\eqref{eq:LDR for BBM}.
This yields
\bse
\label{e:DSW fitting regularized system}
\begin{align}
    \log\left|\frac{\overline{r}}{r^+}\right| &= \frac2{p-1}\left(\frac{\epsilon^2K^2}{48} + \log\left(1 + \frac{\epsilon^2K^2}{24}\right)\right),\label{e:solution to BV1}\\
    \log\left|\frac{\overline{r}}{r^-}\right| &= \frac2{p-1}\left(-\frac{\epsilon^2\widetilde{K}^2}{48} + \log\left|1 - \frac{\epsilon^2\widetilde{K}^2}{24}\right|\right).\label{e:solution to BV2}
\end{align}
\ese
Furthermore, the trailing and leading edge speeds are given by,
\bse
\begin{align}
    s^- &= \frac{\partial \Omega_0}{\partial K}\left(r^-,K^-\right) = \frac{\sqrt{p}\left(r^-\right)^{\frac{p-1}2}\left(1 - \frac{\epsilon^2\left(K^-\right)^2}{24}\right)}{\left(1 + \frac{\epsilon^2\left(K^-\right)^2}{24}\right)^2},\label{e:reg trailing edge speed}\\
    s^+ &= \frac{\widetilde\Omega_s}{\widetilde{K}}\left(r^+,\widetilde{K}^+\right)= \frac{\sqrt{p}\left(r^+\right)^{\frac{p-1}2}}{1 - \frac{\epsilon^2\left(\widetilde{K}^+\right)^2}{24}}.\label{e:reg leading edge speed}
\end{align}
\ese
where again $K^-$ and $\widetilde{K}^+$ are the trailing-edge wavenumber and leading-edge conjugate wavenumbers which can be numerically obtained by solving~\eqref{e:solution to BV1} and \eqref{e:solution to BV2} for $K$ and $\widetilde{K}$, respectively.


\paragraph{Discrete granular lattice.}
%
We can also apply the DSW fitting to the discrete granular lattice model~\eqref{Granular Crystals}. Modulation equations for a general class of FPUT equations are given in \cite{DHM06}.
Once again, we obtain two boundary value problems, which are similar to~\eqref{e:DSW fitting BVP} but with $K$ being replaced by $k$ (where $K = \epsilon k)$,
\bse
\label{e:DSW lattice BVPs}
\begin{align}
    \frac{dk}{d\overline{r}} &= \frac{\partial\omega_0/\partial\overline{r}}{V\big(\overline{r}\big) - \partial\omega_0/\partial k},\qquad 
    k\left(r^+\right) = 0\label{e:bvp 1 for discrete lattice}\\
    \frac{d\widetilde{k}}{d\overline{r}} &= \frac{\partial\widetilde\Omega_s/\partial\overline{r}}{V\big(\overline{r}\big) - \partial\widetilde\Omega_s/\partial \widetilde{k}},\qquad
    \widetilde{k}\left(r^-\right) = 0,
    \label{e:bvp 2 for discrete lattice}  
\end{align}
\ese
where $\omega_0$ denotes the linear dispersion relation~\eqref{e:linearized DR of DDE}, and $\widetilde\Omega_s$ the conjugate dispersion relation defined as
\begin{equation}
\label{e:conjugate dr for lattice}
    \widetilde\Omega_s\left(\overline{r},\widetilde{k}\right) = -i\omega_0\left(\overline{r},i\widetilde{k}\right) = 2p^{\frac{1}2}\big(\overline{r}\big)^{\frac{p-1}2}\sinh(\widetilde{k}/2),
\end{equation}
with $V(\overline{r}) = \sqrt{p}\,\overline{r}^{\frac{p-1}2}$.
%
Solving the two boundary value problems in~\eqref{e:DSW lattice BVPs} yields
%
\begin{equation}
    \label{DDE dsw s_minus} 
    k^- = 4\arc\sec\big[(r^-/r^+)^{\frac{p-1}{4}}\big],
    \quad
    \widetilde{k}^+ = 4\arc\sech\big[(r^+/r^-)^{\frac{p-1}{4}}\big],
\end{equation}
and the associated two edge speeds then read
\bse
\begin{align}
    s^-_{\text{DDE}} &= \frac{\partial\omega_0}{\partial k}\left(r^-, k^-\right) = p^{\frac{1}2}\left(r^-\right)^{\frac{p-1}2}\left(2(r^+/r^-)^{\frac{p-1}2} - 1\right),\label{e:lattice s_minus}\\
    s^+_{\text{DDE}} &= \frac{\widetilde\Omega_s}{\widetilde{k}}\left(r^+,\widetilde{k}^+\right) = \frac{4p^{\frac{1}2}\left(r^+\right)^{\frac{p-1}2}(r^-/r^+)^{\frac{p-1}{4}}\sqrt{(r^-/r^+)^{\frac{p-1}2}-1}}{\widetilde{k}^+}. \label{e:lattice s_plus}
\end{align}
\ese





\section{Numerical validation}
\label{s:numerics}

In this section we report on the results of systematic numerical simulations aimed at verifying the theoretical predictions presented in the previous sections.
Specifically, we numerically measure various features of the dispersive shock waves simulated from the granular lattice DDE and the two continuum models. 
These include the trailing-edge wave number and trailing and leading-edge speeds. 
Moreover, to further understand how the DSWs from each continuum model approximate the one from the granular lattice, we also compare the spatial profile of the DSWs of the two continuum models with that of the granular lattice. 


