	\title{\Large \textbf{Gravitational radiation at infinity  with\\ negative cosmological constant and AdS$_4$ holography}}
	\author[]{Francisco Fernández-Álvarez\thanks{francisco.fernandez@ehu.eus}\ }
	\author[]{\ José M. M. Senovilla\thanks{josemm.senovilla@ehu.eus}} 
