   \b u &=\p{ -2^{10} x^2 (1-x)^2 y^2 (1-y)^2 ( z -3 z^2 + 2z^3 )\qquad \\ \\
           \ \,2^{10} x^2 (1-x)^2 y^2 (1-y)^2 ( z -3 z^2 + 2z^3 ) \qquad \\ \\
   \ \,2^{10} \Big(( x -3 x^2 + 2x^3 )(y-y^2)^2 \qquad\qquad\qquad\\
       - (x-x^2)^2( y -3 x^2 + 2 x^3 )\Big) (z-z^2)^2 }, \\ 
    p&=10(3y^2-2y^3-y).   }
}

