\end{figure}

\medskip

\begin{theorem} \label{thm:law_of_iprime}
Fix an integer $m \ge 1$ and set $N=2^{m-1}$.
Let $i$ denote the integration time index selected by the exact biased progressive sampling procedure with uniform weights. Then $i$ follows the symmetric discrete triangular law:
\begin{equation} \label{eq:pmf_of_ip}
\Pr\bigl[i=k\bigr] \ = \ 
\frac{1}{2N^{2}} \, \min( |k|, 2N-|k|) \; \mathbf{1}\{1 \le |k| \le 2 N-1 \}
\end{equation}
for $k \in (1-2N){:}(2N-1)$.
\end{theorem}


\begin{proof}
At each doubling step ($k=0,\dots,m-1$), the Bernoulli variable $B_{k+1}$ indicates whether the  extension orbit $\calO_{k}^{\ext}$ of length $2^{k}$ is appended to the right ($B_{k+1}=1$) or to the left ($B_{k+1}=0$) of the current orbit $\calO_{k}$. In the final doubling step, the orbit $\calO_{m-1}$ has length  $N=2^{m-1}$ with right endpoint index: \[
 b_{m-1} = \sum_{j=1}^{m-1} B_{j} \; 2^{j-1}  \;.
\] which implies $b_{m-1} \sim \Unif(0{:}(N-1))$.  The corresponding left endpoint index is $a_{m-1} = b_{m-1} - N + 1$.

The final bit $B_m$ determines whether the last extension of length $N$ is appended to the right or left:
  \begin{itemize}
    \item If $B_m=1$, then $a_{m-1}^{\ext} = b_{m-1}+1$ and $b_{m-1}^{\ext} = b_{m-1}+N$. 
    \item If $B_m=0$, then $a_{m-1}^{\ext} = a_{m-1}-N$ and $b_{m-1}^{\ext} = a_{m-1} -1$.
\end{itemize}
The  index $i$ is then sampled uniformly from this extension. Let $c \sim \text{Uniform}(1{:}N)$, independent of all previous random variables. Then \begin{align*}
i &= (b_{m-1}+c) B_m + (a_{m-1}-c) (1-B_m) ,  \\
&= (b_{m-1} + c) \cdot B_m + (b_{m-1} - N + 1 - c) \cdot (1 - B_m),
\end{align*} where the second line uses the identity $a_{m-1} = b_{m-1} - N + 1$. This expression shows that $i$ is distributed as the convolution of two independent discrete uniform variables, yielding the symmetric triangular PMF given in the theorem.
\end{proof}

The following corollary computes the expected magnitude of the integration time index under this distribution, providing a simple benchmark for the typical integration time in this idealized setting.

\medskip

\begin{corollary} \label{cor:stats_of_iprime}
It holds that $\mathbb{E}[\,|i|\,]=2^{m-1}$.
\end{corollary}


\begin{proof}
    From Theorem~\ref{thm:law_of_iprime}, the magnitude $|i|$ has the triangular PMF: \[
    \Pr[|i| = k] \ = \  \frac{1}{N^2} \, \min(k, 2 N - k)
    \] for $k \in 1{:}(2N-1)$.  By expanding the expectation using this PMF, and then re-indexing, \begin{align*}
    E[|i|] &= \sum_{k=1}^{2N-1}  k \Pr[|i|=k] = \frac{1}{N^2} \sum_{k=1}^{2N-1}  k \min(k,2 N-k) \\
    &= \frac{1}{N^2} \left( \sum_{k=1}^N k^2 + \sum_{k=N+1}^{2N-1} k (2 N-k) \right)  \\
    &= \frac{1}{N^2} \left( \sum_{k=1}^N k^2 + \sum_{k=1}^{N-1} (k+N) (N-k) \right)  = N
    \end{align*} as required.
\end{proof}

Next, we describe how the orbit length can be locally adapted without breaking reversibility using a geometric stopping rule based on a U-turn condition.

\subsection{Locally Adaptive Path Length with The No-U-Turn Sampler}

\label{sec:short_overview_nuts}

The key innovation of the No-U-Turn Sampler (NUTS) is to locally adapt the orbit length, and thus integration time,  by terminating the doubling procedure in biased progressive HMC when a U-turn condition is met (see Figure~\ref{fig:uturn-condition}).  

\medskip

\begin{definition} \label{defn:u-turn}
An orbit $\calO\ =\ ((\theta_a, \rho_a), \dots, (\theta_b,\rho_b))$ satisfies the \emph{U-turn condition} if: 
\begin{equation}\label{eq:u-turn}
    \min\bigr(\rho_a \cdot M^{-1} (\theta_b-\theta_a),\,\rho_b \cdot M^{-1} (\theta_b-\theta_a)\bigr)\ <\ 0\;.
\end{equation} 
\end{definition}

