\end{proof}


For notational brevity, we define
\begin{align*}
    p^+_j \ &= \ p_{\micro}(\ell_{j} \mid \micro(\theta_{j},\rho_{j},\mu, M, h, \delta)) \;, \\
    p^-_j \ &= \  p_{\micro}(\ell_{j} \mid \micro(\theta_{j+1},-\rho_{j+1},\mu, M, h, \delta)) \;.
\end{align*}
And for any integers $j\leq k$, we write
\begin{align*}
    p^+_{j:k} \ &= \  p^+_j\cdot p^+_{j+1}\cdots p^+_k,  \\ 
    p^-_{j:k} \ &= \  p^-_j\cdot p^-_{j+1}\cdots p^-_k.
\end{align*}
If $j>k$, we use the convention that $p^+_{j{:}k}=1$ and $p^-_{j{:}k}=1$.

\medskip

\begin{lemma} \label{lem:orbit}
    The orbit selection kernel of WALNUTS is given by
    \begin{align*}
        p_{\orbit}(m, b, \bfell\mid \theta,\rho ) 
        =\frac{1}{2^m}\cdot p^+_{0{:}b-1} \cdot p^-_{a{:}-1}.
    \end{align*}
\end{lemma}
\begin{proof}[Proof of Lemma~\ref{lem:orbit}]
    A WALNUTS orbit is generated by first sampling a sequence of Bernoulli variables $B=(B_1,\ldots,B_{m_{\max}})$ and  micro step size factors $\{\ell_j\}_{a_{m_{\max}}\leq j < b_{m_{\max}}}$. Given $B$ and $\{\ell_j\}_{a_{m_{\max}}\leq j < b_{m_{\max}} }$, the selection of $\calO=\calO_m$ is determined deterministically by the NUTS-style doubling procedure, and one of the following conditions must hold: 
    \begin{enumerate}
        \item $\calO_m$ does not satisfy the sub-U-turn condition, but its extension $\calO_m^{\ext}$ does;
        \item $\calO_m$ satisfies the U-turn condition, but none of its sub-orbits do;
        \item The maximum number of doublings is reached, i.e., $m=m_{\max}$.
    \end{enumerate}
    Let us write this deterministic selection as $\calO_m = \text{NUTS} (B, \{\ell_j\}_{a_{m_{\max}}\leq j < b_{m_{\max}} })$.
    Then, the probability of selecting orbit $\calO_m$ is
    \begin{align*}
        &p_\orbit(\calO_m\mid \theta,\rho ) = \sum_{B' }\sum_{\ell'} p(B') \cdot p(\ell'\mid B' )\cdot \Indc{\text{NUTS}(B',\ell' ) = \calO_m },
    \end{align*}
    where the sums range over all possible values of $ B' \in \{0,1\}^{m_{\max}} $ and $ \ell' = \{ \ell'_j \}_{a_{m_{\max}} \leq j < b_{m_{\max}}} $, and where
    \begin{align*}
        p(B') &= \frac{1}{2^{m_{\max}}},\\
        p(\ell'\mid B') &= \prod_{j=0}^{b_{\max-1} } p_\micro(\ell'_j \mid \micro(\theta'_j,\rho'_j, \mu, M, h, \delta) ) \cdot \prod_{j=a_{\max} }^{-1} p_\micro(\ell'_j \mid \micro(\theta'_{j+1}, -\rho'_{j+1}, \mu, M, h, \delta) ),
    \end{align*}
    and $(\theta'_j,\rho'_j)$ represents the $j$-th state in the orbit constructed from $B',\ell'$.

    The indicator $\Indc{\text{NUTS}(B',\ell' ) = \calO_m }$ is equal to 1 if and only if 
    \begin{align*}
        (B'_1,\ldots,B'_m)= (B_1,\ldots,B_m),\text{ and }
        \ell'_j=\ell_j \text{ for all } a_m\leq j\leq b_m-1 .
    \end{align*}
Hence, the probability of selecting $\calO_m$ is equal to the probability of matching the first $ m $ Bernoulli steps and the corresponding micro step factors:
    \begin{align*}
        \frac{1}{2^m} \cdot \prod_{j=0}^{b_m-1} p_\micro(\ell_j\mid \micro(\theta_j,\rho_j, \delta)) \cdot \prod_{j=a_m}^{-1} p_\micro(\ell_j\mid \micro(\theta_{j+1}, -\rho_{j+1}, \delta) ) = \frac{1}{2^m} \cdot p^+_{0:b-1} \cdot p^-_{a:-1}.
    \end{align*}
\end{proof}

\begin{lemma} \label{lem:mn}
    The index selection kernel for multinomial sampling is given by
    \begin{align*}
        p_{\ind}^{\mn}(j\mid \theta,\rho, \calO ) = \frac{e^{-H(\theta_j,\rho_j)}}{Z(\theta, \rho, \calO)}  \cdot \begin{cases}
             \dfrac{p^-_{0:j-1}} {p^+_{0:j-1} } & 0\leq j\leq b\\
             \dfrac{p^+_{j:-1}}{p^-_{j:-1}} & a\leq j < 0\\
        \end{cases}
    \end{align*}
    where the normalizing constant is given by
    \begin{align*}
        Z(\theta,\rho,\calO) = \sum_{j=0}^b e^{-H(\theta_j,\rho_j)} \frac{p^-_{0:j-1}} {p^+_{0:j-1} } + \sum_{j=a}^{-1} e^{-H(\theta_j,\rho_j)} \frac{p^+_{j:-1}}{p^-_{j:-1}}.
    \end{align*}
\end{lemma}
Lemma~\ref{lem:mn} follows directly from the definitions of $p_{\ind}^{\mn}$ in \eqref{eq:p_ind_mn} and the weights $w_j$ in \eqref{eq:w0}, \eqref{eq:wts-forw} and \eqref{eq:wts-backw}.

\medskip

\begin{lemma}\label{lem: p joint mn}
The extended target density with multinomial sampling is invariant under $\Psi$ in \eqref{eq:walnuts-inv}, i.e., $p_\joint^\mn\circ\Psi=p_\joint^\mn$.
\end{lemma}
\begin{proof}
The case $i=0$ is trivial, as $\Psi$ is the identity.  We therefore assume $i > 0$; the case $i < 0$ is analogous and omitted. By Lemmas~\ref{lem:orbit} and~\ref{lem:mn}, the extended target evaluated at $z$ satisfies:
\begin{align}
    p_{\joint}^\mn(z) \ &\propto \  e^{-H(\theta,\rho)} \cdot 
    \frac{1}{2^m} p^+_{0{:}b-1} p^-_{a{:}-1}\cdot
    \frac{1}{Z(\theta,\rho,\calO)} e^{-H(\theta_i,\rho_i)} \frac{p^-_{0:i-1}} {p^+_{0:i-1} } \nonumber \\
   \  &\propto \ e^{-H(\theta,\rho) - H(\theta_i,\rho_i)} \frac{1}{2^m} p^-_{a:i-1} p^+_{i:b-1} \frac{1}{Z(\theta,\rho,\calO)} \;. \label{eq:pmn_z}
\end{align}
Now consider the transformed point $z' = \Psi(z)$, which shifts the proposal index $i$ to $0$ and the initial index $0$ to $-i$, and reindexes the micro step size factors via the shift operator: $\shift^i \bfell$ satisfies $(\shift^i \bfell)_j = \ell_{j - i}$. Thus, micro step factors and integration times in the reverse orbit are properly aligned,  and hence, we simply write: $(\theta_i,\rho_i,\calO ) = (\theta_i, \rho_i, m, \shift^i \bfell, b-i)$ which corresponds to the same orbit now viewed from the new initial point $(\theta_i, \rho_i)$. Evaluating the extended target at $z'$ yields:
\begin{align}
    p_{\joint}^\mn(z')
   \  &\propto \  e^{-H(\theta_i,\rho_i)} \cdot \frac{1}{2^m} p^+_{i:b-1}  p^-_{a:i-1} \cdot \frac{1}{Z(\theta_i,\rho_i,\calO )}  e^{-H(\theta,\rho)} \frac{ p^+_{0:i-1} }{p^-_{0:i-1} } \nonumber \\
   \  &\propto \  e^{-H(\theta,\rho) - H(\theta_i,\rho_i)} \frac{1}{2^m}p^-_{a:-1} p^+_{0:b-1}  \frac{1}{Z(\theta_i,\rho_i,\calO )} \;. \label{eq:pmn_zp}
\end{align}
Comparing \eqref{eq:pmn_z} to \eqref{eq:pmn_zp}, to prove $p_\joint^\mn(z') = p_\joint^\mn(z)$, it suffices to show
\begin{align} \label{eq:Z_identity}
   Z(\theta_i,\rho_i,\calO) \cdot p^-_{0:i-1} \ = \  Z(\theta,\rho,\calO) \cdot p^+_{0:i-1} \;.
\end{align}

Let $\mu_j := e^{-H(\theta_j, \rho_j)}$ denote the unnormalized weight at index $j$. We first expand $Z(\theta, \rho, \calO)$:
\begin{align*}
    Z(\theta,\rho,\calO)\cdot p^+_{0:i-1} &= \Big(\sum_{j=0}^b \mu_j \frac{p^-_{0:j-1}} {p^+_{0:j-1} } + \sum_{j=a}^{-1} \mu_j \frac{p^+_{j:-1}}{p^-_{j:-1}} \Big) \cdot p^+_{0:i-1}  \\ 
     &=\sum_{j=0}^i \mu_j p^-_{0:j-1} p^+_{j:i-1} + \sum_{j=i+1}^b \mu_j \frac{p^-_{0:j-1}}{p^+_{i:j-1}}  + \sum_{j=a}^{-1} \mu_j \frac{p^+_{j:i-1}}{p^-_{j:-1}} \\
    &=\sum_{j=0}^{i-1} \mu_j p^-_{0:j-1} p^+_{j:i-1} + \sum_{j=i}^b \mu_j \frac{p^-_{0:j-1}}{p^+_{i:j-1}}  + \sum_{j=a}^{-1} \mu_j \frac{p^+_{j:i-1}}{p^-_{j:-1}}.\numberthis\label{eq:Ztheta}
\end{align*}
Here we used that $p^+_{j{:}k}=1$ and $p^-_{j{:}k}=1$, if $j>k$.
Next, we expand $Z(\theta_i, \rho_i, \calO)$:
\begin{align*}
    Z(\theta_i,\rho_i,\calO)\cdot p^-_{0:i-1} &= \Big( \sum_{j=i}^b \mu_j  \frac{p^-_{i:j-1}}{p^+_{i:j-1}} + \sum_{j=a}^{i-1} \mu_j  \frac{p^+_{j:i-1}}{p^-_{j:i-1}} \Big) \cdot  p^-_{0:i-1} \\
    &=\sum_{j=i}^b \mu_j \frac{p^-_{0:j-1}}{p^+_{i:j-1}} + \sum_{j=0}^{i-1}\mu_j p^-_{0:j-1}p^+_{j:i-1} +  \sum_{j=a}^{-1} \mu_j \frac{p^+_{j:i-1}}{p^-_{j:-1}}.
    \numberthis\label{eq:Zthetaprime}
\end{align*}
The right-hand sides of \eqref{eq:Ztheta} and \eqref{eq:Zthetaprime} are identical term-by-term. Therefore, \eqref{eq:Z_identity} holds, and the invariance $p_\joint^\mn \circ \Psi = p_\joint^\mn$ follows. \end{proof}

Lemmas~\ref{lem:measure-preserving-involution-Psi} and~\ref{lem: p joint mn} verify the conditions of Theorem~\ref{thm:AVM_reversibility} in the case of WALNUTS with multinomial integration time sampling. Consequently, the associated transition kernel is reversible. We do not state this as a separate theorem, however, since our primary focus is on WALNUTS with biased progressive sampling.

The following result is key to understanding why WALNUTS, like biased progressive HMC and NUTS, always accepts the proposed next state without the need for a Metropolis correction. In the GIST framework (Section~\ref{sec:gist}), the acceptance probability for transitioning from one extended state to another is determined by a Metropolis ratio of extended target densities. Lemma~\ref{lem: p joint bp} shows that this Metropolis ratio is always equal to one, thereby ensuring automatic acceptance and preserving detailed balance without the need to explicitly compute an acceptance probability.

\medskip
\begin{lemma}\label{lem: p joint bp}
The extended target density with biased progressive sampling in \eqref{eq:walnuts-joint} is invariant under $\Psi$ in \eqref{eq:walnuts-inv}, i.e.,  $p_\joint^{\bp}\circ\Psi=p_\joint^{\bp}$.
\end{lemma}
\begin{proof}

The proof is by induction on the number of doublings $m$. For the base case $m=1$, assume $a=0$, $b=1$, and $i=1$. The claim for $i=0$ is trivial, and the proof for $a=-1$, $b=0$ follows by symmetry.  The orbit consists of two states, $(\theta_0,\rho_0)$ and $(\theta_1,\rho_1)$, and the orbit and index selection kernels under biased progressive sampling are:
\begin{align*}
    &p_\orbit(m,b,\ell_0 \mid\theta_0,\rho_0 ) =\frac12 p^+_0, \quad p_\orbit(m,b-1,\ell_0 \mid\theta_1,\rho_1 ) =\frac12 p^-_0,\\
    &p_\ind^{\bp}(1\mid \theta_0, \rho_0, \calO ) = \min(1, \frac{e^{-H(\theta_1,\rho_1)} \frac{p^-_0}{p^+_0} } {e^{-H(\theta_0,\rho_0)}} ), \quad
    p_\ind^{\bp}(-1\mid \theta_1, \rho_1, \calO ) = \min(1, \frac{e^{-H(\theta_0,\rho_0)} \frac{p^+_0}{p^-_0} } {e^{-H(\theta_1,\rho_1)}} ).
\end{align*}
Thus, the extended target evaluated at $z = (\theta, \rho, m, b, \bfell, i) = (\theta,\rho,1,1,\ell_0,1)$ is
\begin{align*}
    p_\joint^\bp(\theta,\rho,1,1,\ell_0,1)&\propto e^{-H(\theta_0,\rho_0)} \cdot p^+_0 \cdot \min(1, \frac{e^{-H(\theta_1,\rho_1)} \frac{p^-_0}{p^+_0} } {e^{-H(\theta_0,\rho_0)}} )\\
    &= \min(e^{-H(\theta_0,\rho_0)}\cdot p^+_0,\; e^{-H(\theta_1,\rho_1)} \cdot p^-_0 ).
\end{align*}
Similarly, the extended target evaluated at $z' = \Psi(z)$ is
\begin{align*}
    p_\joint^\bp(\theta_1,\rho_1,1,0,\ell_0,-1)&\propto e^{-H(\theta_1,\rho_1)} \cdot p^-_0 \cdot \min(1, \frac{e^{-H(\theta_0,\rho_0)} \frac{p^+_0}{p^-_0} } {e^{-H(\theta_1,\rho_1)}} )\\
    &= \min(e^{-H(\theta_0,\rho_0)}\cdot p^+_0,\; e^{-H(\theta_1,\rho_1)} \cdot p^-_0 ).
\end{align*}
This confirms that the extended target is invariant under $\Psi$ when the orbit contains two states.

Assume that the claim is true when $\calO$ has size $2,2^2,\ldots,2^{m}$. We now prove it holds when $\calO$ has size $2^{m+1}$. There are two cases depending on whether $(\theta_i,\rho_i)$ belongs to $\calO_m^\ext$ or $\calO_{m}$.
\begin{description}
   \item[Case 1: $(\theta_i, \rho_i) \in \calO_m^\ext$.]
    By \eqref{eq:p_ind_bp}, the probability of choosing $i$ under biased progressive sampling is
    \begin{align*}
        p_\ind^{\bp}(i\mid \theta_0,\rho_0, \calO_{m+1}) &= 
        \alpha(\calW_m, \calW_m^{\ext}) \cdot \frac{w_i}{\sum \calW_m^{\ext}} 
        \\
        &=\alpha(\calW_m, \calW_m^{\ext}) \cdot \frac{w_i}{\sum  \calW_{m+1}}    \frac{\sum \calW_{m+1} }{\sum  \calW^\ext_m }\\
        &=\alpha(\calW_m, \calW_m^{\ext}) \cdot p_{\ind}^\mn(i\mid \theta_0,\rho_0,\calO_{m+1} ) \cdot \frac{\sum \calW_{m+1} }{ \sum  \calW^\ext_m } \\
        &= p_{\ind}^\mn(i\mid \theta_0,\rho_0,\calO_{m+1} ) \cdot \min\left(\frac{1}{\sum  \calW^\ext_m}, \frac{1}{\sum \calW_m} \right) \cdot \sum \calW_{m+1}.
    \end{align*}
    Thus,
    \begin{align*}
        &p_\joint^\bp(\theta_0,\rho_0,m,b,\bfell,i) \\
        &\qquad \propto e^{-H(\theta_0,\rho_0)}\cdot p_\orbit(m,b,\bfell\mid\theta_0,\rho_0) \cdot p_{\ind}^\mn(i\mid \theta_0,\rho_0,\calO_{m+1}) \cdot \min\left(\frac{1}{\sum  \calW^\ext_m}, \frac{1}{\sum \calW_m} \right) \cdot \sum \calW_{m+1} \\
        &\qquad \propto p_{\joint}^\mn(\theta_0,\rho_0, \calO_{m+1}, i) \cdot \min\left(\frac{1}{\sum  \calW^\ext_m}, \frac{1}{\sum \calW_m} \right) \cdot \sum \calW_{m+1}.
    \end{align*}

Similarly, for the transformed point:
    \begin{align*}
        p_\ind^{\bp}(-i\mid \theta_i,\rho_i, \calO_{m+1}) &= p_{\ind}^\mn(-i\mid \theta_i,\rho_i,\calO_{m+1}) \cdot \min\left(\frac{1}{\sum  \calW^\ext_m}, \frac{1}{\sum \calW_m} \right) \cdot \sum \calW_{m+1}.
    \end{align*}
    and
    \begin{align*}
        &p_\joint^\bp(\theta_i,\rho_i,m,b,\bfell,-i)  = p_{\joint}^\mn(\theta_i,\rho_i, \calO, -i) \cdot \min\left(\frac{1}{\sum  \calW^\ext_m}, \frac{1}{\sum \calW_m} \right) \cdot \sum \calW_{m+1}.
    \end{align*}
    By Lemma~\ref{lem: p joint mn}, we have
    \begin{align*}
         p_{\joint}^\mn(\theta_0,\rho_0, \calO, i)=p_\joint^\mn(\theta_i,\rho_i,\calO,-i),
    \end{align*}
    and hence, $p_{\joint}^\bp(\theta_0,\rho_0, \calO, i)=p_\joint^\bp(\theta_i,\rho_i,\calO,-i)$.  This concludes the proof for the case $(\theta_i,\rho_i)\in\calO_m^\ext$.

    \item[Case 2: $(\theta_i, \rho_i) \in \calO_m$.]  By \eqref{eq:p_ind_bp}, we have
    \begin{align*}
        p_\ind^{\bp}(i\mid \theta_0,\rho_0,\calO_{m+1})=(1 - \alpha(\calW_m, \calW_m^{\ext}) ) \cdot p_\ind^{\bp}(i\mid\theta_0,\rho_0,\calO_{m}).
    \end{align*}

    Applying the induction hypothesis to $\calO_m$ gives
    \begin{align*}
        e^{-H(\theta,\rho)}\cdot p_{\orbit}(\calO_m\mid\theta,\rho)\cdot p_\ind^{\bp}(i\mid\theta,\rho,\calO_m)=e^{-H(\theta_i,\rho_i)}\cdot p_{\orbit}(\calO_m\mid\theta_i,\rho_i)\cdot p_\ind^{\bp}(-i\mid\theta_i,\rho_i,\calO_m).
    \end{align*}

Suppose $\calO_m^\ext$ is the right half of $\calO_{m+1}$, and let $b_m$ be the rightmost index of $\calO_m$.
(The argument for the other direction is the same.) Then we have
    \begin{align*}
        p_\orbit(\calO_{m+1} \mid\theta,\rho) &=\frac12 p_{\orbit}(\calO_m\mid\theta,\rho) \cdot \prod_{j=b_m}^{j=b_{m+1} - 1} p^+_j,\\
        p_\orbit(\calO_{m+1} \mid\theta_i,\rho_i) &=\frac12 p_{\orbit}(\calO_m \mid\theta_i,\rho_i) \cdot \prod_{j=b_m}^{j=b_{m+1} - 1} p^+_j.
    \end{align*}
Combining these identities confirms that
\[
    p_\joint^\bp(\theta, \rho, \calO_{m+1}, i) = p_\joint^\bp(\theta_i, \rho_i, \calO_{m+1}, -i).
\]
\end{description}
\end{proof}


Lemmas~\ref{lem:measure-preserving-involution-Psi} and~\ref{lem: p joint bp} verify the conditions of Theorem~\ref{thm:AVM_reversibility} for WALNUTS with biased progressive integration time sampling. As a result, the following reversibility result holds.

\medskip

\begin{theorem}
\label{thm:walnuts}
The WALNUTS transition kernel is reversible with respect to the target distribution~$\mu$.
\end{theorem}



\subsection{Pseudocode Implementation of WALNUTS}


WALNUTS requires the following inputs: an unnormalized target density $\mu$, a mass matrix $M$, a macro step size $h > 0$, a maximum number of doublings $m_{\max}$, and a leapfrog energy error threshold $\delta > 0$. The probability distribution $p_{\micro}$, which governs the sampling of micro step size reduction factors, is defined internally in terms of the output of the \texttt{micro} subroutine (see Listing~\ref{algo:micro_lf}).  Complete pseudocode for all components is summarized below and detailed in Appendix~\ref{sec:pseudocode}.  We emphasize that, unlike NUTS, WALNUTS incorporates variable step size leapfrog integration as a central feature of its design.

The main WALNUTS algorithm is given in Listing~\ref{algo:WALNUTS}, which implements orbit construction and biased progressive state selection. Orbit expansion is handled by the \texttt{extend-orbit-forward} and \texttt{extend-orbit-backward} procedures (Listings~\ref{algo:extend-forward} and~\ref{algo:extend-backward}, respectively), which generate new segments of the variable step size leapfrog trajectory along with corresponding weights. The U-turn and sub-U-turn conditions used to terminate orbit growth are checked by the \texttt{U-turn} and \texttt{sub-U-turn} subroutines (Listings~\ref{algo:U-turn} and~\ref{algo:sub-U-turn}). Finally, the local step size selection is handled by the \texttt{micro} subroutine (Listing~\ref{algo:micro_lf}), which adaptively determines the number of micro steps needed to keep the energy error within the specified threshold $\delta$.




\section{Empirical Evaluations}

\label{sec:empirical}

The results and plots presented below can be reproduced using a Python implementation of WALNUTS, which is available on GitHub under a permissive open-source license.\footnote{The code is released under the MIT License and can be found at \url{https://github.com/bob-carpenter/walnuts}.}


\subsection{Setup for Numerical Experiments}
Throughout this and the following sections, unless otherwise specified, WALNUTS is run with a default micro step distribution $p_{\micro}$ defined as follows. Given a current state $(\theta, \rho) \in \mathbb{R}^{2d}$, the function call
\[
\widetilde{\ell} = \texttt{micro}(\theta, \rho, \mu, M, h, \delta)
\]
returns the smallest power of two $\widetilde{\ell} \in 2^{\mathbb{N}}$ such that the energy error of the leapfrog trajectory satisfies $H^+_{\widetilde{\ell}} - H^-_{\widetilde{\ell}} \leq \delta$, as defined in~\eqref{eq:micro}.




The \emph{randomized two-point}  distribution is then defined by:
\begin{equation} \tag{R2P}
p_{\micro}(\ell \mid \widetilde{\ell}) =
\begin{cases}
    2/3 & \text{if } \ell = \widetilde{\ell}, \\
    1/3 & \text{if } \ell = \widetilde{\ell}+1, \\
    0   & \text{otherwise}.
\end{cases}
\end{equation}
The corresponding WALNUTS method using this distribution is referred to as \emph{WALNUTS–R2P}.


In contrast, the \emph{deterministic} variant corresponds to the degenerate case:
\begin{equation} \tag{D}
p_{\text{micro}}(\ell \mid \widetilde{\ell}) = 
\begin{cases}
1 & \text{if } \ell = \widetilde{\ell}, \\
0 & \text{otherwise}.
\end{cases}
\end{equation}
The corresponding method is referred to as \emph{WALNUTS–D}.
These two variants will be compared in the numerical studies that follow.

When measuring performance in terms of gradient evaluations, both the forward and backward $\micro$-computations are counted, even though backward $\micro$-computations may be run on different a processor and thus only adding negligible (wall clock) computation time. 

To avoid the \emph{looping phenomenon}, we jitter the macro step size throughout. NUTS and WALNUTS rely on the U-turn condition to adaptively truncate their orbit lengths.  However, for certain fixed step sizes, this condition can become ineffective: the orbit selection procedure may fail to detect a U-turn and instead expand to the maximum allowed orbit length  and severely impair mixing \cite[Figure 4(a) and 5(b)]{BoOb2024}. This behavior, known as the looping phenomenon, arises from resonance between the doubling procedure and a natural frequency of the underlying Hamiltonian dynamics, causing the physical orbit length to repeatedly miss the U-turn detection range.   A simple and practical remedy is to jitter the leapfrog step size---either once per orbit or at each leapfrog step---to break this periodicity. As shown empirically, such randomization mitigates looping behavior and improves performance \cite[Figure 5(c) and 5(d)]{BoOb2024}. Throughout our experiments, we uniformly jitter the macro step size by $\pm20\%$ at each integration step.

